var NOVA_VERSION = 'v26.21.108-full-models';

/** parse userkey:uk_xxx|model  یا  userkey:uk_xxx/openai/gpt-oss-120b */
function parseUserKeyModelRef(mid) {
  mid = String(mid || '').trim();
  if (mid.indexOf('userkey:') !== 0) return null;
  var rest = mid.slice('userkey:'.length);
  var bar = rest.indexOf('|');
  if (bar > 0) {
    return { userKeyId: rest.slice(0, bar).trim(), model: rest.slice(bar + 1).trim() };
  }
  var m = rest.match(/^(uk_[a-zA-Z0-9]+)(?:[|/](.+))?$/);
  if (m) return { userKeyId: m[1], model: (m[2] || '').trim() };
  return { userKeyId: rest.trim(), model: '' };
}

function isModelIdentityQuestion(text) {
  var t = String(text || '').trim();
  return /^(چه\s*مدل|کدام\s*مدل|مدل\s*چی|مدلت\s*چیه|what\s*model|which\s*model|who\s*are\s*you|تو\s*کیه|اسم\s*مدل)/i.test(t) ||
    /چه\s*مدلی\s*(دارم|داری|هستم|هست|صحبت|حرف|چت)/i.test(t) ||
    /with\s*which\s*model/i.test(t);
}
