async function collectKeys(env, onlyUserId) {
  var provs = {};
  function add(pid, key, meta) {
    if (!key) return;
    key = String(key).trim();
    if (!key) return;
    meta = meta || {};
    var builtin = PROVIDERS[pid];
    var name = meta.name || (builtin && builtin.name) || pid;
    var base = meta.base || (builtin && builtin.base) || 'https://api.openai.com/v1';
    if (!provs[pid]) provs[pid] = { id: pid, name: name, base: base, keys: [] };
    if (meta.name) provs[pid].name = meta.name;
    if (meta.base) provs[pid].base = meta.base;
    if (provs[pid].keys.indexOf(key) === -1) provs[pid].keys.push(key);
  }

  // فقط کلیدهای شخصی یک کاربر
  if (onlyUserId && env.BOT_KV) {
    try {
      var onlyId = String(onlyUserId || '').trim();
      if (onlyId.indexOf('web:') === 0) onlyId = onlyId.slice(4);
      // web_xxx ناشناس معمولاً کلید ندارد — چند فرم uid را امتحان کن
      var candidates = [];
      function pushC(x) {
        x = String(x || '').trim();
        if (!x) return;
        if (candidates.indexOf(x) === -1) candidates.push(x);
        var low = x.toLowerCase();
        if (candidates.indexOf(low) === -1) candidates.push(low);
      }
      if (onlyId) {
        pushC(onlyId);
        if (onlyId.indexOf('tg_') === 0) pushC(onlyId.slice(3));
        else if (/^\d+$/.test(onlyId)) pushC('tg_' + onlyId);
        if (onlyId.indexOf('web_') === 0) { /* skip anonymous */ }
      }
      var uk = [];
      for (var ci = 0; ci < candidates.length && !uk.length; ci++) {
        uk = (await env.BOT_KV.get('user_keys_' + candidates[ci], 'json')) || [];
      }
      // fallback: از all_user_keys با username
      if ((!uk || !uk.length) && onlyId) {
        try {
          var allK = (await env.BOT_KV.get('all_user_keys', 'json')) || [];
          var matched = allK.filter(function (x) {
            if (!x) return false;
            var xu = String(x.uid || x.userName || '').toLowerCase();
            return xu === onlyId.toLowerCase() || xu === String(onlyUserId || '').toLowerCase();
          });
          if (matched.length) {
            uk = matched.map(function (x) {
              return {
                id: x.id,
                provider: x.provider || x.name,
                name: x.name || x.provider,
                key: x.keyFull || x.key,
                keyFull: x.keyFull || x.key,
                site: x.site || x.base || '',
                base: x.base || x.site || ''
              };
            });
          }
        } catch (eAll) {}
      }

      uk.forEach(function (c) {
        if (!c || !(c.key || c.keyFull)) return;
        var keyVal = c.key || c.keyFull;
        // c.id از قبل uk_xxx است — دوبار uk_ نساز
        var pid = String(c.id || '').trim();
        if (!pid || pid.indexOf('uk_') !== 0) {
          pid = 'uk_' + String(c.id || c.provider || c.name || 'custom').replace(/^uk_/, '').replace(/[^a-zA-Z0-9_\-]/g, '_').slice(0, 40);
        }
        var normB = normalizeUserKeyBase(c.site || c.base || c.url, keyVal, c.name || c.provider);
        var base = normB.base || 'https://openrouter.ai/api/v1';
        var meta = {
          name: (normB.provider || c.name || c.provider || 'کلید من') + ' (کلید من)',
          base: base
        };
        add(pid, keyVal, meta);
      });
    } catch (e) {}
    return provs;
  }

  var map = {
    GROQ_API_KEY: 'groq',
    GEMINI_API_KEY: 'gemini',
    OPENAI_API_KEY: 'openai',
    OPENROUTER_API_KEY: 'openrouter',
    CLEANAPIS_API_KEY: 'cleanapis',
    MODELSLAB_API_KEY: 'modelslab',
    ELEVENLABS_API_KEY: 'elevenlabs',
    XAI_API_KEY: 'xai',
    CEREBRAS_API_KEY: 'cerebras',
    TOKENHARBOR_API_KEY: 'tokenharbor',
    NVIDIA_API_KEY: 'nvidia',
    MISTRAL_API_KEY: 'mistral',
    ZAI_API_KEY: 'zai',
    OLLAMA_API_KEY: 'ollama',
    DEEPSEEK_API_KEY: 'deepseek',
    TOGETHER_API_KEY: 'together',
    FIREWORKS_API_KEY: 'fireworks',
    PERPLEXITY_API_KEY: 'perplexity',
    SAMBANOVA_API_KEY: 'sambanova',
    HF_API_KEY: 'huggingface',
    HUGGINGFACE_API_KEY: 'huggingface',
    DEEPINFRA_API_KEY: 'deepinfra',
    HYPERBOLIC_API_KEY: 'hyperbolic',
    SILICONFLOW_API_KEY: 'siliconflow',
    MOONSHOT_API_KEY: 'moonshot',
    WEATHERAI_API_KEY: 'weatherai',
    APMX_API_KEY: 'apx',
    APX_API_KEY: 'apx'
  };
  Object.keys(map).forEach(function (k) {
    if (env[k]) String(env[k]).split(',').forEach(function (x) { add(map[k], x); });
  });
  if (env.EXTERNAL_AI_KEYS) {
    String(env.EXTERNAL_AI_KEYS).split(/[,\n]+/).forEach(function (k) {
      k = k.trim();
      if (!k) return;
      var pid = 'openai';
      Object.keys(PROVIDERS).forEach(function (id) { if (PROVIDERS[id].test(k)) pid = id; });
      add(pid, k);
    });
  }
  if (env.BOT_KV) {
    try {
      var custom = (await env.BOT_KV.get('custom_keys', 'json')) || [];
      custom.forEach(function (c) {
        if (!c || !c.key) return;
        var pid = c.provider || 'custom';
        var meta = {};
        if (c.name) meta.name = c.name;
        if (c.base) meta.base = c.base;

        if (String(pid).indexOf('custom_') === 0) {
          meta.name = c.name || meta.name || pid;
          if (c.base) meta.base = c.base;
          if (c.key && (c.key.indexOf('AIza') === 0 || c.key.indexOf('AQ.') === 0)) {
            meta.base = 'https://generativelanguage.googleapis.com/v1beta/openai';
          }
          add(pid, c.key, meta);
          return;
        }

        var known = null;
        Object.keys(PROVIDERS).forEach(function (id) {
          if (PROVIDERS[id].test(c.key)) known = id;
        });
        if (c.base) {
          // آدرس ذخیره‌شده کاربر/ادمین اولویت دارد
          meta.base = c.base;
          meta.name = c.name || (known && PROVIDERS[known].name) || pid;
          if (!known && String(pid).indexOf('custom_') !== 0) {
            pid = 'custom_' + hashStr(c.base).slice(0, 10);
          }
        } else if (known) {
          pid = known;
          meta.base = PROVIDERS[known].base;
          if (!meta.name) meta.name = PROVIDERS[known].name;
        } else if (!PROVIDERS[pid] && c.base) {
          meta.name = c.name || pid;
          meta.base = c.base;
        }
        add(pid, c.key, meta);
      });
    } catch (e) {}
  }
  return provs;
}

async function keyCount(env) {
  var p = await collectKeys(env), n = 0;
  Object.keys(p).forEach(function (k) { n += p[k].keys.length; });
  return n;
}

function pickKey(prov) {
  if (!prov || !prov.keys.length) return null;
  var i = Math.floor(Math.random() * prov.keys.length);
  return { key: prov.keys[i], index: i, total: prov.keys.length };
}

function isVisionModel(id) {
  if (/embed|whisper|tts|guard|moderation|imagen|flux|draw|dall/i.test(id)) return false;
  if (/gemini.*(vision|image)/i.test(id)) return true;
  if (/gemini/i.test(id)) return false;
  return /vision|vl|4o|llama-4|scout|maverick|qwen.*(3\.8|3\.6|-vl)|gpt-4o/i.test(id);
}
function isImageGenModel(id) {
  return /image|imagen|flux|dall-e|dalle|stable-diffusion|sdxl|draw|generate.*image/i.test(id);
}
function isAudioModel(id) {
  return /whisper|tts|speech|audio|orpheus|melotts|mms-tts/i.test(id);
}
function isChatModel(id) {
  if (/embed|guard|moderation/i.test(id)) return false;
  if (isImageGenModel(id)) return false;
  if (isAudioModel(id)) return false;
  return true;
}
/** مدل‌های رایگان شناخته‌شده (Apmix / OpenRouter / TokenHarbor و مشابه) */
function isFreeModel(id) {
  var s = String(id || '').toLowerCase();
  if (!s) return false;
  if (/:free$/i.test(s) || /-free$/i.test(s) || /\/.*-free$/i.test(s)) return true;
  if (/claude-sonnet-4-6-free|claude-3-haiku|claude-3\.5-haiku|claude-haiku.*free/i.test(s)) return true;
  return false;
}
function modelCapability(id) {
  if (isImageGenModel(id)) return 'image';
  if (isAudioModel(id)) return 'audio';
  if (isVisionModel(id)) return 'vision';
  return 'text';
}
/** Only models that are known shut down / removed from API */
function isDeadGeminiModel(id) {
  // 1.x و 2.0 و اغلب 2.5 برای کلیدهای جدید 404 (اکتبر ۲۰۲۶)
  return /gemini-1\.0|gemini-1\.5|gemini-2\.0|gemini-2\.5-flash(?!-lite)|gemini-pro(?!-)|models\/gemini-pro$/i.test(id);
}
/** مدل‌های زنده Gemini برای متن و vision */
function geminiLiveModels() {
  return [
    'gemini-3.5-flash',
    'gemini-3.8-flash',
    'gemini-3.6-flash',
    'gemini-3.5-flash-lite',
    'gemini-3-flash-preview',
    'gemini-2.5-flash-lite',
    'gemini-flash-latest'
  ];
}
function modelCapLabel(cap) {
  if (cap === 'vision') return 'متن+تصویر';
  if (cap === 'image') return 'تولید تصویر';
  if (cap === 'audio') return 'صوت';
  return 'متن';
}

// ---------- ایموجی قابل‌تنظیم پروایدر / مدل ----------
var DEFAULT_PROVIDER_EMOJI = {
  deepseek: '🐋', together: '🤝', fireworks: '🎆', perplexity: '🔎', sambanova: '🦣',
  huggingface: '🤗', deepinfra: '🏗️', hyperbolic: '🌀', siliconflow: '🌊', moonshot: '🌙',
  cf: '☁️',
  gemini: '🩵☁️',
  google_studio: '🩵☁️',
  groq: '⚡',
  openrouter: '🌐',
  openai: '🟢',
  xai: '✖️',
  cerebras: '🧠',
  tokenharbor: '🚢',
  nvidia: '🟩',
  mistral: '🌬️',
  zai: '🟣',
  ollama: '🦙',
  weatherai: '🌤️',
  apx: '🟣',
  cleanapis: '🩵',
  _default_external: '🩵☁️',
  _default_custom: '🔧'
};

async function loadEmojiMap(env) {
  var base = {};
  Object.keys(DEFAULT_PROVIDER_EMOJI).forEach(function (k) { base[k] = DEFAULT_PROVIDER_EMOJI[k]; });
  if (!env || !env.BOT_KV) return { providers: base, models: {} };
  try {
    var saved = await env.BOT_KV.get('emoji_map', 'json');
    if (saved && typeof saved === 'object') {
      if (saved.providers) {
        Object.keys(saved.providers).forEach(function (k) {
          if (saved.providers[k]) base[k] = String(saved.providers[k]).slice(0, 8);
        });
      }
      return {
        providers: base,
        models: (saved.models && typeof saved.models === 'object') ? saved.models : {}
      };
    }
  } catch (e) {}
  return { providers: base, models: {} };
}

async function saveEmojiMap(env, data) {
  if (!env.BOT_KV) return false;
  try {
    var payload = {
      providers: (data && data.providers) || {},
      models: (data && data.models) || {},
      updated: Date.now()
    };
    await env.BOT_KV.put('emoji_map', JSON.stringify(payload));
    return true;
  } catch (e) { return false; }
}

function emojiForModel(map, providerId, modelId) {
  map = map || { providers: DEFAULT_PROVIDER_EMOJI, models: {} };
  if (modelId && map.models && map.models[modelId]) return String(map.models[modelId]).slice(0, 8);
  var famE = familyEmoji(modelId);
  if (famE) return famE;
  if (providerId && map.providers && map.providers[providerId]) return map.providers[providerId];
  if (providerId && String(providerId).indexOf('custom_') === 0) {
    return (map.providers && map.providers._default_custom) || DEFAULT_PROVIDER_EMOJI._default_custom;
  }
  if (providerId === 'cf') return (map.providers && map.providers.cf) || '☁️';
  return (map.providers && map.providers._default_external) || DEFAULT_PROVIDER_EMOJI._default_external;
}

function formatModelLabel(emoji, shortName, providerName) {
  var e = emoji ? (emoji + ' ') : '';
  var p = providerName ? (' · ' + providerName) : '';
  return e + shortName + p;
}

/** پاورقی صادقانه مدل — همیشه مسیر واقعی */
function buildTruthFooter(r) {
  if (!r) return '';
  if (FEATURES && FEATURES.strictTruth === false) {
    var m0 = String(r.model || '').trim();
    var p0 = String(r.providerName || r.provider || '').trim();
    return (m0 || p0) ? ('\n\n— ' + (m0 || '') + (p0 ? ' · ' + p0 : '')) : '';
  }
  var model = String(r.model || '').trim();
  var prov = String(r.providerName || r.provider || '').trim();
  if (!model && !prov) return '';
  var tag = '';
  if (r.userKey || /کلید\s*(شما|من)|user.?key/i.test(prov)) tag = ' · 🔑 کلید شما';
  else if (/Cloudflare/i.test(prov)) tag = ' · رایگان CF';
  else if (r.note && /fallback|جایگزین/i.test(String(r.note))) tag = ' · جایگزین';
  return '\n\n— ' + (model || 'مدل؟') + (prov ? (' · ' + prov) : '') + tag;
}

/** خودآزمایی داخلی — نمره کیفیت عملیاتی */
async function runSelfTest(env) {
  var tests = [];
  function ok(name, pass, detail) {
    tests.push({ name: name, pass: !!pass, detail: String(detail || '').slice(0, 200) });
  }
  ok('نسخه', !!NOVA_VERSION, NOVA_VERSION);
  ok('KV', !!env.BOT_KV, env.BOT_KV ? 'متصل' : 'ندارد');
  ok('تلگرام', !!env.TELEGRAM_BOT_TOKEN, env.TELEGRAM_BOT_TOKEN ? 'توکن هست' : 'نیست');
  ok('Workers AI', !!env.AI, env.AI ? 'binding هست' : 'نیست');
  ok('buildTruthFooter', buildTruthFooter({ model: 'x', providerName: 'Cloudflare' }).indexOf('CF') >= 0, 'footer');
  ok('normalizeKeyboardAction', normalizeKeyboardAction('reset', 'پاک کردن') === '/reset', normalizeKeyboardAction('reset', 'پاک'));
  ok('normalize support', normalizeKeyboardAction('support', 'پشتیبانی') === '__support__', 'support');
  // KV read/write
  if (env.BOT_KV) {
    try {
      var k = 'selftest_' + Date.now();
      await env.BOT_KV.put(k, '1', { expirationTtl: 60 });
      var v = await env.BOT_KV.get(k);
      await env.BOT_KV.delete(k);
      ok('KV نوشتن/خواندن', v === '1', v);
    } catch (e) {
      ok('KV نوشتن/خواندن', false, e.message || e);
    }
  }
  // کلیدها
  try {
    var provs = await collectKeys(env);
    var n = Object.keys(provs || {}).length;
    ok('کلیدهای سیستم', n >= 0, n + ' سرویس');
    ok('Gemini برای vision', !!(provs.gemini || provs.google_studio || env.AI), (provs.gemini || provs.google_studio) ? 'Gemini' : (env.AI ? 'فقط CF' : 'هیچ'));
  } catch (e2) {
    ok('کلیدهای سیستم', false, e2.message || e2);
  }
  // CF ping اختیاری
  if (env.AI) {
    try {
      var r = await withTimeout(env.AI.run('@cf/meta/llama-3.2-3b-instruct', {
        messages: [{ role: 'user', content: 'Say OK' }]
      }), 8000);
      var t = r && (r.response || (r.result && r.result.response) || '');
      ok('CF متن', !!(t && String(t).length), String(t).slice(0, 40));
    } catch (e3) {
      ok('CF متن', false, e3.message || e3);
    }
  }
  var passed = tests.filter(function (x) { return x.pass; }).length;
  var total = tests.length;
  var score = total ? Math.round((passed / total) * 100) / 10 : 0;
  return {
    ok: passed === total,
    score: score,
    passed: passed,
    total: total,
    version: NOVA_VERSION,
    tests: tests
  };
}

function formatSelfTestReport(res) {
  var lines = [
    '🧪 خودآزمایی Nova ' + (res.version || NOVA_VERSION),
    'نمره عملیاتی: ' + res.score + ' / ۱۰  (' + res.passed + '/' + res.total + ')',
    '────────────'
  ];
  (res.tests || []).forEach(function (t) {
    lines.push((t.pass ? '✅ ' : '❌ ') + t.name + (t.detail ? (' — ' + t.detail) : ''));
  });
  lines.push('────────────');
  if (res.ok) lines.push('همه چک‌های اصلی سبز هستند.');
  else lines.push('موارد ❌ را در پنل ادمین/کلیدها/Bindings برطرف کن.');
  return lines.join('\n');
}

