// ============================================================================
// Model Discovery
// ============================================================================
async function discoverModels(env) {
  var ck = 'models_v27';
  if (env.BOT_KV) {
    try {
      var c = await env.BOT_KV.get(ck, 'json');
      if (c && (Date.now() - c.ts) < MODEL_CACHE_TTL * 1000) return c.data;
    } catch (e) {}
  }
  var provs = await collectKeys(env);
  var result = {};
  await Promise.all(Object.keys(provs).map(async function (pid) {
    var prov = provs[pid], ki = pickKey(prov);
    if (!ki) return;
    if (PROVIDERS[pid] && PROVIDERS[pid].kind === 'weather') return;
    if (prov.kind === 'weather') return;
    try {
      var r = await fetchT(prov.base + '/models', { headers: { 'Authorization': 'Bearer ' + ki.key } }, 6000);
      if (!r.ok) {
        result[pid] = { name: prov.name, models: getFallbackModels(pid) };
        return;
      }
      var d = await r.json();
      var models = (d.data || d.models || []).map(function (m) { return m.id || m.name || ''; }).filter(Boolean);
      if (pid === 'tokenharbor' || pid === 'openrouter' || pid === 'apx') {
        // رایگان‌ها اول (apmix: *-free / openrouter: :free)
        var freeFirst = models.filter(function (m) {
          return /:free$/i.test(m) || /-free$/i.test(m) || /\/.*-free$/i.test(m);
        });
        var paidRest = models.filter(function (m) {
          return !(/:free$/i.test(m) || /-free$/i.test(m) || /\/.*-free$/i.test(m));
        });
        models = freeFirst.concat(paidRest);
        if (!models.length) models = getFallbackModels(pid);
        models = models.slice(0, 400);
      }
      if (pid === 'gemini' || (prov.name && /google\s*ai\s*studio|gemini/i.test(prov.name))) {
        var gemOnly = models.filter(function (m) {
          return /gemini|gemma/i.test(m) && !/embed|imagen|tts/i.test(m) && !isDeadGeminiModel(m);
        });
        if (gemOnly.length) models = gemOnly;
        else models = getFallbackModels('gemini');
      }
      if (!models.length) models = getFallbackModels(pid);
      // ids گوگل به شکل «models/gemini-…» می‌آیند
      models = models.map(function (m) { return String(m).replace(/^models\//, ''); });
      // apmix گاهی anthropic/claude-… برمی‌گرداند — هم نسخهٔ کامل و هم کوتاه را نگه دار
      if (pid === 'apx') {
        var expanded = [];
        models.forEach(function (m) {
          if (expanded.indexOf(m) === -1) expanded.push(m);
          var short = String(m).replace(/^(anthropic|openai|google|xai|deepseek|alibaba|zai|moonshot|minimax|xiaomi|tencent|cursor|meta)\//i, '');
          if (short && short !== m && expanded.indexOf(short) === -1) expanded.push(short);
        });
        models = expanded;
      }
      var fb = getFallbackModels(pid);
      if (fb.length) {
        var merged = [];
        var trustFb = (pid === 'openrouter' || pid === 'tokenharbor'); // apx: only models returned by API
        fb.forEach(function (m) {
          // نام fallback فقط اگر API واقعاً آن را برگردانده باشد (یا provider جزو استثناها باشد) جلو می‌آید
          if ((trustFb || models.indexOf(m) !== -1) && merged.indexOf(m) === -1) merged.push(m);
        });
        models.forEach(function (m) { if (merged.indexOf(m) === -1) merged.push(m); });
        models = merged;
      }
      result[pid] = { name: prov.name, models: models };
    } catch (e) {
      result[pid] = { name: prov.name, models: getFallbackModels(pid) };
    }
  }));
  if (env.BOT_KV && Object.keys(result).length) {
    try {
      await env.BOT_KV.put(ck, JSON.stringify({ ts: Date.now(), data: result }), { expirationTtl: MODEL_CACHE_TTL });
    } catch (e) {}
  }
  return result;
}

/**
 * وضعیت اتصال کلیدها — وجود کلید + GET سبک /models
 * 401/403 = قطع؛ برای Gemini وجود کلید کافی است.
 */
async function checkKeysStatus(env) {
  var provs = await collectKeys(env);
  var status = [];

  if (env.AI) {
    status.push({
      id: 'cf',
      name: 'Cloudflare Workers AI',
      connected: true,
      keys: 1,
      detail: 'binding فعال'
    });
  } else {
    status.push({
      id: 'cf',
      name: 'Cloudflare Workers AI',
      connected: false,
      keys: 0,
      detail: 'AI binding تنظیم نشده'
    });
  }

  var pids = Object.keys(provs);
  // تست موازی با timeout کوتاه — تا پنل ادمین قفل نشود
  var tasks = pids.map(function (pid) {
    return (async function () {
      var prov = provs[pid];
      if (PROVIDERS[pid] && PROVIDERS[pid].kind === 'weather') {
        return {
          id: pid,
          name: prov.name || pid,
          connected: prov.keys.length > 0,
          keys: prov.keys.length,
          detail: prov.keys.length ? 'کلید ثبت شده' : 'بدون کلید'
        };
      }
      var ki = pickKey(prov);
      if (!ki) {
        return { id: pid, name: prov.name || pid, connected: false, keys: 0, detail: 'بدون کلید' };
      }
      var isGemKey = ki.key.indexOf('AIza') === 0 || ki.key.indexOf('AQ.') === 0;
      var isCustom = String(pid).indexOf('custom_') === 0;
      var ok = false;
      var detail = '';
      try {
        var base = normalizeGeminiBase(prov.base, ki.key) || prov.base;
        base = String(base).replace(/\/+$/, '');
        var headers = {
          'Authorization': 'Bearer ' + ki.key,
          'User-Agent': 'NovaAI/' + String(NOVA_VERSION || '25').replace(/^v/, '')
        };
        if (pid === 'openrouter' || /openrouter/i.test(prov.name || '')) {
          headers['HTTP-Referer'] = 'https://nova-ai.workers.dev';
          headers['X-Title'] = 'Nova AI';
          headers['Content-Type'] = 'application/json';
        }
        var r = await fetchT(base + '/models', { headers: headers }, 2800);
        if (r && r.ok) {
          ok = true;
          detail = 'وصل — API پاسخ داد';
        } else {
          var code = r ? r.status : 0;
          if (isGemKey) {
            ok = true;
            detail = 'کلید Gemini ثبت شده';
          } else if (isCustom) {
            ok = true;
            detail = 'کلید سفارشی ثبت شده (مسیر /models ممکن است پشتیبانی نشود)';
          } else if (code === 404 || code === 405) {
            ok = true;
            detail = 'کلید ثبت شده (endpoint مدل‌ها در دسترس نیست)';
          } else if (code === 401) {
            ok = false;
            detail = 'کلید نامعتبر (401) — کلید را در پنل عوض کن';
          } else if (code === 403) {
            ok = true;
            detail = 'کلید ثبت است — تست /models کد 403 داد (محدودیت منطقه یا هدر؛ در چت امتحان کن)';
          } else if (code === 429) {
            ok = true;
            detail = 'کلید ثبت است — فعلاً rate-limit (429)';
          } else {
            ok = true;
            detail = 'کلید ثبت است — پاسخ تست: ' + (code || 'network');
          }
        }
      } catch (e) {
        ok = true;
        detail = isGemKey || isCustom
          ? 'کلید ثبت شده'
          : 'کلید ثبت است — تست شبکه ناموفق: ' + (e.message || 'network');
      }
      return {
        id: pid,
        name: prov.name || pid,
        connected: ok,
        keys: prov.keys.length,
        detail: detail
      };
    })();
  });
  try {
    var settled = await Promise.all(tasks);
    for (var si = 0; si < settled.length; si++) status.push(settled[si]);
  } catch (eAll) {
    /* fallback: فقط وجود کلید */
    pids.forEach(function (pid) {
      var prov = provs[pid];
      var n = (prov && prov.keys && prov.keys.length) || 0;
      status.push({
        id: pid,
        name: (prov && prov.name) || pid,
        connected: n > 0,
        keys: n,
        detail: n ? 'کلید ثبت شده' : 'بدون کلید'
      });
    });
  }

  return status;
}

/**
 * فقط پروایدرهای وصل‌شده + مدل‌هایشان (بدون تست چت زنده).
 */
async function getWorkingModels(env, noCache) {
  if (!noCache) {
    var cachedWm = await cacheGet(env, 'wm_v1');
    if (cachedWm) return cachedWm;
  }
  var raw = await discoverModels(env);
  var provsAll = await collectKeys(env);
  var connected = {};
  Object.keys(provsAll).forEach(function (pid) {
    if (PROVIDERS[pid] && PROVIDERS[pid].kind === 'weather') return;
    if (provsAll[pid] && provsAll[pid].keys && provsAll[pid].keys.length) connected[pid] = true;
  });
  if (env.AI) connected.cf = true;

  var result = {};
  Object.keys(raw).forEach(function (pid) {
    if (!connected[pid]) return;
    var models = (raw[pid].models || []).filter(isChatModel);
    if (pid === 'gemini' || pid === 'google_studio') {
      models = models.filter(function (m) { return /gemini|gemma/i.test(m) && !isDeadGeminiModel(m); });
    }
    if (!models.length) models = getFallbackModels(pid).filter(isChatModel);
    if (models.length) result[pid] = { name: raw[pid].name || pid, models: models.slice(0, 400) };
  });
  Object.keys(connected).forEach(function (pid) {
    if (pid === 'cf' || result[pid]) return;
    var fb = getFallbackModels(pid).filter(isChatModel);
    if (fb.length) result[pid] = { name: (provsAll[pid] && provsAll[pid].name) || pid, models: fb };
  });
  if (env.AI) result.cf = { name: 'Cloudflare', models: CF_CHAT_MODELS.slice() };

  // مدل‌های دستی ادمین
  try {
    var nxExtraM = env.BOT_KV ? ((await env.BOT_KV.get('extra_models', 'json')) || {}) : {};
    Object.keys(nxExtraM).forEach(function (pid) {
      var add = nxExtraM[pid] || [];
      if (!add.length) return;
      // مدل‌های ادمین همیشه اضافه می‌شوند — حتی اگر آن سرویس فقط کلید کاربر داشته باشد
      if (!result[pid]) result[pid] = { name: (PROVIDERS[pid] && PROVIDERS[pid].name) || pid, models: [] };
      add.slice().reverse().forEach(function (m) {
        if (result[pid].models.indexOf(m) === -1) result[pid].models.unshift(m);
      });
    });
  } catch (e) {}

  // مدل‌های ذخیره‌شده روی custom_keys (از ویزارد سایت+کلید)
  try {
    var cksM = env.BOT_KV ? ((await env.BOT_KV.get('custom_keys', 'json')) || []) : [];
    cksM.forEach(function (c) {
      if (!c || !c.key) return;
      var pid = c.provider || ('custom_' + hashStr(c.base || c.site || c.key).slice(0, 10));
      var nm = c.name || c.provider || pid;
      var saved = Array.isArray(c.models) ? c.models.filter(Boolean) : [];
      if (!result[pid]) {
        result[pid] = { name: nm, models: saved.slice(0, 400), base: c.base || c.site || '' };
      } else {
        if (!result[pid].name || result[pid].name === pid) result[pid].name = nm;
        saved.forEach(function (m) {
          if (result[pid].models.indexOf(m) === -1) result[pid].models.push(m);
        });
      }
      // اگر هنوز مدل ندارد، از fallback خالی نگذار — حداقل یک مدل پیش‌فرض
      if (!result[pid].models.length) {
        var defM = defaultModelForBase(c.base || c.site || '');
        if (defM) result[pid].models = [defM];
      }
    });
  } catch (eCk) {}

  if (Object.keys(result).length) await cacheSet(env, 'wm_v1', result, 300);
  return result;
}

async function pickModel(env, pid, kind) {
  var working = await getWorkingModels(env);
  var info = working[pid];
  if ((!info || !info.models || !info.models.length) && pid === 'cf') {
    info = working.cf;
  }
  if (!info || !info.models || !info.models.length) {
    if (pid === 'groq' && working.groq) return working.groq.models[0];
    if (pid === 'apx' && working.apx) return working.apx.models[0];
    if (env.AI) return '@cf/meta/llama-3.3-70b-instruct-fp8-fast';
    if (pid === 'groq') return 'openai/gpt-oss-120b';
    if (pid === 'apx') return 'claude-sonnet-4-6-free';
    if (pid === 'gemini') return 'gemini-3.5-flash';
    if (pid === 'nvidia') return 'nvidia/nemotron-3-super-120b-a12b';
    if (pid === 'mistral') return 'mistral-small-latest';
    if (pid === 'zai') return 'glm-4.7-flash';
    if (pid === 'ollama') return 'gpt-oss:120b';
    if (pid === 'tokenharbor') return 'mimo-v2.5:free';
    if (pid === 'openrouter') return 'deepseek/deepseek-chat-v3.1:free';
    if (pid === 'xai') return 'grok-3-mini';
    if (pid === 'cerebras') return 'llama3.1-8b';
    return null;
  }
  var chat = info.models.filter(isChatModel);
  if (pid === 'gemini') {
    chat = chat.filter(function (m) { return !isDeadGeminiModel(m); });
  }
  if (kind === 'vision') {
    var vis = chat.filter(isVisionModel);
    vis.sort(function (a, b) { return (/flash/.test(a) ? 0 : 1) - (/flash/.test(b) ? 0 : 1); });
    return vis[0] || null;
  }
  if (pid === 'gemini') {
    var prefer = chat.filter(function (m) { return /gemini-2\.5-flash(?!-lite)|gemini-3\.\d-flash(?!-lite)|flash-latest|flash-lite/i.test(m); });
    if (prefer.length) return prefer[0];
    var f = chat.filter(function (m) { return /flash/i.test(m); });
    if (f.length) return f[0];
  }
  if (pid === 'groq') {
    var g = chat.filter(function (m) { return /70b|120b|llama-3\.3/i.test(m); });
    if (g.length) return g[0];
  }
  if (pid === 'openrouter' && chat.indexOf('openrouter/free') !== -1) return 'openrouter/free';
  if (pid === 'tokenharbor' || pid === 'openrouter' || pid === 'apx') {
    var free = chat.filter(function (m) {
      return m.indexOf(':free') !== -1 || /-free$/i.test(m) || /\/.*-free$/i.test(m);
    });
    if (free.length) return free[0];
  }
  return chat[0] || null;
}


