function cleanApiError(raw) {
  var s = String(raw || '');
  if (/<!doctype|google-signin|<html/i.test(s)) {
    return 'آدرس API یا کلید اشتباه است (پاسخ HTML به‌جای JSON). برای Google AI Studio از این آدرس استفاده کن:\nhttps://generativelanguage.googleapis.com/v1beta/openai';
  }
  try {
    var j = JSON.parse(s);
    if (j.error) {
      var e = j.error;
      return (e.message || e.status || JSON.stringify(e)).slice(0, 220);
    }
  } catch (e) {}
  return s.replace(/\s+/g, ' ').slice(0, 250);
}

function normalizeGeminiBase(base, key) {
  var isGemKey = key && (String(key).indexOf('AIza') === 0 || String(key).indexOf('AQ.') === 0);
  var gemBase = 'https://generativelanguage.googleapis.com/v1beta/openai';
  if (isGemKey) return gemBase;
  if (base && /generativelanguage\.googleapis\.com/i.test(base)) {
    base = base.replace(/\/+$/, '');
    if (!/\/openai$/i.test(base) && !/\/v1beta\/openai/i.test(base)) {
      if (/\/v1beta$/i.test(base)) return base + '/openai';
      return gemBase;
    }
    return base;
  }
  return base;
}

function isFatalKeyError(err) {
  var e = String(err || '').toLowerCase();
  return /unsupported_country|region_territory|request_forbidden|invalid.?api.?key|incorrect.?api.?key|authentication|401|billing|quota.?exceeded|account.?deactivated|payment.?required|no credits|credits remaining|insufficient.?quota|insufficient.?funds|\[402\]|\[403\]|\[429\]/i.test(e);
}

function isBillingOrQuotaError(err) {
  var e = String(err || '').toLowerCase();
  return /402|insufficient.?quota|insufficient.?funds|billing|payment.?required|no credits|credits remaining|quota.?exceeded|payment method/i.test(e);
}

/** موقتاً پروایدر/مدل را به‌خاطر اتمام اعتبار کنار بگذار */
async function markProviderQuotaFail(env, providerId, modelId, errMsg) {
  if (!env || !env.BOT_KV) return;
  try {
    var key = 'quota_fail_' + String(providerId || 'x') + '_' + String(modelId || 'any').slice(0, 60);
    await env.BOT_KV.put(key, JSON.stringify({
      ts: Date.now(),
      err: String(errMsg || '').slice(0, 200)
    }), { expirationTtl: 3600 }); // 1 hour skip
    var list = (await env.BOT_KV.get('quota_fail_list', 'json')) || [];
    if (!Array.isArray(list)) list = [];
    list.unshift({ p: providerId, m: modelId, ts: Date.now(), err: String(errMsg || '').slice(0, 120) });
    if (list.length > 40) list = list.slice(0, 40);
    await env.BOT_KV.put('quota_fail_list', JSON.stringify(list), { expirationTtl: 86400 });
  } catch (e) {}
}

async function isProviderQuotaFailed(env, providerId, modelId) {
  if (!env || !env.BOT_KV) return false;
  try {
    var key = 'quota_fail_' + String(providerId || 'x') + '_' + String(modelId || 'any').slice(0, 60);
    var v = await env.BOT_KV.get(key);
    return !!v;
  } catch (e) { return false; }
}

