/** Vision بومی Gemini (inline_data) — پایدارتر از endpoint سازگار با OpenAI */
async function seeFileGeminiNative(env, question, pureB64, mime, keys) {
  if (!keys || !keys.length || !pureB64) return null;
  mime = String(mime || 'image/jpeg');
  var models = geminiLiveModels();
  var last = '';
  for (var k = 0; k < keys.length && k < 3; k++) {
    var key = keys[k];
    for (var i = 0; i < models.length; i++) {
      var model = models[i];
      var url = 'https://generativelanguage.googleapis.com/v1beta/models/' + model +
        ':generateContent?key=' + encodeURIComponent(key);
      try {
        var r = await fetchT(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{
              role: 'user',
              parts: [
                { text: String(question || 'این تصویر را کامل توضیح بده.') },
                { inline_data: { mime_type: mime, data: pureB64 } }
              ]
            }],
            generationConfig: { maxOutputTokens: 2048 }
          })
        }, 15000);
        if (!r || !r.ok) {
          var et = '';
          try { et = await r.text(); } catch (e) {}
          last = 'Gemini ' + model + ' [' + (r ? r.status : '?') + ']: ' + cleanApiError(et).slice(0, 120);
          continue;
        }
        var d = await r.json();
        var t = d && d.candidates && d.candidates[0] && d.candidates[0].content &&
          d.candidates[0].content.parts && d.candidates[0].content.parts.map(function (p) {
            return p && p.text ? p.text : '';
          }).join('');
        if (t && String(t).trim()) {
          return { text: String(t).trim(), model: model, providerName: 'Gemini' };
        }
        last = 'Gemini ' + model + ': پاسخ خالی';
      } catch (e) {
        last = 'Gemini: ' + ((e && e.message) || 'error');
      }
    }
  }
  return last ? { error: last } : null;
}

async function seeFile(env, question, dataUrl, mime, uid) {
  mime = String(mime || 'image/jpeg');
  var deadline = Date.now() + 55000;
  function timeLeft() { return Math.max(0, deadline - Date.now()); }
  function expired() { return timeLeft() < 1500; }

  var errs = [];
  var tried = [];
  var pureB64 = String(dataUrl || '').replace(/^data:[^;]+;base64,/, '');
  if (!pureB64 || pureB64.length < 50) {
    return { error: 'داده تصویر خالی یا ناقص است' };
  }
  // تشخیص mime واقعی از بایت‌ها
  try {
    var bin0 = atob(pureB64.slice(0, 48));
    var u0 = new Uint8Array(bin0.length);
    for (var zi = 0; zi < bin0.length; zi++) u0[zi] = bin0.charCodeAt(zi);
    var det = detectImageMime(u0);
    if (det) mime = det;
  } catch (eMime) {}
  if (pureB64.length > 1800000) {
    pureB64 = pureB64.slice(0, 1800000);
    errs.push('عکس بزرگ؛ کوتاه شد');
  }
  question = String(question ||
    'این تصویر را کامل و دقیق توضیح بده. هر متن، عدد، لوگو، رنگ و جزئیات مهم را بنویس. اگر سؤال خاصی در پیام هست همان را جواب بده.');
  var dataUrlSafe = 'data:' + mime + ';base64,' + pureB64;

  // —— جمع کلید Gemini (سیستم + کاربر)
  var gemKeys = [];
  var allProvs = null;
  try {
    allProvs = await collectKeys(env);
    if (allProvs.gemini && allProvs.gemini.keys) gemKeys = gemKeys.concat(allProvs.gemini.keys);
    if (allProvs.google_studio && allProvs.google_studio.keys) gemKeys = gemKeys.concat(allProvs.google_studio.keys);
    Object.keys(allProvs || {}).forEach(function (pid) {
      if (pid === 'gemini' || pid === 'google_studio') return;
      var pr = allProvs[pid];
      if (!pr || !pr.keys) return;
      if (/generativelanguage|gemini/i.test(String(pr.base || ''))) {
        gemKeys = gemKeys.concat(pr.keys);
      } else {
        pr.keys.forEach(function (k) {
          if (/^AIza|^AQ\./i.test(String(k))) gemKeys.push(k);
        });
      }
    });
  } catch (eP) { errs.push('collectKeys:' + (eP.message || eP)); }
  if (uid) {
    try {
      var uk = await getUserKeys(env, uid);
      (uk || []).forEach(function (rec) {
        var k = rec && (rec.key || rec.keyFull);
        if (k && /^AIza|^AQ\./i.test(String(k))) gemKeys.push(String(k));
        if (k && /generativelanguage|gemini/i.test(String(rec.base || rec.site || ''))) gemKeys.push(String(k));
      });
    } catch (eUk) {}
  }
  var seenK = {};
  gemKeys = gemKeys.filter(function (k) {
    k = String(k || '').trim();
    if (!k || seenK[k]) return false;
    seenK[k] = 1;
    return true;
  }).slice(0, 4);

  // ——— 1) Cloudflare vision — چند فرمت (byte array / prompt+image / messages)
  if (env.AI && mime.indexOf('image/') === 0 && !expired()) {
    tried.push('cf');
    var cfModel = '@cf/meta/llama-3.2-11b-vision-instruct';
    var imgBytes = null;
    try {
      var binImg = atob(pureB64);
      imgBytes = new Uint8Array(binImg.length);
      for (var bi = 0; bi < binImg.length; bi++) imgBytes[bi] = binImg.charCodeAt(bi);
    } catch (eBytes) { errs.push('CF decode:' + (eBytes.message || eBytes)); }
    var cfPayloads = [];
    if (imgBytes && imgBytes.length) {
      // Array بزرگ حافظه Worker را پر می‌کند؛ فقط برای عکس کوچک
      if (imgBytes.length <= 400000) {
        cfPayloads.push({ tag: 'prompt+bytes', body: { prompt: question, image: Array.from(imgBytes) } });
      }
      cfPayloads.push({ tag: 'prompt+b64', body: { prompt: question, image: pureB64 } });
    }
    cfPayloads.push({
      tag: 'messages+image',
      body: {
        messages: [
          { role: 'system', content: 'You are a helpful vision assistant. Answer clearly.' },
          { role: 'user', content: question }
        ],
        image: dataUrlSafe,
        max_tokens: 1500
      }
    });
    cfPayloads.push({
      tag: 'messages+image_url',
      body: {
        messages: [{
          role: 'user',
          content: [
            { type: 'text', text: question },
            { type: 'image_url', image_url: { url: dataUrlSafe } }
          ]
        }],
        max_tokens: 1500
      }
    });
    for (var cp = 0; cp < cfPayloads.length && !expired(); cp++) {
      try {
        var res = await withTimeout(env.AI.run(cfModel, cfPayloads[cp].body), Math.min(16000, timeLeft()));
        var tCf = res && (res.response || (res.result && res.result.response) ||
          (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) ||
          (typeof res === 'string' ? res : null) ||
          res.description);
        if (tCf && String(tCf).trim()) {
          var tOut = String(tCf).trim();
          if (/must submit the prompt ['\"]agree['\"]|submit the prompt agree/i.test(tOut)) {
            errs.push('CF needs-agree');
            continue;
          }
          return { text: tOut, model: cfModel, providerName: 'Cloudflare Workers AI' };
        }
        errs.push('CF ' + cfPayloads[cp].tag + ': empty');
      } catch (e1) {
        var em = String((e1 && e1.message) || e1).slice(0, 100);
        errs.push('CF ' + cfPayloads[cp].tag + ':' + em);
        // ToS agree error — skip rest of CF quickly
        if (/5016|submit the prompt|agree/i.test(em)) break;
      }
    }
  } else if (!env.AI) {
    tried.push('cf-missing');
    errs.push('AI binding نيست');
  }

  // ——— 2) Gemini — مدل‌های زنده، تایم‌اوت بیشتر، فشرده‌تر
  if (gemKeys.length && !expired()) {
    tried.push('gemini');
    var gModels = geminiLiveModels().slice(0, 4);
    // عکس خیلی بزرگ → کوتاه‌تر (Gemini گاهی abort)
    var gemB64 = pureB64;
    if (gemB64.length > 900000) gemB64 = gemB64.slice(0, 900000);
    outerGem:
    for (var gk = 0; gk < Math.min(gemKeys.length, 2) && !expired(); gk++) {
      for (var gi = 0; gi < gModels.length && !expired(); gi++) {
        var gModel = gModels[gi];
        if (typeof isDeadGeminiModel === 'function' && isDeadGeminiModel(gModel)) continue;
        var gUrl = 'https://generativelanguage.googleapis.com/v1beta/models/' + gModel +
          ':generateContent?key=' + encodeURIComponent(gemKeys[gk]);
        try {
          var gR = await fetchT(gUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              contents: [{
                role: 'user',
                parts: [
                  { text: question },
                  { inline_data: { mime_type: mime, data: gemB64 } }
                ]
              }],
              generationConfig: { maxOutputTokens: 2048, temperature: 0.3 }
            })
          }, Math.min(28000, Math.max(12000, timeLeft())));
          if (gR && gR.ok) {
            var gD = await gR.json();
            var block = gD && gD.promptFeedback && gD.promptFeedback.blockReason;
            if (block) { errs.push('Gemini block:' + block); continue; }
            var parts = gD && gD.candidates && gD.candidates[0] && gD.candidates[0].content && gD.candidates[0].content.parts;
            var gT = '';
            if (parts && parts.length) {
              gT = parts.map(function (p) { return (p && p.text) || ''; }).join('');
            }
            if (gT && String(gT).trim()) {
              return { text: String(gT).trim(), model: gModel, providerName: 'Gemini' };
            }
            errs.push('Gemini ' + gModel + ': empty');
          } else {
            var gEt = '';
            try { gEt = gR ? await gR.text() : ''; } catch (e) {}
            var st = gR ? gR.status : 'net';
            errs.push('Gemini ' + gModel + '[' + st + '] ' + (typeof cleanApiError === 'function' ? cleanApiError(gEt).slice(0, 70) : String(gEt).slice(0, 70)));
            if (gR && (gR.status === 401 || gR.status === 403)) continue outerGem;
            if (gR && gR.status === 404) continue;
          }
        } catch (eG) {
          errs.push('Gemini:' + ((eG && eG.message) || 'err'));
        }
      }
    }
  } else if (!gemKeys.length) {
    errs.push('كليد Gemini نيست (AIza...)');
  }

  // ——— 3) OpenRouter vision (مدل‌های واقعی‌تر)
  if (!expired() && allProvs && allProvs.openrouter && allProvs.openrouter.keys && allProvs.openrouter.keys.length) {
    tried.push('openrouter');
    var orModels = [
      'google/gemini-2.0-flash-001',
      'google/gemini-2.5-flash-preview-05-20',
      'google/gemini-flash-1.5-8b',
      'qwen/qwen2.5-vl-32b-instruct',
      'meta-llama/llama-3.2-11b-vision-instruct:free',
      'openai/gpt-4o-mini'
    ];
    var msgs = [{
      role: 'user',
      content: [
        { type: 'text', text: question },
        { type: 'image_url', image_url: { url: dataUrlSafe } }
      ]
    }];
    for (var oi = 0; oi < orModels.length && !expired(); oi++) {
      try {
        var rOr = await callExternalAllKeys(env, msgs, {
          provider: 'openrouter',
          model: orModels[oi],
          maxTokens: 1500,
          timeout: Math.min(14000, timeLeft()),
          forceExternal: true,
          noModelFallback: true,
          noProviderFallback: true
        });
        if (rOr && rOr.text) {
          return Object.assign(rOr, { providerName: rOr.providerName || 'OpenRouter' });
        }
        if (rOr && rOr.error) {
          errs.push('OR:' + String(rOr.error).slice(0, 80));
          if (/403|401|access denied|security policy/i.test(String(rOr.error))) break;
        }
      } catch (eOr1) {
        errs.push('OR:' + ((eOr1 && eOr1.message) || 'err'));
      }
    }
  }

  // ——— 4) Groq vision
  if (!expired() && allProvs && allProvs.groq && allProvs.groq.keys && allProvs.groq.keys.length) {
    tried.push('groq');
    var groqModels = [
      'meta-llama/llama-4-scout-17b-16e-instruct',
      'llama-3.2-11b-vision-preview'
    ];
    var msgsG = [{
      role: 'user',
      content: [
        { type: 'text', text: question },
        { type: 'image_url', image_url: { url: dataUrlSafe } }
      ]
    }];
    for (var gqi = 0; gqi < groqModels.length && !expired(); gqi++) {
      try {
        var rQ = await callExternalAllKeys(env, msgsG, {
          provider: 'groq',
          model: groqModels[gqi],
          maxTokens: 1200,
          timeout: Math.min(14000, timeLeft()),
          forceExternal: true,
          noModelFallback: true,
          noProviderFallback: true
        });
        if (rQ && rQ.text) return Object.assign(rQ, { providerName: rQ.providerName || 'Groq' });
        if (rQ && rQ.error) errs.push('Groq:' + String(rQ.error).slice(0, 80));
      } catch (eQ) {
        errs.push('Groq:' + ((eQ && eQ.message) || 'err'));
      }
    }
  }

  return {
    error: (errs.slice(0, 5).join(' · ') || 'ناموفق') +
      ' | امتحان: ' + (tried.join(',') || '-') +
      ' | GeminiKey:' + (gemKeys.length ? ('yes×' + gemKeys.length) : 'no') +
      ' | AI:' + (env.AI ? 'yes' : 'no')
  };
}

/**
 * تحلیل واقعی PDF — از endpoint بومی Gemini (generateContent) استفاده می‌کند
 * چون endpoint سازگار با OpenAI فایل PDF را به‌عنوان image_url قبول نمی‌کند.
 * base64Data باید فقط بخش base64 (بدون پیشوند data:...;base64,) باشد.
 */
async function analyzePDF(env, question, base64Data) {
  var provs = await collectKeys(env);
  if (!provs.gemini && !provs.google_studio) return null;
  var provKey = provs.gemini ? 'gemini' : 'google_studio';
  var ki = pickKey(provs[provKey]);
  if (!ki) return null;
  var models = geminiLiveModels();
  for (var i = 0; i < models.length; i++) {
    var model = models[i];
    if (isDeadGeminiModel(model)) continue;
    var url = 'https://generativelanguage.googleapis.com/v1beta/models/' + model +
      ':generateContent?key=' + ki.key;
    try {
      var r = await fetchT(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{
            role: 'user',
            parts: [
              { text: question },
              { inline_data: { mime_type: 'application/pdf', data: base64Data } }
            ]
          }]
        })
      }, FILE_ANALYSIS_TIMEOUT);
      if (!r.ok) continue;
      var d = await r.json();
      var t = d && d.candidates && d.candidates[0] && d.candidates[0].content &&
        d.candidates[0].content.parts && d.candidates[0].content.parts[0] && d.candidates[0].content.parts[0].text;
      if (t) return { text: t, model: model, providerName: 'Gemini' };
    } catch (e) {}
  }
  return null;
}

/** پاک‌سازی متن خروجی Whisper */
function cleanTranscript(t) {
  t = String(t || '').replace(/\s+/g, ' ').trim();
  // زیر تکرارهای بی‌معنی مدل
  t = t.replace(/^(زیرنویس|subtitles|thanks for watching)[\s\S]*$/i, '').trim();
  t = t.replace(/[^\S\n]+/g, ' ');
  return t;
}

/** امتیاز کیفیت متن تشخیص‌داده‌شده (بالاتر = بهتر) */
function scoreTranscript(t) {
  t = String(t || '').trim();
  if (!t || t.length < 2) return -1;
  if (/^[.\s…,_-]+$/.test(t)) return -1;
  var score = Math.min(t.length, 80);
  var fa = (t.match(/[\u0600-\u06FF]/g) || []).length;
  var en = (t.match(/[a-zA-Z]/g) || []).length;
  // اولویت فارسی برای کاربر ایرانی
  score += fa * 2;
  score += Math.min(en, 20);
  // جریمه برای متن خیلی انگلیسی وقتی انتظار فارسی است
  if (fa === 0 && en > 15 && t.length > 20) score -= 10;
  // جریمه تکرار کاراکتر
  if (/(.)\1{5,}/.test(t)) score -= 20;
  return score;
}

/**
 * STT بهینه‌شده:
 * - فرمت درست برای ویس تلگرام (ogg/opus)
 * - چند مدل/زبان Groq + OpenAI + Cloudflare
 * - انتخاب بهترین خروجی با امتیاز
 */
async function transcribe(env, audioBytes, mime, fname) {
  var provs = await collectKeys(env);
  mime = audioMimeFromName(mime, fname);
  var bytes = audioBytes instanceof Uint8Array ? audioBytes : new Uint8Array(audioBytes || []);
  if (!bytes.length) return null;

  // پسوند و MIME — ویس تلگرام معمولاً ogg/opus است
  var ext = 'mp3';
  var blobMime = mime || 'audio/mpeg';
  if (/ogg|opus/i.test(mime) || /\.(ogg|oga|opus)$/i.test(fname || '')) {
    ext = 'ogg';
    blobMime = 'audio/ogg';
  } else if (/webm/i.test(mime)) {
    ext = 'webm';
    blobMime = 'audio/webm';
  } else if (/wav/i.test(mime)) {
    ext = 'wav';
    blobMime = 'audio/wav';
  } else if (/mp4|m4a|aac/i.test(mime)) {
    ext = 'm4a';
    blobMime = 'audio/mp4';
  } else if (/flac/i.test(mime)) {
    ext = 'flac';
    blobMime = 'audio/flac';
  } else if (fname && /\.(\w+)$/.test(fname)) {
    ext = fname.match(/\.(\w+)$/)[1].toLowerCase();
  }

  var faPrompt =
    'گفتار فارسی ایران. اخبار، قیمت دلار، آب و هوا، سوالات روزمره. ' +
    'کلمات را دقیق بنویس. از فارسی معیار استفاده کن.';

  var candidates = [];

  async function tryOpenAICompatible(base, key, model, language, prompt, label) {
    try {
      var fd = new FormData();
      fd.append('file', new Blob([bytes], { type: blobMime }), 'voice.' + ext);
      fd.append('model', model);
      fd.append('response_format', 'json');
      fd.append('temperature', '0');
      if (language) fd.append('language', language);
      if (prompt) fd.append('prompt', prompt);
      var r = await fetchT(base.replace(/\/+$/, '') + '/audio/transcriptions', {
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + key },
        body: fd
      }, 55000);
      if (!(r && r.ok)) return;
      var d = await r.json();
      var tx = cleanTranscript(d && d.text);
      if (scoreTranscript(tx) >= 0) {
        candidates.push({ text: tx, providerName: label, score: scoreTranscript(tx), model: model });
      }
    } catch (e) {}
  }

  // 1) Groq — سریع و دقیق
  if (provs.groq) {
    var gk = pickKey(provs.groq).key;
    // ترتیب: turbo+fa → large+fa → turbo بدون زبان
    await tryOpenAICompatible('https://api.groq.com/openai/v1', gk, 'whisper-large-v3-turbo', 'fa', faPrompt, 'Groq Whisper');
    // اگر امتیاز پایین بود مدل دقیق‌تر
    var bestSoFar = candidates.length ? candidates.reduce(function (a, b) { return a.score >= b.score ? a : b; }) : null;
    if (!bestSoFar || bestSoFar.score < 25) {
      await tryOpenAICompatible('https://api.groq.com/openai/v1', gk, 'whisper-large-v3', 'fa', faPrompt, 'Groq Whisper v3');
    }
    if (!candidates.length) {
      await tryOpenAICompatible('https://api.groq.com/openai/v1', gk, 'whisper-large-v3-turbo', null, faPrompt, 'Groq Whisper auto');
    }
  }

  // 2) OpenAI Whisper (اگر کلید باشد)
  if ((!candidates.length || candidates[0].score < 20) && provs.openai) {
    var ok = pickKey(provs.openai).key;
    await tryOpenAICompatible('https://api.openai.com/v1', ok, 'whisper-1', 'fa', faPrompt, 'OpenAI Whisper');
  }

  // 3) Cloudflare Workers AI
  if (env.AI && (!candidates.length || candidates[0].score < 15)) {
    try {
      var res = await env.AI.run(CF_WHISPER, { audio: b64(bytes) });
      var ctx = cleanTranscript(res && res.text);
      if (scoreTranscript(ctx) >= 0) {
        candidates.push({
          text: ctx,
          providerName: 'Cloudflare Whisper',
          score: scoreTranscript(ctx),
          model: CF_WHISPER
        });
      }
    } catch (e) {}
  }

  if (!candidates.length) return null;
  candidates.sort(function (a, b) { return b.score - a.score; });
  return {
    text: candidates[0].text,
    providerName: candidates[0].providerName,
    model: candidates[0].model,
    score: candidates[0].score
  };
}

/** تبدیل پاسخ مدل TTS به بایت‌های صوتی */
function normalizeAudioResult(res) {
  if (!res) return null;
  return Promise.resolve().then(async function () {
    if (res instanceof ReadableStream) {
      var ab = await new Response(res).arrayBuffer();
      return ab && ab.byteLength ? new Uint8Array(ab) : null;
    }
    if (res instanceof ArrayBuffer) return res.byteLength ? new Uint8Array(res) : null;
    if (res instanceof Uint8Array) return res.length ? res : null;
    if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView && ArrayBuffer.isView(res)) {
      return new Uint8Array(res.buffer, res.byteOffset, res.byteLength);
    }
    if (res.audio) {
      if (typeof res.audio === 'string') {
        try {
          var bin = atob(res.audio.replace(/^data:audio\/[\w/+-]+;base64,/, ''));
          var a = new Uint8Array(bin.length);
          for (var i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
          return a.length ? a : null;
        } catch (e) { return null; }
      }
      if (Array.isArray(res.audio)) return new Uint8Array(res.audio);
      if (res.audio instanceof Uint8Array) return res.audio;
    }
    if (typeof res === 'string' && res.length > 100) {
      try {
        var bin2 = atob(res);
        var a2 = new Uint8Array(bin2.length);
        for (var j = 0; j < bin2.length; j++) a2[j] = bin2.charCodeAt(j);
        return a2.length ? a2 : null;
      } catch (e2) { return null; }
    }
    return null;
  });
}

/** آیا بایت‌ها واقعاً شبیه فایل صوتی هستند؟ (نه فایل خالی 00:00) */
function isValidAudioBytes(u8) {
  if (!u8 || u8.length < 800) return false;
  // MP3: ID3 یا frame sync 0xFFEx
  if (u8[0] === 0x49 && u8[1] === 0x44 && u8[2] === 0x33) return true; // ID3
  if (u8[0] === 0xff && (u8[1] & 0xe0) === 0xe0) return true;
  // OGG
  if (u8[0] === 0x4f && u8[1] === 0x67 && u8[2] === 0x67 && u8[3] === 0x53) return true;
  // WAV/RIFF
  if (u8[0] === 0x52 && u8[1] === 0x49 && u8[2] === 0x46 && u8[3] === 0x46) return true;
  // بعضی پاسخ‌های CF بدون هدر استاندارد ولی بزرگ‌اند
  if (u8.length > 4000) return true;
  return false;
}

/** آماده‌سازی متن فارسی برای تلفظ طبیعی‌تر */
function preparePersianTTS(text) {
  text = String(text || '');
  // یکسان‌سازی حروف عربی → فارسی
  text = text.replace(/ي/g, 'ی').replace(/ك/g, 'ک').replace(/ة/g, 'ه');
  // حذف حرکات عربی
  text = text.replace(/[\u064B-\u065F\u0670]/g, '');
  // لینک و مارک‌داون
  text = text
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/[*_`#~>\[\]()]+/g, ' ')
    .replace(/🤖[\s\S]*$/m, ' ')
    .replace(/via\s+\w+/gi, ' ')
    .replace(/[📌🔗📊📰🗞⚡🚨🏛💰⚽🌍👥]+/g, ' ');
  // اعداد انگلیسی → خواناتر (فاصله دور عدد)
  text = text.replace(/(\d+)/g, ' $1 ');
  // فاصله بعد از نقطه‌گذاری فارسی
  text = text.replace(/([.!?؟؛:،])\s*/g, '$1 ');
  // خطوط خبری «1. عنوان» → نرم‌تر
  text = text.replace(/^\s*\d+[\.\)]\s*/gm, '');
  text = text.replace(/\s+/g, ' ').trim();
  return text;
}

/** برش متن روی مرز جمله/عبارت برای TTS روان‌تر */
function chunkForTTS(text, maxLen) {
  maxLen = maxLen || 140;
  text = String(text || '').trim();
  if (!text) return [];
  var chunks = [];
  var parts = text.split(/(?<=[.!?؟؛\n])\s+/);
  var buf = '';
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i].trim();
    if (!p) continue;
    if ((buf + ' ' + p).trim().length <= maxLen) {
      buf = (buf + ' ' + p).trim();
    } else {
      if (buf) chunks.push(buf);
      if (p.length <= maxLen) {
        buf = p;
      } else {
        // برش طولانی روی فاصله
        var j = 0;
        while (j < p.length && chunks.length < 12) {
          var end = Math.min(j + maxLen, p.length);
          if (end < p.length) {
            var sp = p.lastIndexOf(' ', end);
            if (sp > j + 30) end = sp;
          }
          chunks.push(p.slice(j, end).trim());
          j = end;
        }
        buf = '';
      }
    }
  }
  if (buf) chunks.push(buf);
  return chunks.filter(Boolean).slice(0, 12);
}

/** Google Translate TTS — کیفیت بهتر برای فارسی با تکه‌بندی جمله‌ای */
async function speakGoogleTTS(text, lang) {
  lang = lang || (/[\u0600-\u06FF]/.test(text) ? 'fa' : 'en');
  if (lang === 'fa' || lang === 'fa-IR') {
    text = preparePersianTTS(text);
    lang = 'fa';
  } else {
    text = String(text || '').replace(/\s+/g, ' ').trim();
  }
  if (!text) return null;
  var chunks = chunkForTTS(text, lang === 'fa' ? 120 : 160);
  if (!chunks.length) return null;
  var parts = [];
  for (var c = 0; c < chunks.length; c++) {
    if (!chunks[c]) continue;
    try {
      // client=tw-ob پایدارتر؛ tk ندارد
      var url = 'https://translate.google.com/translate_tts?ie=UTF-8&client=tw-ob&tl=' +
        encodeURIComponent(lang) + '&q=' + encodeURIComponent(chunks[c]);
      var r = await fetchT(url, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
          'Accept': 'audio/mpeg,audio/*;q=0.9,*/*;q=0.5',
          'Referer': 'https://translate.google.com/',
          'Accept-Language': 'fa-IR,fa;q=0.9,en;q=0.5'
        }
      }, 18000);
      if (r && r.ok) {
        var ab = await r.arrayBuffer();
        if (ab && ab.byteLength > 300) parts.push(new Uint8Array(ab));
      }
    } catch (e) {}
  }
  if (!parts.length) return null;
  if (parts.length === 1) return parts[0];
  var total = 0;
  for (var p = 0; p < parts.length; p++) total += parts[p].length;
  var out = new Uint8Array(total);
  var off = 0;
  for (var q = 0; q < parts.length; q++) {
    out.set(parts[q], off);
    off += parts[q].length;
  }
  return out;
}

/**
 * TTS با اولویت کیفیت فارسی:
 * فارسی → Google (طبیعی‌تر) → OpenAI → Workers AI
 * انگلیسی → OpenAI → MeloTTS → Google
 */
async function speak(env, text) {
  text = preparePersianTTS(text).slice(0, 1500);
  if (!text) return null;
  var isFa = /[\u0600-\u06FF]/.test(text);

  // فارسی: اول Google (کیفیت گفتار فارسی بهتر از اکثر مدل‌های رایگان CF)
  if (isFa) {
    try {
      var gFa = await speakGoogleTTS(text, 'fa');
      if (isValidAudioBytes(gFa)) return gFa;
    } catch (e) {}
  }

  // OpenAI — صدای باکیفیت (nova برای وضوح بیشتر)
  try {
    var provs = await collectKeys(env);
    if (provs.openai) {
      var key = pickKey(provs.openai).key;
      var r = await fetchT('https://api.openai.com/v1/audio/speech', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + key,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: 'tts-1-hd',
          voice: isFa ? 'nova' : 'alloy',
          input: text.slice(0, 1000),
          response_format: 'mp3',
          speed: isFa ? 0.95 : 1.0
        })
      }, 50000);
      if (r && r.ok) {
        var ab = await r.arrayBuffer();
        var u8 = ab ? new Uint8Array(ab) : null;
        if (isValidAudioBytes(u8)) return u8;
      }
      // fallback tts-1
      var r2 = await fetchT('https://api.openai.com/v1/audio/speech', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + key,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: 'tts-1',
          voice: 'nova',
          input: text.slice(0, 1000),
          response_format: 'mp3',
          speed: 0.95
        })
      }, 45000);
      if (r2 && r2.ok) {
        var ab2 = await r2.arrayBuffer();
        var u82 = ab2 ? new Uint8Array(ab2) : null;
        if (isValidAudioBytes(u82)) return u82;
      }
    }
  } catch (e) {}

  // Workers AI
  if (env.AI) {
    var models = isFa
      ? [
          { id: CF_TTS_FA, usePrompt: false, lang: 'fa' },
          { id: CF_TTS_EN, usePrompt: true, lang: 'en' }
        ]
      : [
          { id: CF_TTS_EN, usePrompt: true, lang: 'en' },
          { id: '@cf/facebook/mms-tts-eng', usePrompt: false, lang: 'en' }
        ];
    for (var mi = 0; mi < models.length; mi++) {
      var m = models[mi];
      var tries = m.usePrompt
        ? [{ prompt: text, lang: m.lang || 'en' }, { text: text }]
        : [{ text: text }, { prompt: text }];
      for (var ti = 0; ti < tries.length; ti++) {
        try {
          var res = await env.AI.run(m.id, tries[ti]);
          var audio = await normalizeAudioResult(res);
          if (isValidAudioBytes(audio)) return audio;
        } catch (e) {}
      }
    }
  }

  // انگلیسی یا آخرین شانس: Google
  if (!isFa) {
    try {
      var gEn = await speakGoogleTTS(text, 'en');
      if (isValidAudioBytes(gEn)) return gEn;
    } catch (e) {}
  }

  return null;
}

/** ارسال صوت TTS به تلگرام */
async function tgSendVoice(env, chatId, text) {
  if (!FEATURES.tts || !env.TELEGRAM_BOT_TOKEN) return false;
  try {
    await tg(env, 'sendChatAction', { chat_id: chatId, action: 'record_voice' });
    var audio = await speak(env, String(text || '').slice(0, 1500));
    if (!isValidAudioBytes(audio)) {
      try {
        await tgReply(env, chatId,
          '❌ ساخت صدا ناموفق بود (فایل خالی یا مدل قطع).\n' +
          'راه‌حل: دوباره 🔊 بزن یا بفرست:\n/tts متن شما اینجا');
      } catch (e) {}
      return false;
    }
    // ارسال به‌صورت document/audio با بایت خام — جلوگیری از 00:00
    var fd = new FormData();
    fd.append('chat_id', String(chatId));
    fd.append('audio', new Blob([audio], { type: 'audio/mpeg' }), 'nova-tts.mp3');
    fd.append('caption', '🔊 نسخه صوتی');
    fd.append('title', 'Nova TTS');
    fd.append('performer', 'Nova AI');
    var r = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendAudio', {
      method: 'POST', body: fd
    });
    if (r && r.ok) return true;
    // fallback document
    var fd2 = new FormData();
    fd2.append('chat_id', String(chatId));
    fd2.append('document', new Blob([audio], { type: 'audio/mpeg' }), 'nova-tts.mp3');
    fd2.append('caption', '🔊 نسخه صوتی (فایل)');
    var r2 = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendDocument', {
      method: 'POST', body: fd2
    });
    return r2 && r2.ok;
  } catch (e) {
    try { await tgReply(env, chatId, '❌ خطا در ارسال صدا: ' + String(e.message || e).slice(0, 120)); } catch (e2) {}
    return false;
  }
}

/** وضعیت قابلیت‌ها برای پلن رایگان — بدون Vectorize/R2 */
function capabilityReport(env) {
  return {
    version: NOVA_VERSION,
    freeTierOk: true,
    kv: !!env.BOT_KV,
    ai: !!env.AI,
    telegram: !!env.TELEGRAM_BOT_TOKEN,
    vectorize: false,
    r2: false,
    note: 'Vectorize و R2 لازم نیستند. برای صدا: AI binding. برای حافظه: KV.',
    security: {
      cors: env.ALLOWED_ORIGIN ? 'locked' : 'open (*)',
      loginPassSet: !!env.LOGIN_PASS,
      authSecretSet: !!env.AUTH_SECRET,
      adminTokenSet: !!env.ADMIN_TOKEN
    }
  };
}

/** کلیدواژه‌های هشدار اخبار */
async function loadAlertKeywords(env) {
  if (!env.BOT_KV) return [];
  try { return (await env.BOT_KV.get('alert_keywords', 'json')) || []; } catch (e) { return []; }
}
async function saveAlertKeywords(env, list) {
  if (!env.BOT_KV) return;
  try { await env.BOT_KV.put('alert_keywords', JSON.stringify(list || [])); } catch (e) {}
}
async function loadDigestSubs(env) {
  if (!env.BOT_KV) return [];
  try { return (await env.BOT_KV.get('digest_subs', 'json')) || []; } catch (e) { return []; }
}
async function toggleDigestSub(env, chatId, on) {
  if (!env.BOT_KV) return;
  var list = await loadDigestSubs(env);
  chatId = String(chatId);
  list = list.filter(function (x) { return String(x) !== chatId; });
  if (on) list.push(chatId);
  await env.BOT_KV.put('digest_subs', JSON.stringify(list.slice(0, 200)));
}

/** بررسی هشدار روی متن اخبار */
async function checkNewsAlerts(env, newsText) {
  if (!FEATURES.keywordAlerts || !newsText) return;
  var kws = await loadAlertKeywords(env);
  if (!kws.length) return;
  var hits = [];
  var low = String(newsText).toLowerCase();
  kws.forEach(function (kw) {
    if (kw && low.indexOf(String(kw).toLowerCase()) !== -1) hits.push(kw);
  });
  if (!hits.length) return;
  await notifyAdmins(env, '🚨 هشدار خبر\nکلیدواژه: ' + hits.join('، ') + '\n\n' + String(newsText).slice(0, 800));
}

/** ترجیحات خبر کاربر */
async function getUserNewsCats(env, uid) {
  var p = await loadUserPrefs(env, uid);
  return (p && Array.isArray(p.cats)) ? p.cats : [];
}
async function setUserNewsCats(env, uid, cats) {
  var p = await loadUserPrefs(env, uid);
  p.cats = (cats || []).slice(0, 8);
  await saveUserPrefs(env, uid, p);
}

/** خطای دوستانه با پیشنهاد */
function friendlyModelError(err, providerName) {
  if (!FEATURES.friendlyErrors) return '❌ ' + (err || 'خطای مدل');
  var e = String(err || '');
  var tip = '💡 مدل «خودکار» را امتحان کن یا از /models مدل دیگری بساز.';
  if (/401|invalid.?api.?key|unauthorized/i.test(e)) tip = '💡 کلید ' + (providerName || 'این سرویس') + ' نامعتبر است — در پنل ادمین عوض کن.';
  else if (/403|forbidden|region/i.test(e)) tip = '💡 دسترسی رد شد (محدودیت منطقه یا کلید). مدل Cloudflare یا Gemini را امتحان کن.';
  else if (/429|rate.?limit|quota/i.test(e)) tip = '💡 سقف استفاده پر شده. چند دقیقه صبر کن یا مدل دیگری انتخاب کن.';
  else if (/timeout|timed?\s*out/i.test(e)) tip = '💡 مدل دیر جواب داد. دوباره بفرست یا مدل سبک‌تر انتخاب کن.';
  return '❌ ' + e.slice(0, 280) + '\n\n' + tip;
}

/** مقایسه دو مدل */
async function compareModels(env, prompt, modelA, provA, modelB, provB) {
  var msgs = [{ role: 'user', content: String(prompt).slice(0, 2000) }];
  var optsA = { maxTokens: 800, model: modelA, forceExternal: provA !== 'cf' };
  if (provA && provA !== 'cf') optsA.provider = provA;
  var optsB = { maxTokens: 800, model: modelB, forceExternal: provB !== 'cf' };
  if (provB && provB !== 'cf') optsB.provider = provB;
  var results = await Promise.all([
    think(env, msgs, optsA),
    think(env, msgs, optsB)
  ]);
  return {
    a: results[0],
    b: results[1]
  };
}


/** ساخت آهنگ — ModelsLab Song API یا ElevenLabs Music؛ در غیر این صورت متن+TTS */
async function generateMusic(env, prompt, opts) {
  opts = opts || {};
  prompt = String(prompt || '').trim().slice(0, 1500);
  if (!prompt) return { error: 'پرامپت خالی' };

  // 1) Cloudflare Workers AI — رایگان در سقف neurons حساب
  if (env.AI) {
    var cfModels = [
      { id: 'elevenlabs/music-v2', input: function (p) {
        return {
          prompt: p.slice(0, 1000),
          music_length_ms: opts.durationMs || 30000,
          force_instrumental: !!opts.instrumental,
          output_format: 'mp3_48000_128'
        };
      }},
      { id: 'minimax/music-2.6', input: function (p) {
        return {
          prompt: p.slice(0, 1500),
          is_instrumental: !!opts.instrumental,
          lyrics_optimizer: !opts.lyrics,
          lyrics: opts.lyrics || undefined
        };
      }}
    ];
    for (var ci = 0; ci < cfModels.length; ci++) {
      try {
        var cfin = cfModels[ci].input(prompt);
        if (!cfin.lyrics) delete cfin.lyrics;
        var cres = await Promise.race([
          env.AI.run(cfModels[ci].id, cfin),
          new Promise(function (resolve) { setTimeout(function () { resolve(null); }, 90000); })
        ]);
        if (!cres) continue;
        var bytes = null;
        var audioUrl = null;
        if (cres instanceof ReadableStream) {
          bytes = new Uint8Array(await new Response(cres).arrayBuffer());
        } else if (cres instanceof Uint8Array) {
          bytes = cres;
        } else if (cres && cres.audio) {
          if (typeof cres.audio === 'string') {
            if (/^https?:\/\//i.test(cres.audio)) audioUrl = cres.audio;
            else {
              var b64s = String(cres.audio).replace(/^data:audio\/\w+;base64,/, '');
              try {
                var bin = atob(b64s);
                bytes = new Uint8Array(bin.length);
                for (var bi = 0; bi < bin.length; bi++) bytes[bi] = bin.charCodeAt(bi);
              } catch (eB) {}
            }
          } else if (cres.audio instanceof Uint8Array) bytes = cres.audio;
        } else if (cres && cres.result && cres.result.audio) {
          audioUrl = cres.result.audio;
        } else if (cres && typeof cres === 'object') {
          // some bindings return { audio: ArrayBuffer-like }
          var keys = Object.keys(cres);
          for (var ki = 0; ki < keys.length; ki++) {
            var v = cres[keys[ki]];
            if (typeof v === 'string' && /^https?:\/\//i.test(v) && /mp3|audio|wav/i.test(v)) {
              audioUrl = v; break;
            }
          }
        }
        if (audioUrl && !bytes) {
          try {
            var ar = await fetchT(audioUrl, {}, 60000);
            if (ar && ar.ok) {
              var ab = await ar.arrayBuffer();
              if (ab && ab.byteLength > 1000) bytes = new Uint8Array(ab);
            }
          } catch (eDl) {}
        }
        if (bytes && bytes.length > 1000) {
          return {
            type: 'music',
            bytes: bytes,
            mime: 'audio/mpeg',
            caption: '🎵 ' + prompt.slice(0, 80) + '\n— Cloudflare AI · ' + cfModels[ci].id,
            provider: 'cloudflare-ai',
            model: cfModels[ci].id
          };
        }
        if (audioUrl) {
          return {
            type: 'music',
            url: audioUrl,
            caption: '🎵 ' + prompt.slice(0, 80) + '\n— Cloudflare AI · ' + cfModels[ci].id,
            provider: 'cloudflare-ai',
            model: cfModels[ci].id
          };
        }
      } catch (eCf) {
        console.log('[music] cf fail', cfModels[ci].id, eCf && eCf.message);
      }
    }
  }

  // 2) کلیدهای خارجی ModelsLab / ElevenLabs (اگر ثبت شده)
  var keys = [];
  try {
    var provs = await collectKeys(env);
    if (provs.modelslab && provs.modelslab.keys) keys = keys.concat(provs.modelslab.keys.map(function (k) { return { k: k, p: 'modelslab' }; }));
    if (provs.elevenlabs && provs.elevenlabs.keys) keys = keys.concat(provs.elevenlabs.keys.map(function (k) { return { k: k, p: 'elevenlabs' }; }));
  } catch (e) {}
  if (env.MODELSLAB_API_KEY) keys.unshift({ k: env.MODELSLAB_API_KEY, p: 'modelslab' });
  if (env.ELEVENLABS_API_KEY) keys.unshift({ k: env.ELEVENLABS_API_KEY, p: 'elevenlabs' });

  for (var i = 0; i < keys.length; i++) {
    if (keys[i].p !== 'modelslab') continue;
    try {
      var body = {
        key: keys[i].k,
        prompt: prompt,
        lyrics_source: opts.lyrics ? 'user' : 'ai',
        track_name: (opts.title || 'Nova Track').slice(0, 80)
      };
      if (opts.lyrics) body.lyrics = String(opts.lyrics).slice(0, 2000);
      var r = await fetchT('https://modelslab.com/api/v6/voice/song_generator', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      }, 90000);
      if (!r || !r.ok) continue;
      var j = await r.json().catch(function () { return null; });
      if (!j) continue;
      var audioUrl2 = (j.output && j.output[0]) || j.audio || j.url || (j.proxy_links && j.proxy_links[0]);
      var status = j.status;
      var id = j.id || j.job_id;
      if ((!audioUrl2 || status === 'processing' || status === 'queued') && id) {
        for (var poll = 0; poll < 20; poll++) {
          await new Promise(function (res) { setTimeout(res, 4000); });
          var pr = await fetchT('https://modelslab.com/api/v6/voice/fetch/' + id, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ key: keys[i].k })
          }, 30000);
          if (!pr || !pr.ok) continue;
          var pj = await pr.json().catch(function () { return null; });
          if (!pj) continue;
          audioUrl2 = (pj.output && pj.output[0]) || pj.audio || pj.url || (pj.proxy_links && pj.proxy_links[0]);
          if (audioUrl2 && (pj.status === 'success' || pj.status === 'completed')) break;
          if (pj.status === 'failed' || pj.status === 'error') break;
        }
      }
      if (audioUrl2 && typeof audioUrl2 === 'string') {
        var ar2 = await fetchT(audioUrl2, {}, 60000);
        if (ar2 && ar2.ok) {
          var ab2 = await ar2.arrayBuffer();
          if (ab2 && ab2.byteLength > 1000) {
            return {
              type: 'music',
              bytes: new Uint8Array(ab2),
              mime: 'audio/mpeg',
              caption: '🎵 ' + prompt.slice(0, 80),
              provider: 'ModelsLab',
              url: audioUrl2
            };
          }
        }
        return { type: 'music', url: audioUrl2, caption: '🎵 ' + prompt.slice(0, 80), provider: 'ModelsLab' };
      }
    } catch (eML) {}
  }

  for (var e = 0; e < keys.length; e++) {
    if (keys[e].p !== 'elevenlabs') continue;
    try {
      var er = await fetchT('https://api.elevenlabs.io/v1/music', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'xi-api-key': keys[e].k },
        body: JSON.stringify({ prompt: prompt.slice(0, 2000), music_length_ms: opts.durationMs || 30000 })
      }, 120000);
      if (!er || !er.ok) continue;
      var ct = (er.headers.get('content-type') || '').toLowerCase();
      if (ct.indexOf('audio') >= 0 || ct.indexOf('octet') >= 0) {
        var eab = await er.arrayBuffer();
        if (eab && eab.byteLength > 1000) {
          return {
            type: 'music',
            bytes: new Uint8Array(eab),
            mime: ct.indexOf('wav') >= 0 ? 'audio/wav' : 'audio/mpeg',
            caption: '🎵 ' + prompt.slice(0, 80),
            provider: 'ElevenLabs'
          };
        }
      }
    } catch (eEL) {}
  }

  // 3) Fallback: متن آهنگ + TTS رایگان Cloudflare
  try {
    var lyricPrompt = 'Write short song lyrics (verse+chorus) about: ' + prompt + '\nMax 100 words. No explanation.';
    var lr = await think(env, [{ role: 'user', content: lyricPrompt }], { maxTokens: 350 });
    var lyrics = (lr && lr.text) ? String(lr.text).trim() : '';
    if (lyrics.length > 20 && env.AI) {
      try {
        var ttsModel = /[\u0600-\u06FF]/.test(lyrics)
          ? (typeof CF_TTS_FA !== 'undefined' ? CF_TTS_FA : '@cf/facebook/mms-tts-fas')
          : (typeof CF_TTS_EN !== 'undefined' ? CF_TTS_EN : '@cf/myshell-ai/melotts');
        var ttsIn = /melotts/i.test(ttsModel) ? { prompt: lyrics.slice(0, 500) } : { text: lyrics.slice(0, 500) };
        var ttsRes = await env.AI.run(ttsModel, ttsIn);
        var ttsBytes = null;
        if (ttsRes instanceof ReadableStream) ttsBytes = new Uint8Array(await new Response(ttsRes).arrayBuffer());
        else if (ttsRes instanceof Uint8Array) ttsBytes = ttsRes;
        if (ttsBytes && ttsBytes.length > 500) {
          return {
            type: 'music',
            bytes: ttsBytes,
            mime: 'audio/mpeg',
            caption: '🎤 نسخهٔ موقت (متن + TTS)\nاگر مدل آهنگ CF در حسابت فعال نیست، از داشبورد Workers AI مدل elevenlabs/music-v2 را فعال کن.\n\n' + lyrics.slice(0, 350),
            provider: 'tts-fallback',
            lyrics: lyrics
          };
        }
      } catch (eTts) {}
    }
    if (lyrics.length > 20) {
      return {
        type: 'text',
        text: '🎵 متن آهنگ:\n\n' + lyrics +
          '\n\n💡 برای فایل صوتی واقعی:\n• binding AI باید روشن باشد (Workers AI)\n• مدل‌های elevenlabs/music-v2 یا minimax/music-2.6 در حساب Cloudflare\nسقف رایگان neurons روی Workers AI کافی است برای تست.'
      };
    }
  } catch (eFb) {}

  return {
    error: 'ساخت آهنگ ممکن نشد. Workers AI را چک کن (AI binding) یا از پنل یک کلید ModelsLab اضافه کن.'
  };
}


async function drawImage(env, prompt) {
  if (!env.AI) return null;

  var models = [
    { id: '@cf/bytedance/stable-diffusion-xl-lightning', steps: null },
    { id: '@cf/black-forest-labs/flux-1-schnell', steps: 4 }
  ];

  for (var i = 0; i < models.length; i++) {
    try {
      var inputs = { prompt: String(prompt || '').slice(0, 1500) };
      if (models[i].steps) inputs.steps = models[i].steps;

      var res = await Promise.race([
        env.AI.run(models[i].id, inputs),
        new Promise(function(resolve) {
          setTimeout(function(){ resolve(null); }, 25000);
        })
      ]);

      if (!res) continue;

      var out = null;
      if (res instanceof ReadableStream) {
        var ab = await new Response(res).arrayBuffer();
        out = new Uint8Array(ab);
      } else if (res instanceof Uint8Array) {
        out = res;
      } else if (res && res.image && typeof res.image === 'string') {
        var b64str = res.image.replace(/^data:image\/\w+;base64,/, '');
        var bin = atob(b64str);
        out = new Uint8Array(bin.length);
        for (var j = 0; j < bin.length; j++) out[j] = bin.charCodeAt(j);
      } else if (typeof res === 'string') {
        try {
          var bin2 = atob(res);
          out = new Uint8Array(bin2.length);
          for (var k = 0; k < bin2.length; k++) out[k] = bin2.charCodeAt(k);
        } catch(e2) {}
      }
      if (out && out.length > 1000) return out;
    } catch (e) {}
  }
  return null;
}

/** جستجوی عکس واقعی با Tavily (include_images) — روش کد موفق */

/** استوری‌بورد: ۳ فریم سینمایی متوالی (نه ویدیو واقعی) */
async function generateStoryboard(env, prompt) {
  prompt = String(prompt || '').trim().slice(0, 400);
  if (!prompt) return { ok: false, error: 'پرامپت خالی', frames: [] };
  if (!env.AI) return { ok: false, error: 'Workers AI (AI binding) فعال نیست', frames: [] };

  var en = prompt;
  if (/[\u0600-\u06FF]/.test(prompt)) {
    try {
      var tr = await env.AI.run(CF_TRANSLATE, { text: prompt.slice(0, 400), source_lang: 'fa', target_lang: 'en' });
      if (tr && tr.translated_text && String(tr.translated_text).trim().length > 3) {
        en = String(tr.translated_text).trim();
      }
    } catch (eTr) {}
  }
  en = String(en).replace(/[\u0600-\u06FF]+/g, ' ').replace(/\s+/g, ' ').trim() || 'a cinematic scene';

  // سه زاویه/لحظه متوالی برای حس حرکت
  var shotPrompts = [
    en + ', cinematic still, wide establishing shot, frame 1 of 3, beginning of action, film grain, highly detailed, photorealistic, no text, no watermark',
    en + ', cinematic still, medium shot, frame 2 of 3, mid action, dynamic pose, film grain, highly detailed, photorealistic, no text, no watermark',
    en + ', cinematic still, closer shot, frame 3 of 3, end of action, emotional moment, film grain, highly detailed, photorealistic, no text, no watermark'
  ];

  var frames = [];
  for (var fi = 0; fi < shotPrompts.length; fi++) {
    try {
      var fr = await drawImage(env, shotPrompts[fi]);
      if (fr) frames.push({ bytes: fr, caption: '🎬 فریم ' + (fi + 1) + '/3\n' + prompt.slice(0, 80) });
    } catch (eF) {}
  }

  if (!frames.length) {
    return { ok: false, error: 'ساخت فریم‌ها ناموفق بود (مدل تصویر یا سقف Workers AI)', frames: [] };
  }
  return {
    ok: true,
    frames: frames,
    caption: '🎬 استوری‌بورد (' + frames.length + ' فریم) — ویدیو واقعی نیست\n📌 ' + prompt.slice(0, 120)
  };
}



/** تولید ویدیو mp4 واقعی با ModelsLab (نیاز: MODELSLAB_API_KEY) */
async function generateVideoMp4(env, prompt) {
  prompt = String(prompt || '').trim().slice(0, 500);
  if (!prompt) return { ok: false, error: 'پرامپت خالی' };

  var key = null;
  try {
    if (env.MODELSLAB_API_KEY) key = String(env.MODELSLAB_API_KEY).split(',')[0].trim();
    if (!key && env.BOT_KV) {
      var custom = (await env.BOT_KV.get('custom_keys', 'json')) || [];
      for (var i = 0; i < custom.length; i++) {
        if (custom[i] && custom[i].provider === 'modelslab' && custom[i].key) {
          key = String(custom[i].key).trim();
          break;
        }
      }
    }
    if (!key) {
      var provs = await collectKeys(env);
      if (provs.modelslab && provs.modelslab.keys && provs.modelslab.keys.length) {
        key = String(provs.modelslab.keys[0]).trim();
      }
    }
  } catch (eK) {}

  if (!key) {
    return { ok: false, error: 'کلید ModelsLab تنظیم نیست (MODELSLAB_API_KEY در env یا /addkey modelslab KEY)' };
  }

  // ترجمه پرامپت فارسی → انگلیسی برای کیفیت بهتر
  var en = prompt;
  if (/[\u0600-\u06FF]/.test(prompt) && env.AI) {
    try {
      var tr = await env.AI.run(CF_TRANSLATE, { text: prompt.slice(0, 400), source_lang: 'fa', target_lang: 'en' });
      if (tr && tr.translated_text && String(tr.translated_text).trim().length > 3) {
        en = String(tr.translated_text).trim();
      }
    } catch (eTr) {}
  }
  en = String(en).replace(/[\u0600-\u06FF]+/g, ' ').replace(/\s+/g, ' ').trim() || prompt;

  try {
    var body = {
      key: key,
      model_id: 'wan2.2',
      prompt: en + ', cinematic motion, smooth movement',
      negative_prompt: 'low quality, blurry, static, watermark, text, deformed',
      height: 512,
      width: 512,
      num_frames: 25,
      num_inference_steps: 20,
      guidance_scale: 7,
      output_type: 'mp4',
      webhook: null,
      track_id: null
    };
    var r = await fetchT('https://modelslab.com/api/v6/video/text2video', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    }, 25000);
    var t = await r.text();
    var j;
    try { j = JSON.parse(t); } catch (eP) {
      return { ok: false, error: 'پاسخ نامعتبر ModelsLab: ' + String(t).slice(0, 120) };
    }
    if (!j || j.status === 'error') {
      return { ok: false, error: (j && (j.message || j.messege)) || ('HTTP ' + r.status) };
    }

    // اگر همان لحظه success و output دارد
    var outUrl = null;
    if (j.status === 'success' && j.output && j.output.length) {
      outUrl = j.output[0];
    } else if (j.output && j.output.length && /^https?:\/\//i.test(String(j.output[0]))) {
      outUrl = j.output[0];
    }

    var reqId = j.id;
    if (!outUrl && reqId != null) {
      // poll تا حداکثر ~45 ثانیه (محدودیت Worker)
      var deadline = Date.now() + 45000;
      while (Date.now() < deadline) {
        await new Promise(function (res) { setTimeout(res, 4000); });
        try {
          var fr = await fetchT('https://modelslab.com/api/v6/video/fetch/' + reqId, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ key: key })
          }, 15000);
          var ft = await fr.text();
          var fj;
          try { fj = JSON.parse(ft); } catch (e2) { continue; }
          if (fj && fj.status === 'success' && fj.output && fj.output.length) {
            outUrl = fj.output[0];
            break;
          }
          if (fj && (fj.status === 'failed' || fj.status === 'error')) {
            return { ok: false, error: fj.message || 'تولید ویدیو ناموفق' };
          }
        } catch (ePoll) {}
      }
    }

    if (!outUrl) {
      return { ok: false, error: 'زمان ساخت ویدیو تمام شد یا هنوز آماده نیست. کمی بعد دوباره بزن.' };
    }

    // دانلود بایت‌های mp4
    try {
      var vr = await fetchT(outUrl, {}, 60000);
      if (vr && vr.ok) {
        var ab = await vr.arrayBuffer();
        if (ab && ab.byteLength > 2000) {
          return {
            ok: true,
            bytes: new Uint8Array(ab),
            mime: 'video/mp4',
            url: outUrl,
            caption: '🎥 ویدیو mp4\n📌 ' + prompt.slice(0, 100),
            provider: 'ModelsLab'
          };
        }
      }
    } catch (eDl) {}

    // اگر دانلود نشد، حداقل لینک بده
    return {
      ok: true,
      url: outUrl,
      mime: 'video/mp4',
      caption: '🎥 ویدیو آماده است:\n' + outUrl + '\n📌 ' + prompt.slice(0, 80),
      provider: 'ModelsLab'
    };
  } catch (e) {
    return { ok: false, error: e.message || String(e) };
  }
}


async function tavilyImageSearch(query, apiKey) {
  if (!apiKey || !query) return null;
  try {
    var r = await fetchT('https://api.tavily.com/search', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        api_key: apiKey,
        query: query,
        include_images: true,
        max_results: 5
      })
    }, SEARCH_TIMEOUT);
    if (!r || !r.ok) return null;
    var d = await r.json();
    var urls = (d.images || []).map(function (i) {
      return typeof i === 'string' ? i : (i && i.url);
    }).filter(Boolean);
    return urls.length ? urls : null;
  } catch (e) {
    return null;
  }
}

/** دانلود بایت‌های تصویر از URL برای ارسال به تلگرام/وب */
async function downloadImageBytes(url) {
  if (!url) return null;
  try {
    var r = await fetchT(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 NovaAI/23' }
    }, 12000);
    if (!r || !r.ok) return null;
    var ab = await r.arrayBuffer();
    var bytes = new Uint8Array(ab);
    return bytes.length > 1000 ? bytes : null;
  } catch (e) {
    return null;
  }
}


