/* ==== 06_rag_and_core.js — RAG, news, weather, prices, pipeline, digest (lines 2165-4785) ==== */
// ============================================================================
// RAG — Chunk + Embed (bge-m3)
// ============================================================================
/**
 * دو مفهوم اصلی:
 *
 * 1. Chunk (تکه‌بندی)
 *    متن بلند را به قطعات ≈۶۵۰ کاراکتری با همپوشانی ۱۰۰ کاراکتر تقسیم می‌کند
 *    (chunkText). این کار باعث می‌شود هر تکه به‌اندازه کافی کوچک و معنادار
 *    باشد تا embedding دقیق بگیرد و در پاسخ نهایی جا شود.
 *
 * 2. Embed (Embedding با bge-m3)
 *    هر Chunk با مدل @cf/baai/bge-m3 (Cloudflare Workers AI) به یک بردار
 *    عددی چندبعدی تبدیل می‌شود. سوال کاربر هم با همان مدل embed می‌شود،
 *    سپس با cosine similarity نزدیک‌ترین Chunkها به سوال پیدا می‌شوند
 *    (ragQuery) و به‌عنوان context به مدل زبانی داده می‌شوند.
 *
 * جریان کامل:
 *   آپلود فایل → chunkText → embed هر Chunk (bge-m3) → ذخیره در BOT_KV
 *   سوال کاربر → embed سوال (bge-m3) → cosineSim با همه Chunkها →
 *   انتخاب بهترین RAG_TOPK تکه (بالای آستانه RAG_THRESHOLD) → پیام سیستم
 */
function cosineSim(a, b) {
  if (!a || !b || a.length !== b.length) return 0;
  var dot = 0, na = 0, nb = 0;
  for (var i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  var d = Math.sqrt(na) * Math.sqrt(nb);
  return d ? dot / d : 0;
}

function chunkText(t) {
  var out = [];
  var clean = t.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (!clean) return out;

  var paragraphs = clean.split(/\n{2,}/);
  var current = '';

  for (var i = 0; i < paragraphs.length; i++) {
    var p = paragraphs[i].trim();
    if (!p) continue;

    if ((current + '\n\n' + p).length > RAG_CHUNK) {
      if (current.length > 40) out.push(current.trim());
      current = p;
    } else {
      current = current ? current + '\n\n' + p : p;
    }

    while (current.length > RAG_CHUNK + 200) {
      var cut = current.slice(0, RAG_CHUNK);
      var lastDot = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('?'), cut.lastIndexOf('\n'));
      if (lastDot > RAG_CHUNK * 0.6) {
        out.push(current.slice(0, lastDot + 1).trim());
        current = current.slice(lastDot + 1).trim();
      } else {
        out.push(cut.trim());
        current = current.slice(RAG_CHUNK - RAG_OVERLAP).trim();
      }
    }
  }
  if (current.length > 40) out.push(current.trim());
  return out.slice(0, 400);
}

async function ragIngest(env, name, text) {
  if (!env.AI || !env.BOT_KV) return { ok: false, reason: 'AI يا KV در دسترس نيست' };
  if (!text || text.trim().length < 30) return { ok: false, reason: 'متن خيلي کوتاه است' };

  var chunks = chunkText(text.slice(0, 400000));
  if (!chunks.length) return { ok: false, reason: 'نتوانست متن را تکه‌بندي کند' };

  var vecs = [];
  for (var i = 0; i < chunks.length; i += 12) {
    try {
      var batch = chunks.slice(i, i + 12);
      var res = await env.AI.run(CF_EMBED, { text: batch });
      var v = res && (res.data || (res.result && res.result.data));
      if (!v || !v.length) return { ok: false, reason: 'خطا در ساخت embedding' };
      vecs = vecs.concat(v);
    } catch (e) {
      return { ok: false, reason: 'خطاي embedding: ' + e.message };
    }
  }

  if (vecs.length !== chunks.length) {
    return { ok: false, reason: 'تعداد بردار با تکه‌ها برابر نیست' };
  }

  var id = 'doc_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  await env.BOT_KV.put('rag:' + id, JSON.stringify({
    name: name,
    chunks: chunks,
    vecs: vecs,
    ts: Date.now(),
    size: text.length
  }));

  var meta = (await env.BOT_KV.get('docs_meta', 'json')) || [];
  meta.unshift({
    id: id,
    name: name,
    chunks: chunks.length,
    size: text.length,
    ts: Date.now()
  });
  await env.BOT_KV.put('docs_meta', JSON.stringify(meta.slice(0, 150)));
  return { ok: true, id: id, chunks: chunks.length };
}

async function ragQuery(env, query) {
  if (!env.AI || !env.BOT_KV) return '';
  var meta = (await env.BOT_KV.get('docs_meta', 'json')) || [];
  if (!meta.length) return '';

  var qr = await env.AI.run(CF_EMBED, { text: [query.slice(0, 900)] });
  var qv = qr && qr.data && qr.data[0];
  if (!qv) return '';

  var scored = [];
  var maxDocs = Math.min(meta.length, 30);

  for (var d = 0; d < maxDocs; d++) {
    try {
      var doc = await env.BOT_KV.get('rag:' + meta[d].id, 'json');
      if (!doc || !doc.chunks || !doc.vecs) continue;

      for (var c = 0; c < doc.chunks.length; c++) {
        if (!doc.vecs[c]) continue;
        var sc = cosineSim(qv, doc.vecs[c]);
        if (sc >= RAG_THRESHOLD) {
          scored.push({
            score: sc,
            text: doc.chunks[c],
            doc: doc.name
          });
        }
      }
    } catch (e) {}
  }

  if (!scored.length) return '';
  scored.sort(function (a, b) { return b.score - a.score; });

  var top = [];
  var seen = {};
  for (var i = 0; i < scored.length && top.length < RAG_TOPK; i++) {
    var key = scored[i].text.slice(0, 80);
    if (seen[key]) continue;
    seen[key] = true;
    top.push(scored[i]);
  }

  if (!top.length) return '';

  return top.map(function (s, idx) {
    return `📄 منبع ${idx + 1}: «${s.doc}» (شباهت: ${(s.score * 100).toFixed(1)}%)\n${s.text.slice(0, 700)}`;
  }).join('\n\n---\n\n');
}

async function ragGetDoc(env, id) {
  if (!env.BOT_KV || !id) return null;
  try {
    return await env.BOT_KV.get('rag:' + id, 'json');
  } catch (e) { return null; }
}

async function ragGetText(env, id) {
  var doc = await ragGetDoc(env, id);
  if (!doc || !doc.chunks) return null;
  return {
    id: id,
    name: doc.name || id,
    text: (doc.chunks || []).join('\n\n'),
    chunks: (doc.chunks || []).length,
    size: doc.size || 0,
    ts: doc.ts || 0
  };
}

/** جایگزینی سند: حذف قبلی + ایندکس متن جدید */
async function ragReplace(env, id, name, text) {
  await ragDelete(env, id);
  return ragIngest(env, name || 'سند', text);
}

async function ragDelete(env, id) {
  if (!env.BOT_KV) return;
  await env.BOT_KV.delete('rag:' + id);
  var meta = (await env.BOT_KV.get('docs_meta', 'json')) || [];
  await env.BOT_KV.put('docs_meta', JSON.stringify(meta.filter(function (d) {
    return d.id !== id;
  })));
}
