  'بندرعباس': 'Bandar Abbas', 'اراک': 'Arak', 'زنجان': 'Zanjan',
  'سنندج': 'Sanandaj', 'قزوین': 'Qazvin', 'گرگان': 'Gorgan',
  'ساری': 'Sari', 'بوشهر': 'Bushehr', 'ایلام': 'Ilam',
