/** Constant-time-ish string compare */
function safeEq(a, b) {
  a = String(a || ''); b = String(b || '');
  var max = Math.max(a.length, b.length, 1);
  var diff = a.length ^ b.length;
  for (var i = 0; i < max; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}

/** Simple math CAPTCHA — no external service */
function makeCaptchaChallenge() {
  var a = 2 + Math.floor(Math.random() * 12);
  var b = 1 + Math.floor(Math.random() * 9);
  var op = (Math.random() < 0.35 && a > b) ? '-' : '+';
  var ans = op === '+' ? (a + b) : (a - b);
  return { question: a + ' ' + op + ' ' + b + ' = ?', answer: String(ans) };
}
async function captchaSign(env, answer, ts) {
  return hmac(authSecret(env), 'captcha.' + String(answer) + '.' + String(ts));
}
async function issueCaptcha(env) {
  var ch = makeCaptchaChallenge();
  var ts = Date.now().toString(36);
  var sig = await captchaSign(env, ch.answer, ts);
  return { question: ch.question, token: ts + '|' + sig };
}
async function verifyCaptcha(env, token, userAnswer) {
  if (!token || userAnswer == null || String(userAnswer).trim() === '') return false;
  var parts = String(token).split('|');
  if (parts.length !== 2) return false;
  var ts = parts[0], sig = parts[1];
  var ans = String(userAnswer).trim().replace(/[^\d-]/g, '');
  var expect = await captchaSign(env, ans, ts);
  if (!safeEq(expect, sig)) return false;
  try {
    var ms = parseInt(ts, 36);
    if (!isFinite(ms) || (Date.now() - ms) > 10 * 60 * 1000) return false;
  } catch (e) { return false; }
  return true;
}



/** bytes <-> base64url helpers for split key */
function bytesToB64url(u8) {
  var bin = '';
  for (var i = 0; i < u8.length; i++) bin += String.fromCharCode(u8[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function b64urlToBytes(s) {
  s = String(s || '').replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  var bin = atob(s);
  var out = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
function xorBytes(a, b) {
  var n = Math.min(a.length, b.length);
  var out = new Uint8Array(n);
  for (var i = 0; i < n; i++) out[i] = a[i] ^ b[i];
  return out;
}
async function sha256Hex(bytes) {
  var buf = await crypto.subtle.digest('SHA-256', bytes);
  var u8 = new Uint8Array(buf);
  var hex = '';
  for (var i = 0; i < u8.length; i++) hex += ('0' + u8[i].toString(16)).slice(-2);
  return hex;
}

/**
 * Split-key state in KV:
 *   admin_split: { serverHalfB64, secretHash, created, version }
 * Admin keeps clientHalf as file (text or photo caption / binary).
 * Full secret = clientHalf XOR serverHalf; hash must match secretHash.
 */
async function getAdminSplit(env) {
  if (!env.BOT_KV) return null;
  try { return await env.BOT_KV.get('admin_split', 'json'); } catch (e) { return null; }
}

/** Generate or rotate split key. Returns { clientHalfB64, serverStored: true } for admin download once. */
async function setupAdminSplitKey(env, force) {
  if (!env.BOT_KV) return { error: 'BOT_KV required' };
  var existing = await getAdminSplit(env);
  if (existing && existing.secretHash && !force) {
    return { error: 'already_set', message: 'کلید دو‌تکه از قبل تنظیم شده. برای چرخش force=1 بفرست.' };
  }
  var secret = new Uint8Array(32);
  var pad = new Uint8Array(32);
  crypto.getRandomValues(secret);
  crypto.getRandomValues(pad);
  var clientHalf = xorBytes(secret, pad);
  var hash = await sha256Hex(secret);
  await env.BOT_KV.put('admin_split', JSON.stringify({
    serverHalfB64: bytesToB64url(pad),
    secretHash: hash,
    created: Date.now(),
    version: 1
  }));
  return {
    ok: true,
    clientHalfB64: bytesToB64url(clientHalf),
    message: 'نیمهٔ ادمین را دانلود و امن نگه دار. نیمهٔ سرور فقط در KV است.'
  };
}

/** Verify uploaded client half against server half */
async function verifyAdminSplitPiece(env, clientHalfRaw) {
  var st = await getAdminSplit(env);
  if (!st || !st.serverHalfB64 || !st.secretHash) {
    // Fallback: if ADMIN_KEY_HALF env set as full shared secret piece
    if (env.ADMIN_KEY_HALF) {
      var expected = String(env.ADMIN_KEY_HALF).trim();
      var got = String(clientHalfRaw || '').trim().replace(/\s+/g, '');
      return safeEq(got, expected);
    }
    return false;
  }
  try {
    var raw = String(clientHalfRaw || '').trim().replace(/\s+/g, '');
    // accept base64url text, or extract from data-url / pure b64
    if (/^data:/.test(raw)) {
      var idx = raw.indexOf('base64,');
      if (idx !== -1) raw = raw.slice(idx + 7).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }
    var client = b64urlToBytes(raw);
    var server = b64urlToBytes(st.serverHalfB64);
    if (client.length !== 32 || server.length !== 32) return false;
    var secret = xorBytes(client, server);
    var hash = await sha256Hex(secret);
    return safeEq(hash, st.secretHash);
  } catch (e) {
    return false;
  }
}

