      if (!nxPP || !nxMM2) return jsonError('سرویس و مدل لازم است', cors);
      nxExtra[nxPP] = nxExtra[nxPP] || [];
      if (nxExtra[nxPP].indexOf(nxMM2) === -1) nxExtra[nxPP].unshift(nxMM2);
      await env.BOT_KV.put('extra_models', JSON.stringify(nxExtra));
