    var eidx = parseInt(bEdit.idx, 10);
    if (!env.BOT_KV) return jsonError('KV لازم است', cors, 503);
    var cksE = (await env.BOT_KV.get('custom_keys', 'json')) || [];
    if (isNaN(eidx) || eidx < 0 || eidx >= cksE.length) return jsonError('ایندکس نامعتبر', cors);
    if (bEdit.key) cksE[eidx].key = String(bEdit.key).trim();
    if (bEdit.name) cksE[eidx].name = String(bEdit.name).trim();
