/* ==== 09_telegram.js — Telegram send/process, commands, message pipeline (lines 6434-10010) ==== */
// ============================================================================
// Telegram
// ============================================================================
async function tg(env, method, payload) {
  var r = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/' + method, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload || {})
  });
  return r.json();
}

async function tgDownload(env, fileId) {
  var info = await tg(env, 'getFile', { file_id: fileId });
  if (!info || !info.result || !info.result.file_path) return null;
  var r = await fetch('https://api.telegram.org/file/bot' + env.TELEGRAM_BOT_TOKEN + '/' + info.result.file_path);
  return r.ok ? await r.arrayBuffer() : null;
}

async function tgReply(env, chatId, text, extra) {
  text = String(text == null ? '' : text);
  for (var i = 0; i < text.length; i += 4000) {
    var payload = Object.assign({ chat_id: chatId, text: text.slice(i, i + 4000) }, extra || {});
    await tgSendSafe(env, 'sendMessage', payload, 2);
  }
}
/**
 * ارسال پاسخ به صورت Streaming (پیام اول + ویرایش تدریجی) - v26.13
 */
async function tgReplyStream(env, chatId, text, extra) {
  text = String(text == null ? '' : text);
  if (!text || text.length < 40) {
    return tgReply(env, chatId, text, extra);
  }

  // حالت فکر کردن — زیباتر
  var placeholder = '🧠 Nova در حال فکر کردن...\n▌';
  var sent;
  try {
    sent = await tgSendSafe(env, 'sendMessage', Object.assign({
      chat_id: chatId,
      text: placeholder
    }, extra || {}), 1);
  } catch (e) {
    return tgReply(env, chatId, text, extra);
  }

  if (!sent || !sent.ok || !sent.result || !sent.result.message_id) {
    return tgReply(env, chatId, text, extra);
  }

  var msgId = sent.result.message_id;
  // تایپ طبیعی: روی مرز کلمه/فاصله برش بزن
  var parts = [];
  var buf = '';
  var words = text.split(/(\s+)/);
  for (var w = 0; w < words.length; w++) {
    buf += words[w];
    if (buf.length >= 70 || w === words.length - 1) {
      parts.push(buf);
      buf = '';
    }
  }
  if (!parts.length) parts = [text];
  var shown = '';
  var lastEdit = 0;

  for (var p = 0; p < parts.length; p++) {
    shown += parts[p];
    var now = Date.now();
    var wait = 220 - (now - lastEdit);
    if (wait > 0 && p < parts.length - 1) {
      await new Promise(function (r) { setTimeout(r, wait); });
    }
    lastEdit = Date.now();
    try {
      await tg(env, 'editMessageText', {
        chat_id: chatId,
        message_id: msgId,
        text: shown + (p < parts.length - 1 ? '▌' : ''),
        parse_mode: (extra && extra.parse_mode) || undefined,
        reply_markup: (extra && extra.reply_markup) || undefined
      });
    } catch (e) {
      break;
    }
  }

  try {
    await tg(env, 'editMessageText', {
      chat_id: chatId,
      message_id: msgId,
      text: text.slice(0, 4090),
      parse_mode: (extra && extra.parse_mode) || undefined,
      reply_markup: (extra && extra.reply_markup) || undefined
    });
  } catch (e) {
    await tgReply(env, chatId, text, extra);
  }
}


/** ارسال کد به‌صورت فایل قابل دانلود در تلگرام */
async function tgSendCodeFile(env, chatId, block) {
  if (!env.TELEGRAM_BOT_TOKEN || !block || !block.code) return false;
  try {
    var ext = block.ext || 'txt';
    var fname = block.filename || ('nova-code.' + ext);
    var mimeMap = {
      html: 'text/html;charset=utf-8',
      htm: 'text/html;charset=utf-8',
      css: 'text/css;charset=utf-8',
      js: 'text/javascript;charset=utf-8',
      mjs: 'text/javascript;charset=utf-8',
      json: 'application/json;charset=utf-8',
      xml: 'application/xml;charset=utf-8',
      svg: 'image/svg+xml',
      py: 'text/x-python;charset=utf-8',
      md: 'text/markdown;charset=utf-8'
    };
    var mime = mimeMap[ext] || 'text/plain;charset=utf-8';
    var langLabel = block.lang || ext;
    var caption = '💻 ' + fname + ' · ' + langLabel;
    if (ext === 'html') caption = '🌐 ' + fname + ' · صفحه وب (HTML) — دانلود و در مرورگر باز کن';
    else if (ext === 'py') caption = '🐍 ' + fname + ' · پایتون — دانلود و اجرا کن';
    else if (ext === 'js') caption = '🟨 ' + fname + ' · JavaScript';
    var fd = new FormData();
    fd.append('chat_id', String(chatId));
    fd.append('document', new Blob([block.code], { type: mime }), fname);
    fd.append('caption', caption.slice(0, 200));
    var r = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendDocument', {
      method: 'POST', body: fd
    });
    return r && r.ok;
  } catch (e) {
    return false;
  }
}

/** Store short callback tokens for long model ids (Telegram 64-byte limit) */
async function saveModelCallbackMap(env, chatId, map) {
  if (env.BOT_KV) {
    try {
      await env.BOT_KV.put('tg_model_cb_' + chatId, JSON.stringify(map), { expirationTtl: 86400 });
    } catch (e) {}
  }
}
async function loadModelCallbackMap(env, chatId) {
  if (!env.BOT_KV) return {};
  try {
    return (await env.BOT_KV.get('tg_model_cb_' + chatId, 'json')) || {};
  } catch (e) {
    return {};
  }
}


/** نمایش مدل‌های رایگان + وضعیت کلید Apmix/سایر */
async function showFreeConnectedModels(env, chatId, uid) {
  var emojiMap = await loadEmojiMap(env);
  var working = await getWorkingModels(env, true);
  var myKeys = [];
  try { myKeys = await getUserKeys(env, uid); } catch (e) {}
  var lines = ['🆓 مدل‌های رایگان و اتصال کلید\n'];

  // کلیدهای سیستم (env)
  var sysProvs = await collectKeys(env);
  var apxOk = !!(sysProvs.apx && sysProvs.apx.keys && sysProvs.apx.keys.length);
  if (apxOk) {
    lines.push('✅ Apmix.ai — کلید سیستم وصل است');
  } else {
    lines.push('⚪ Apmix.ai — کلید سیستم نیست (env: APX_API_KEY)');
  }

  // کلیدهای شخصی کاربر
  var userApx = myKeys.filter(function (k) {
    return (k.provider === 'apx') || /^apx_live_/i.test(k.key || '');
  });
  if (userApx.length) {
    lines.push('🔑 کلید شخصی Apmix: ' + userApx.length + ' عدد');
  }

  // لیست مدل‌های رایگان از working
  var freeList = [];
  Object.keys(working).forEach(function (pid) {
    (working[pid].models || []).forEach(function (m) {
      if (isFreeModel(m)) freeList.push({ p: pid, m: m, name: working[pid].name || pid });
    });
  });
  // اگر apx هست ولی free در working نبود، fallback رایگان
  if (apxOk || userApx.length) {
    var hasApxFree = freeList.some(function (x) { return x.p === 'apx'; });
    if (!hasApxFree) {
      freeList.unshift({ p: 'apx', m: 'claude-sonnet-4-6-free', name: 'Apmix.ai' });
    }
  }

  if (!freeList.length) {
    lines.push('\n❌ فعلاً مدل رایگانی در سرویس‌های وصل‌شده نیست.');
    lines.push('➕ /addkey apx apx_live_...  یا  env APX_API_KEY');
    lines.push('📖 /freekeys');
    await tgReply(env, chatId, lines.join('\n'));
    return;
  }

  lines.push('\nمدل‌های رایگان قابل استفاده (' + freeList.length + '):\n');
  var cbMap = {};
  var buttons = [];
  freeList.slice(0, 20).forEach(function (x, i) {
    var tok = 'f' + i;
    cbMap[tok] = { m: x.m, p: x.p };
    var label = ('🆓 ' + shortModelName(x.m) + ' · ' + x.name).slice(0, 60);
    buttons.push([{ text: label, callback_data: 'model:' + tok }]);
    lines.push('• ' + x.m + '  (' + x.name + ')');
  });
  buttons.push([{ text: '🤖 خودکار', callback_data: 'model:auto' }]);
  buttons.push([{ text: '📋 همه مدل‌ها', callback_data: 'mp:_:0' }]);
  await saveModelCallbackMap(env, chatId, cbMap);
  await tg(env, 'sendMessage', {
    chat_id: chatId,
    text: lines.join('\n').slice(0, 3500),
    reply_markup: { inline_keyboard: buttons }
  });
}

async function showModels(env, chatId) {
  var uid = 'tg_' + chatId;
  var role = await getUserRole(env, uid);
  if (role !== 'public') { await showProviderMenu(env, chatId, uid, role, null); return; }

  // عمومی: خودکار + در صورت داشتن کلید شخصی
  if (role === 'public') {
    var pubKeys = await getUserKeys(env, uid);
    var pubBtns = [[{ text: '🤖 خودکار (هوشمند)', callback_data: 'model:auto' }]];
    var pubMap = {};
    var pubIdx = 0;
    if (pubKeys.length) {
      pubKeys.forEach(function (k) {
        var tok = 'm' + (pubIdx++);
        pubMap[tok] = { m: 'userkey:' + k.id, p: k.provider || '' };
        pubBtns.push([{ text: ('🔑 ' + (k.name || k.provider || 'کلید')).slice(0, 60), callback_data: 'model:' + tok }]);
      });
      await saveModelCallbackMap(env, chatId, pubMap);
    } else {
      pubBtns.push([{ text: '📖 دریافت کلید رایگان', callback_data: 'model:freekeys' }]);
    }
    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: pubKeys.length
        ? '🎯 مدل‌ها\n✅ کلید شخصی دارید — با همان چت کنید.\n➕ /addkey · 📖 /freekeys'
        : '🎯 مدل‌ها (کاربر عمومی)\n\n• خودکار — سقف ' + PUBLIC_MSG_LIMIT + ' پیام\n• برای نامحدود:\n  1️⃣ /freekeys → کلید رایگان بگیر\n  2️⃣ /addkey gemini KEY → ثبت کن\n  3️⃣ دوباره /models',
      reply_markup: { inline_keyboard: pubBtns }
    });
    return;
  }

  var disc = await getWorkingModels(env);
  var buttons = [];
  var cbMap = {};
  var cbIdx = 0;

  function addModelBtn(label, modelId, pid) {
    var token = 'm' + (cbIdx++);
    cbMap[token] = { m: modelId, p: pid || '' };
    buttons.push([{ text: label.slice(0, 60), callback_data: 'model:' + token }]);
  }

  buttons.push([{ text: '🤖 خودکار (هوشمند)', callback_data: 'model:auto' }]);

  if (disc.cf && disc.cf.models && disc.cf.models.length) {
    addModelBtn('☁️ ' + disc.cf.models[0].replace('@cf/meta/', '') + ' (CF)', disc.cf.models[0], 'cf');
  } else if (env.AI) {
    addModelBtn('☁️ Llama 3.3 70B (Cloudflare)', '@cf/meta/llama-3.3-70b-instruct-fp8-fast', 'cf');
  }

  // VIP: فقط کلیدهای شخصی خودش
  if (role === 'vip') {
    var myKeys = await getUserKeys(env, uid);
    if (!myKeys.length) {
      buttons.push([{ text: '➕ افزودن کلید (/addkey)', callback_data: 'model:addkey' }]);
    } else {
      myKeys.forEach(function (k) {
        addModelBtn('🔑 ' + (k.name || k.provider || 'کلید'), 'userkey:' + k.id, k.provider);
      });
    }
    await saveModelCallbackMap(env, chatId, cbMap);
    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: '🎯 مدل‌ها (ویژه — کلید شخصی)\n/addkey PROVIDER KEY',
      reply_markup: { inline_keyboard: buttons }
    });
    return;
  }

  // ادمین: همه مدل‌ها با آیکن
  var order = ['tokenharbor', 'google_studio', 'gemini', 'groq', 'openrouter', 'nvidia', 'mistral', 'zai', 'ollama', 'xai', 'cerebras', 'openai'];
  var icons = {
    tokenharbor: '🔹', groq: '⚡', google_studio: '🟢', gemini: '✨',
    openrouter: '🌐', xai: '🚀', cerebras: '🧠', nvidia: '🟩',
    mistral: '🌬️', zai: '🔷', ollama: '🦙', openai: '🟢'
  };

  order.forEach(function (pid) {
    if (!disc[pid] || !disc[pid].models) return;
    disc[pid].models.slice(0, 3).forEach(function (m) {
      var short = m.length > 28 ? m.slice(0, 26) + '…' : m;
      addModelBtn((icons[pid] || '•') + ' ' + short + ' (' + (disc[pid].name || pid) + ')', m, pid);
    });
  });

  Object.keys(disc).forEach(function (pid) {
    if (order.indexOf(pid) !== -1 || pid === 'cf') return;
    if (!disc[pid] || !disc[pid].models) return;
    disc[pid].models.slice(0, 3).forEach(function (m) {
      var short = m.length > 28 ? m.slice(0, 26) + '…' : m;
      var name = disc[pid].name || pid;
      var icon = String(pid).indexOf('custom_') === 0 ? '🆕' : '•';
      addModelBtn(icon + ' ' + short + ' (' + name + ')', m, pid);
    });
  });

  // مدل‌های دست‌ساز کاربر در انتهای ادمین
  try {
    var customs = await getUserModels(env, uid);
    customs.forEach(function (x) {
      if (!x || !x.m) return;
      addModelBtn('⭐ ' + x.m + ' (' + (x.p || '?') + ')', x.m, x.p);
    });
  } catch (e) {}

  await saveModelCallbackMap(env, chatId, cbMap);
  await tg(env, 'sendMessage', {
    chat_id: chatId,
    text: '🎯 انتخاب مدل (ادمین):\n• آیکن هر AI کنار نام مدل\n• سایت‌های سفارشی (🆕) در لیست‌اند\n• مدل دست‌ساز: /addmodel',
    reply_markup: { inline_keyboard: buttons }
  });
}

