async function fetchCryptoPricesFull() {
  // ۱) Binance Vision — از Workers معمولاً در دسترس است (api.binance.com گاهی 451 می‌دهد)
  var bases = [
    'https://data-api.binance.vision',
    'https://api1.binance.com',
    'https://api.binance.com'
  ];
  for (var b = 0; b < bases.length; b++) {
    try {
      var r = await fetchT(bases[b] + '/api/v3/ticker/24hr', {
        headers: { 'Accept': 'application/json' }
      }, 12000);
      if (!r || !r.ok) continue;
      var arr = await r.json();
      if (!Array.isArray(arr) || !arr.length) continue;
      var bySym = {};
      arr.forEach(function (t) { if (t && t.symbol) bySym[t.symbol] = t; });
      var out = {};
      Object.keys(CRYPTO_META).forEach(function (id) {
        if (id === 'tether') {
          out[id] = { usd: 1, usd_24h_change: 0 };
          return;
        }
        var sym = CRYPTO_BINANCE[id];
        var t = sym ? bySym[sym] : null;
        // fallback نمادهای قدیمی
        if (!t && id === 'matic-network') t = bySym['MATICUSDT'] || bySym['POLUSDT'];
        if (!t && id === 'render_token') t = bySym['RENDERUSDT'] || bySym['RNDRUSDT'];
        if (!t || t.lastPrice == null) return;
        var price = parseFloat(t.lastPrice);
        if (!isFinite(price) || price <= 0) return;
        out[id] = {
          usd: price,
          usd_24h_change: parseFloat(t.priceChangePercent || 0)
        };
      });
      if (Object.keys(out).length >= 3) return { _src: 'Binance', data: out };
    } catch (e) {}
  }

  // ۲) Coinbase public
  try {
    var cbMap = {
      bitcoin: 'BTC', ethereum: 'ETH', solana: 'SOL', litecoin: 'LTC',
      chainlink: 'LINK', dogecoin: 'DOGE', cardano: 'ADA', polkadot: 'DOT',
      'binancecoin': 'BNB', ripple: 'XRP', uniswap: 'UNI', stellar: 'XLM',
      cosmos: 'ATOM', near: 'NEAR', 'avalanche-2': 'AVAX'
    };
    var outCb = { tether: { usd: 1, usd_24h_change: 0 } };
    var idsCb = Object.keys(cbMap);
    await Promise.all(idsCb.map(async function (id) {
      try {
        var rc = await fetchT('https://api.coinbase.com/v2/prices/' + cbMap[id] + '-USD/spot', {
          headers: { 'Accept': 'application/json' }
        }, 6000);
        if (!rc || !rc.ok) return;
        var jc = await rc.json();
        var price = jc && jc.data && parseFloat(jc.data.amount);
        if (price) outCb[id] = { usd: price, usd_24h_change: null };
      } catch (e) {}
    }));
    if (Object.keys(outCb).length >= 3) return { _src: 'Coinbase', data: outCb };
  } catch (e) {}

  // ۳) CoinGecko (گاهی rate-limit)
  try {
    var ids = Object.keys(CRYPTO_META).join(',');
    var url = 'https://api.coingecko.com/api/v3/simple/price?ids=' + ids +
      '&vs_currencies=usd&include_24hr_change=true';
    var r2 = await fetchT(url, {
      headers: { 'Accept': 'application/json', 'User-Agent': 'Mozilla/5.0 NovaAI/26' }
    }, 12000);
    if (r2 && r2.ok) {
      var d2 = await r2.json();
      if (d2 && typeof d2 === 'object' && !d2.status) return { _src: 'CoinGecko', data: d2 };
    }
  } catch (e) {}

  return null;
}

function formatCryptoReportFull(payload) {
  if (!payload || !payload.data) return '❌ دریافت قیمت ممکن نشد. کمی بعد دوباره امتحان کن.';
  var data = payload.data;
  var src = payload._src || 'API';
  // \u200E = LTR mark تا در چت فارسی ترتیب قیمت به‌هم نریزد
  var LTR = '\u200E';
  var lines = [LTR + '💰 قیمت ارزهای دیجیتال (به‌روز)'];
  var order = Object.keys(CRYPTO_META);
  var shown = 0;
  order.forEach(function (id) {
    var meta = CRYPTO_META[id];
    var row = data[id];
    if (!meta || !row || row.usd == null) return;
    var price = Number(row.usd);
    if (!isFinite(price)) return;
    var change = row.usd_24h_change;
    var changeStr = '';
    if (change != null && !isNaN(Number(change))) {
      var c = Number(change);
      changeStr = '  ' + (c >= 0 ? '🟢 +' : '🔴 ') + Math.abs(c).toFixed(2) + '%';
    }
    var priceStr;
    if (price >= 1000) priceStr = price.toLocaleString('en-US', { maximumFractionDigits: 2 });
    else if (price >= 1) priceStr = price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    else if (price >= 0.01) priceStr = price.toFixed(4);
    else priceStr = price.toFixed(8);
    // یک خط ثابت: آیکن نام (نماد) — $قیمت تغییر
    lines.push(LTR + meta.icon + ' ' + meta.name + ' (' + meta.symbol + ') — $' + priceStr + changeStr);
    shown++;
  });
  if (!shown) return '❌ دریافت قیمت ممکن نشد. کمی بعد دوباره امتحان کن.';
  lines.push('');
  lines.push(LTR + '⏰ ' + nowFa() + ' · منبع: ' + src);
  return lines.join('\n');
}


/** Reply keyboard markup — غیرثابت تا کاربر بتواند جمعش کند */
function tgKeyboardMarkup(rows, opts) {
  opts = opts || {};
  var persistent = FEATURES.kbPersistent === true;
  if (opts.persistent === true) persistent = true;
  if (opts.persistent === false) persistent = false;
  return {
    keyboard: rows,
    resize_keyboard: true,
    is_persistent: persistent,
    one_time_keyboard: !!opts.oneTime,
    input_field_placeholder: opts.placeholder || 'پیام بنویسید...'
  };
}

/** صف جمع‌کردن کیبورد بعد از چند ثانیه (با waitUntil در webhook) */
function queueHideKeyboard(env, chatId, sec) {
  if (!FEATURES.kbAutoHide) return;
  if (!env) return;
  chatId = String(chatId || '');
  if (!chatId) return;
  if (!env.__kbHideJobs) env.__kbHideJobs = [];
  // جلوگیری از صف تکراری برای یک چت
  if (env.__kbHideJobs.indexOf(chatId) === -1) env.__kbHideJobs.push(chatId);
  env.__kbHideSec = sec || 10;
}

async function flushHideKeyboardJobs(env, ctx) {
  if (!FEATURES.kbAutoHide || !env || !env.__kbHideJobs || !env.__kbHideJobs.length) return;
  var jobs = env.__kbHideJobs.slice();
  var sec = env.__kbHideSec || 10;
  env.__kbHideJobs = [];
  var p = (async function () {
    try {
      await new Promise(function (r) { setTimeout(r, Math.max(3, sec) * 1000); });
      for (var i = 0; i < jobs.length; i++) {
        var chatId = jobs[i];
        try {
          var r = await tgSendSafe(env, 'sendMessage', {
            chat_id: chatId,
            text: '⬇️ کیبورد جمع شد — باز کردن: /menu',
            reply_markup: { remove_keyboard: true },
            disable_notification: true
          }, 1);
          if (r && r.ok && r.result && r.result.message_id) {
            var mid = r.result.message_id;
            await new Promise(function (r2) { setTimeout(r2, 2800); });
            try { await tg(env, 'deleteMessage', { chat_id: chatId, message_id: mid }); } catch (eDel) {}
          }
        } catch (eOne) {}
      }
    } catch (eAll) {}
  })();
  if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(p);
  else try { await p; } catch (e) {}
}

async function hideKeyboardNow(env, chatId, notice) {
  try {
    await tgSendSafe(env, 'sendMessage', {
      chat_id: chatId,
      text: notice || '⬇️ کیبورد بسته شد.\nبرای باز کردن دوباره بفرست: /menu',
      reply_markup: { remove_keyboard: true },
      disable_notification: true
    }, 1);
  } catch (e) {}
}

