async function getTgKeyboardConfig(env) {
  var def = defaultTgKeyboardConfig();
  if (!env || !env.BOT_KV) return def;
  try {
    var saved = await env.BOT_KV.get('tg_keyboard_v1', 'json');
    if (saved && Array.isArray(saved.rows) && saved.rows.length) {
      return {
        rows: saved.rows,
        adminRows: Array.isArray(saved.adminRows) ? saved.adminRows : def.adminRows
      };
    }
  } catch (e) {}
  return def;
}

/** نرمال‌سازی اکشن دکمه — reset → /reset ، support → __support__ */
function normalizeKeyboardAction(action, buttonText) {
  var a = String(action != null ? action : '').trim();
  var t = String(buttonText || '').trim();
  if (!a) a = t;
  // اگر فقط نام دستور بدون اسلش است
  var bare = a.replace(/^\//, '').toLowerCase();
  var cmdMap = {
    reset: '/reset', start: '/start', help: '/help', menu: '/menu',
    status: '/status', models: '/models', crypto: '/crypto', admin: '/admin',
    keys: '/keys', users: '/users', stats: '/stats', inbox: '/inbox',
    freekeys: '/freekeys', mode: '/mode', memory: '/memory', usage: '/usage',
    userkeys: '/userkeys', support: '__support__', news: '__news__',
    hidekb: '__hidekb__', hide: '__hidekb__',
    rea: '/rea', reverse: '/rea'
  };
  if (cmdMap[bare]) return cmdMap[bare];
  // از روی متن دکمه
  if (/پاک\s*کردن|reset/i.test(t) && !a) return '/reset';
  if (/پاک\s*کردن|🗑️/.test(t) && bare === 'reset') return '/reset';
  if (/پشتیبانی|support/i.test(t) && bare === 'support') return '__support__';
  if (/اخبار|news/i.test(t) && (bare === 'news' || a === '__news__')) return '__news__';
  return a || t;
}

/** یک‌بار اکشن‌های منوی ذخیره‌شده را نرمال می‌کند (reset→/reset) */
async function ensureKeyboardNormalized(env) {
  if (!env || !env.BOT_KV) return;
  try {
    var flag = await env.BOT_KV.get('tg_kb_norm_v2');
    if (flag === '1') return;
    var saved = await env.BOT_KV.get('tg_keyboard_v1', 'json');
    if (saved && Array.isArray(saved.rows) && saved.rows.length) {
      var res = await saveTgKeyboardConfig(env, saved);
      if (!res || !res.ok) return; // اگر ذخیره نشد پرچم نزن تا دفعه بعد دوباره تلاش شود
    }
    await env.BOT_KV.put('tg_kb_norm_v2', '1', { expirationTtl: 60 * 60 * 24 * 60 });
  } catch (e) {}
}

async function novaHealthReport(env) {
  var lines = ['🏥 سلامت Nova ' + NOVA_VERSION, '────────────'];
  lines.push('• Workers AI: ' + (env.AI ? '✅' : '❌'));
  lines.push('• KV: ' + (env.BOT_KV ? '✅' : '❌'));
  lines.push('• تلگرام: ' + (env.TELEGRAM_BOT_TOKEN ? '✅' : '❌'));
  var vis = [];
  try {
    var provs = await collectKeys(env);
    var names = Object.keys(provs || {});
    lines.push('• کلیدهای سیستم: ' + (names.length ? names.join(', ') : 'هیچ'));
    lines.push('• Gemini: ' + (provs.gemini || provs.google_studio ? '✅' : '❌'));
    lines.push('• OpenRouter: ' + (provs.openrouter ? '✅' : '❌'));
    lines.push('• Groq: ' + (provs.groq ? '✅' : '❌'));
    if (provs.gemini || provs.google_studio) vis.push('Gemini');
    if (provs.openrouter) vis.push('OpenRouter');
    if (provs.groq) vis.push('Groq');
  } catch (e) {
    lines.push('• کلیدها: خطا در خواندن');
  }
  if (env.AI) vis.push('CF');
  lines.push('• Vision: ' + (vis.length ? vis.join('+') : '❌ نیاز به Gemini یا AI binding'));
  lines.push('────────────');
  lines.push('دستورات: /health · /reset · /menu · /models');
  return lines.join('\n');
}

async function saveTgKeyboardConfig(env, cfg) {
  if (!env || !env.BOT_KV) return { ok: false, error: 'KV نیست' };
  var cleanRows = function (rows) {
    if (!Array.isArray(rows)) return [];
    return rows.map(function (row) {
      if (!Array.isArray(row)) return [];
      return row.map(function (b) {
        var text = String((b && b.text) || '').trim().slice(0, 64);
        var action = normalizeKeyboardAction((b && b.action) != null ? b.action : text, text);
        if (!text) return null;
        var en = (b && b.enabled === false) ? false : true;
        return { text: text, action: action || text, enabled: en };
      }).filter(Boolean);
    }).filter(function (r) { return r.length > 0; });
  };
  var out = {
    rows: cleanRows(cfg && cfg.rows),
    adminRows: cleanRows(cfg && cfg.adminRows),
    updated: Date.now()
  };
  if (!out.rows.length) return { ok: false, error: 'حداقل یک ردیف دکمه لازم است' };
  await env.BOT_KV.put('tg_keyboard_v1', JSON.stringify(out));
  return { ok: true, config: out };
}

function tgMainKeyboard(isAdmin, showAdminBtn) {
  // همگام — فقط پیش‌فرض (برای جاهایی که await ممکن نیست)
  var cfg = defaultTgKeyboardConfig();
  var rows = (cfg.rows || []).map(function (row) {
    return row.map(function (b) { return { text: b.text }; });
  });
  if (isAdmin && cfg.adminRows) {
    cfg.adminRows.forEach(function (row) {
      rows.push(row.map(function (b) { return { text: b.text }; }));
    });
  }
  return rows;
}

async function buildTgKeyboard(env, isAdmin) {
  var cfg = await getTgKeyboardConfig(env);
  if (!FEATURES.richKeyboard) {
    return [
      [{ text: '🎯 مدل‌ها' }, { text: '📊 وضعیت' }],
      [{ text: '📰 اخبار' }, { text: '💱 نرخ ارزها' }]
    ];
  }
  function mapEnabled(rows) {
    return (rows || []).map(function (row) {
      return (row || []).filter(function (b) { return b && b.enabled !== false; })
        .map(function (b) { return { text: b.text }; });
    }).filter(function (r) { return r.length > 0; });
  }
  var rows = mapEnabled(cfg.rows);
  if (isAdmin && cfg.adminRows && cfg.adminRows.length) {
    mapEnabled(cfg.adminRows).forEach(function (row) { rows.push(row); });
  }
  return rows;
}

async function resolveKeyboardButton(env, btnText) {
  btnText = String(btnText || '').trim();
  if (!btnText) return null;
  var cfg = await getTgKeyboardConfig(env);
  var all = (cfg.rows || []).concat(cfg.adminRows || []);
  for (var i = 0; i < all.length; i++) {
    var row = all[i] || [];
    for (var j = 0; j < row.length; j++) {
      var b = row[j];
      if (b && String(b.text).trim() === btnText) {
        if (b.enabled === false) return null;
        return normalizeKeyboardAction(b.action != null ? b.action : b.text, b.text);
      }
    }
  }
  return null;
}


