function admFmtDate(ts) {
  if (!ts) return '-';
  try { return new Date(ts).toLocaleString('fa-IR', { timeZone: 'Asia/Tehran', dateStyle: 'short', timeStyle: 'short' }); }
  catch (e) { return '-'; }
}
async function admUsers(env) {
  if (!env.BOT_KV) return [];
  var u = (await env.BOT_KV.get('users_meta', 'json')) || [];
  if (!Array.isArray(u)) u = [];
  // ادغام درخواست‌های ثبت‌نام وب در انتظار تأیید
  try {
    var rlist = (await env.BOT_KV.get('web_reg_list', 'json')) || [];
    if (Array.isArray(rlist)) {
      for (var i = 0; i < rlist.length; i++) {
        var reg = await getPendingReg(env, rlist[i]);
        if (!reg || reg.status !== 'pending') continue;
        var uid = webUserId(reg.username);
        var exists = u.some(function (x) { return x.id === uid || x.regId === reg.id; });
        if (exists) {
          u.forEach(function (x) {
            if (x.id === uid || x.regId === reg.id) {
              x.pending = true;
              x.status = 'pending';
              x.regId = reg.id;
              x.source = 'web';
              x.name = x.name || reg.displayName || reg.username;
            }
          });
        } else {
          u.unshift({
            id: uid,
            name: (reg.displayName || reg.username || 'کاربر') + ' (در انتظار)',
            role: 'public',
            source: 'web',
            pending: true,
            status: 'pending',
            regId: reg.id,
            first: reg.created || Date.now(),
            last: reg.created || Date.now(),
            msgs: 0
          });
        }
      }
    }
  } catch (ePend) {}
  return u;
}
async function admGetState(env, uid) {
  if (!env.BOT_KV) return null;
  try { return await env.BOT_KV.get('tg_state_' + uid, 'json'); } catch (e) { return null; }
}
async function admSetState(env, uid, st) {
  if (!env.BOT_KV) return;
  try {
    if (st) await env.BOT_KV.put('tg_state_' + uid, JSON.stringify(st), { expirationTtl: 900 });
    else await env.BOT_KV.delete('tg_state_' + uid);
  } catch (e) {}
}
/** پیام را ویرایش می‌کند؛ اگر نشد پیام جدید می‌فرستد */
async function admSend(env, chatId, msgId, text, markup) {
  text = String(text).slice(0, 3900);
  var payload = { chat_id: chatId, text: text };
  if (markup) payload.reply_markup = { inline_keyboard: markup };
  if (msgId) {
    var r = await tg(env, 'editMessageText', Object.assign({ message_id: msgId }, payload));
    if (r && r.ok) return;
    if (r && /not modified/i.test(String(r.description || ''))) return;
  }
  await tg(env, 'sendMessage', payload);
}

