async function admShowKeys(env, chatId, msgId) {
  var ck = env.BOT_KV ? ((await env.BOT_KV.get('custom_keys', 'json')) || []) : [];
  var lines = ['🔑 مدیریت کلیدها\n'];
  var kb = [];

  if (ck.length) {
    lines.push('🗂 کلیدهای ثبت‌شده از پنل (' + ck.length + '):\n');
    ck.slice(0, 20).forEach(function (k, i) {
      var nm = k.name || (PROVIDERS[k.provider] && PROVIDERS[k.provider].name) || k.provider || 'Custom';
      var site = k.base || k.site || '';
      lines.push((i + 1) + '. ' + nm + ' — ' + maskKey(k.key));
      if (site) lines.push('   🌐 ' + String(site).slice(0, 60));
      if (k.models && k.models.length) lines.push('   🤖 ' + k.models.length + ' مدل');
      kb.push([{ text: '🗑 حذف #' + (i + 1) + ' ' + String(nm).slice(0, 22), callback_data: 'adm:kdel:' + i }]);
    });
  } else {
    lines.push('هنوز کلیدی از پنل ثبت نشده.\nبا «➕ افزودن کلید» اول آدرس سایت بعد کلید را بفرست.\n');
  }

  // خلاصه کوتاه اتصال (بدون جایگزین کردن پنل مدیریت)
  try {
    var ks = await checkKeysStatus(env);
    var okN = 0, badN = 0;
    ks.forEach(function (x) { if (x.connected) okN++; else badN++; });
    lines.push('\n📡 اتصال: ✅ ' + okN + ' · ❌ ' + badN + '  (جزئیات: /keystatus)');
  } catch (eKs) {}

  kb.push([{ text: '➕ افزودن کلید', callback_data: 'adm:addkey' }, { text: '🔄 تازه‌سازی', callback_data: 'adm:keys' }]);
  kb.push([{ text: '📊 وضعیت اتصال', callback_data: 'adm:keystatus' }, { text: '🔙 منو', callback_data: 'adm:menu' }]);
  await admSend(env, chatId, msgId, lines.join('\n'), kb);
}

/** ارسال همگانی — دسته‌ای (۲۰ تایی در ثانیه) تا از سقف تلگرام رد نشویم */
async function admDoBroadcast(env, adminChatId, text) {
  var users = await admUsers(env);
  var targets = users.filter(function (u) { return u.source === 'telegram' && !u.banned; })
    .map(function (u) { return String(u.id).replace('tg_', ''); });
  var sent = 0, fail = 0;
  for (var i = 0; i < targets.length; i += 20) {
    var batch = targets.slice(i, i + 20);
    var res = await Promise.all(batch.map(function (cid) {
      return tg(env, 'sendMessage', { chat_id: cid, text: text })
        .then(function (r) { return r && r.ok; }).catch(function () { return false; });
    }));
    res.forEach(function (ok) { if (ok) sent++; else fail++; });
    if (i + 20 < targets.length) await new Promise(function (r) { setTimeout(r, 1000); });
  }
  await tg(env, 'sendMessage', {
    chat_id: adminChatId,
    text: '📢 ارسال همگانی تمام شد.\n✅ موفق: ' + sent + '\n❌ ناموفق: ' + fail,
    reply_markup: { inline_keyboard: [[{ text: '🏠 منو', callback_data: 'adm:menu' }]] }
  });
}

async function admDeleteUser(env, id) {
  var users = (await admUsers(env)).filter(function (u) { return u.id !== id; });
  await env.BOT_KV.put('users_meta', JSON.stringify(users));
  await env.BOT_KV.delete('hist_' + id);
  await env.BOT_KV.delete('tg_model_' + id);
  await env.BOT_KV.delete('mem_' + id);
}

async function tgAdminCallback(env, ctx, cq) {
  var fromId = cq.from && cq.from.id;
  var chatId = cq.message.chat.id, msgId = cq.message.message_id;
  if (!(await isTgAdmin(env, fromId))) {
    await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: '⛔ دسترسی ندارید', show_alert: true });
    return;
  }
  await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id });
  if (!env.BOT_KV) { await admSend(env, chatId, msgId, '⚠️ KV تنظیم نشده؛ مدیریت کار نمی‌کند.', null); return; }

  var p = String(cq.data || '').split(':');
  var act = p[1];
  var adminUid = 'tg_' + chatId;

  if (act === 'noop') return;
  if (act === 'menu') { await admSetState(env, adminUid, null); return admShowMenu(env, chatId, msgId); }
  if (act === 'stats') return admShowStats(env, chatId, msgId);
  if (act === 'users') return admShowUsers(env, chatId, msgId, p[2] || 'a', parseInt(p[3] || '0', 10));
  if (act === 'u') return admShowUser(env, chatId, msgId, p[2]);
  if (act === 'approve') {
    var apR = await webApproveRegistration(env, p[2], chatId);
    await tg(env, 'sendMessage', { chat_id: chatId, text: apR.ok ? ('✅ ' + apR.message) : ('⛔ ' + (apR.error || 'خطا')) });
    return admShowUsers(env, chatId, msgId, 'p', 0);
  }
  if (act === 'reject') {
    var rjR = await webRejectRegistration(env, p[2]);
    await tg(env, 'sendMessage', { chat_id: chatId, text: rjR.ok ? ('❌ ' + rjR.message) : ('⛔ ' + (rjR.error || 'خطا')) });
    return admShowUsers(env, chatId, msgId, 'p', 0);
  }
  if (act === 'docs') { await admSetState(env, adminUid, null); return admShowDocs(env, chatId, msgId); }
  if (act === 'keys') return admShowKeys(env, chatId, msgId);
  if (act === 'keystatus') {
    var ks2 = await checkKeysStatus(env);
    var lines2 = ['🔑 وضعیت اتصال کلیدها:\n'];
    ks2.forEach(function (x) {
      lines2.push((x.connected ? '✅ ' : '❌ ') + x.name + ' — ' + (x.detail || '') + (x.keys ? ' (' + x.keys + ' کلید)' : ''));
    });
    lines2.push('\nبرای مدیریت: دکمه «کلیدها» یا /keys');
    return admSend(env, chatId, msgId, lines2.join('\n'), [
      [{ text: '🔑 مدیریت کلیدها', callback_data: 'adm:keys' }, { text: '🔙 منو', callback_data: 'adm:menu' }]
    ]);
  }

  if (act === 'debug') {
    await tg(env, 'sendMessage', { chat_id: chatId, text: 'برای عیب‌یابی دستور /debug را بفرست.' });
    return;
  }

  if (act === 'ban') {
    var id = p[2], val = p[3] === '1';
    var users = await admUsers(env);
    users.forEach(function (u) { if (u.id === id) u.banned = val; });
    await env.BOT_KV.put('users_meta', JSON.stringify(users));
    return admShowUser(env, chatId, msgId, id);
  }
  if (act === 'hist') {
    try {
      var hh = await getHistory(env, p[2]);
      if (hh && hh.length) await archiveChatSession(env, p[2], hh);
    } catch (eH) {}
    await env.BOT_KV.delete('hist_' + p[2]);
    await tg(env, 'sendMessage', { chat_id: chatId, text: '🧹 تاریخچه پاک شد و در آرشیو ذخیره شد.' });
    return;
  }
  if (act === 'del') {
    return admSend(env, chatId, msgId, '⚠️ مطمئنی کاربر ' + p[2] + ' حذف شود؟ (تاریخچه و تنظیماتش هم پاک می‌شود)',
      [[{ text: '✅ بله، حذف کن', callback_data: 'adm:delok:' + p[2] }, { text: '❌ نه', callback_data: 'adm:u:' + p[2] }]]);
  }
  if (act === 'delok') {
    await admDeleteUser(env, p[2]);
    return admShowUsers(env, chatId, msgId, 'a', 0);
  }
  if (act === 'dm') {
    await admSetState(env, adminUid, { t: 'dm', to: p[2] });
    return admSend(env, chatId, msgId, '✉️ متن پیامی که می‌خواهی برای این کاربر بفرستم را بنویس.\n(لغو: /cancel)', [[{ text: '❌ لغو', callback_data: 'adm:u:' + p[2] }]]);
  }
  if (act === 'bc') {
    await admSetState(env, adminUid, { t: 'bc' });
    return admSend(env, chatId, msgId, '📢 متن پیام همگانی را بنویس و بفرست.\nبه همه‌ی کاربران تلگرام (غیرمسدود) ارسال می‌شود.\n(لغو: /cancel)', [[{ text: '❌ لغو', callback_data: 'adm:menu' }]]);
  }
  if (act === 'bcyes') {
    var st = await admGetState(env, adminUid);
    if (!st || st.t !== 'bcc' || !st.text) { return admSend(env, chatId, msgId, '⌛ منقضی شد. دوباره از «ارسال همگانی» شروع کن.', [[{ text: '🏠 منو', callback_data: 'adm:menu' }]]); }
    await admSetState(env, adminUid, null);
    await admSend(env, chatId, msgId, '⏳ در حال ارسال… (پایان که رسید خبر می‌دهم)', null);
    ctx.waitUntil(admDoBroadcast(env, chatId, st.text));
    return;
  }
  if (act === 'docdel') {
    await ragDelete(env, p[2]);
    return admShowDocs(env, chatId, msgId);
  }
  if (act === 'docget') {
    var gId = p[2];
    var gDoc = await ragGetText(env, gId);
    if (!gDoc) {
      await tg(env, 'sendMessage', { chat_id: chatId, text: '❓ سند پیدا نشد.' });
      return admShowDocs(env, chatId, msgId);
    }
    var gName = String(gDoc.name || 'doc').replace(/[^\w\u0600-\u06FF.\-]+/g, '_').slice(0, 60) || 'doc';
    if (!/\.\w{1,8}$/.test(gName)) gName += '.txt';
    try {
      var fd = new FormData();
      fd.append('chat_id', String(chatId));
      fd.append('document', new Blob([gDoc.text], { type: 'text/plain; charset=utf-8' }), gName);
      fd.append('caption', '⬇️ ' + (gDoc.name || gId) + ' (' + (gDoc.chunks || 0) + ' بخش · از RAG)');
      var gr = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendDocument', { method: 'POST', body: fd });
      var gj = await gr.json().catch(function () { return {}; });
      if (!gj || !gj.ok) {
        var t = gDoc.text.slice(0, 3500);
        await tg(env, 'sendMessage', {
          chat_id: chatId,
          text: '📄 ' + (gDoc.name || '') + '\n\n' + t + (gDoc.text.length > 3500 ? '\n\n… (ادامه بریده شد)' : '')
        });
      }
    } catch (eGet) {
      await tg(env, 'sendMessage', { chat_id: chatId, text: '❌ دانلود ناموفق: ' + (eGet.message || '') });
    }
    return;
  }
  if (act === 'docview') {
    var vId = p[2];
    var vDoc = await ragGetText(env, vId);
    if (!vDoc) {
      await tg(env, 'sendMessage', { chat_id: chatId, text: '❓ سند پیدا نشد.' });
      return;
    }
    var preview = vDoc.text.slice(0, 3200);
    var more = vDoc.text.length > 3200 ? '\n\n… (برای فایل کامل ⬇️ دانلود بزن)' : '';
    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: '👁 «' + (vDoc.name || vId) + '»\n' + (vDoc.chunks || 0) + ' بخش · ' + vDoc.text.length + ' کاراکتر\n\n' + preview + more,
      reply_markup: {
        inline_keyboard: [[
          { text: '⬇️ دانلود', callback_data: 'adm:docget:' + vId },
          { text: '✏️ ویرایش', callback_data: 'adm:docedit:' + vId },
          { text: '🗑 حذف', callback_data: 'adm:docdel:' + vId }
        ], [{ text: '📚 لیست اسناد', callback_data: 'adm:docs' }]]
      }
    });
    return;
  }
  if (act === 'docedit') {
    var eId = p[2];
    var eDoc = await ragGetText(env, eId);
    if (!eDoc) {
      await tg(env, 'sendMessage', { chat_id: chatId, text: '❓ سند پیدا نشد.' });
      return;
    }
    await admSetState(env, adminUid, { t: 'docedit', id: eId, name: eDoc.name || eId });
    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: '✏️ ویرایش «' + (eDoc.name || eId) + '»\n\nمتن کامل جدید را در یک پیام بفرست.\nحداقل ۳۰ کاراکتر.\nانصراف: /cancel',
      reply_markup: { inline_keyboard: [[{ text: '❌ انصراف', callback_data: 'adm:docs' }]] }
    });
    return;
  }
  if (act === 'kdel') {
    var i = parseInt(p[2], 10);
    var ck = (await env.BOT_KV.get('custom_keys', 'json')) || [];
    if (i >= 0 && i < ck.length) {
      ck.splice(i, 1);
      await env.BOT_KV.put('custom_keys', JSON.stringify(ck));
      await env.BOT_KV.delete('models_v27'); await env.BOT_KV.delete('cache:wm_v1');
    }
    return admShowKeys(env, chatId, msgId);
  }
  if (act === 'addkey') {
    await admSetState(env, adminUid, { t: 'addkey_site' });
    return admSend(env, chatId, msgId,
      '➕ افزودن کلید — مرحله ۱ از ۲\n\n' +
      '🌐 اول آدرس سایت / API را بفرست:\n' +
      'مثال‌ها:\n' +
      '• https://openrouter.ai/api/v1\n' +
      '• https://api.groq.com/openai/v1\n' +
      '• https://api.example.com/v1\n' +
      '• api.example.com\n\n' +
      'اگر سرویس معروف است (Gemini/Groq/OpenRouter) می‌توانی مستقیم کلید را بفرستی.\n\n' +
      'یا یک‌جا:\nhttps://api.xxx.com/v1 sk-your-key\n\n' +
      '🔒 پیام بعد از ثبت پاک می‌شود.\nلغو: /cancel',
      [[{ text: '❌ لغو', callback_data: 'adm:keys' }]]);
  }
}

/** ورودی متنی ادمین وقتی در حالت (state) است. true = پیام مصرف شد */
async function tgAdminHandleState(env, msg, chatId, uid, st) {
  var text = String(msg.text || '').trim();
  if (st.t === 'bc') {
    if (!text) return true;
    await admSetState(env, uid, { t: 'bcc', text: text });
    var users = await admUsers(env);
    var n = users.filter(function (u) { return u.source === 'telegram' && !u.banned; }).length;
    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: '📢 پیش‌نمایش:\n\n' + text + '\n\n— برای ' + n + ' کاربر تلگرام ارسال می‌شود. تأیید؟',
      reply_markup: { inline_keyboard: [[{ text: '✅ ارسال', callback_data: 'adm:bcyes' }, { text: '❌ لغو', callback_data: 'adm:menu' }]] }
    });
    return true;
  }
  if (st.t === 'dm') {
    await admSetState(env, uid, null);
    var to = String(st.to || '').replace('tg_', '');
    var r = await tg(env, 'sendMessage', { chat_id: to, text: '📩 پیام از مدیر:\n\n' + text });
    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: (r && r.ok) ? '✅ پیام ارسال شد.' : ('❌ ارسال نشد: ' + ((r && r.description) || 'نامشخص')),
      reply_markup: { inline_keyboard: [[{ text: '🔙 کاربر', callback_data: 'adm:u:' + st.to }]] }
    });
    return true;
  }
  if (st.t === 'addkey' || st.t === 'addkey_site' || st.t === 'addkey_key') {
    try { await tg(env, 'deleteMessage', { chat_id: chatId, message_id: msg.message_id }); } catch (e) {}

    // یک‌جا: URL + KEY در یک پیام
    var oneShotBase = extractApiBaseFromText(text);
    var oneShotKey = extractApiKeyFromText(text);
    var hasUrl = !!oneShotBase && !!oneShotBase.base;
    var hasKey = !!(oneShotKey && oneShotKey.length >= 8);
    // اگر فقط کلید معروف است (بدون URL)
    var knownFromKey = false;
    if (hasKey && !hasUrl) {
      Object.keys(PROVIDERS).forEach(function (id) {
        if (PROVIDERS[id].test(oneShotKey)) knownFromKey = true;
      });
    }

    if (st.t === 'addkey_key') {
      // مرحله ۲: منتظر کلید هستیم
      var keyOnly = extractApiKeyFromText(text);
      if (!keyOnly || keyOnly.length < 8) {
        await tg(env, 'sendMessage', {
          chat_id: chatId,
          text: '❌ کلید معتبر نیست. کلید API را بفرست (حداقل ۸ کاراکتر).\nلغو: /cancel',
          reply_markup: { inline_keyboard: [[{ text: '❌ لغو', callback_data: 'adm:keys' }]] }
        });
        return true;
      }
      await admSetState(env, uid, null);
      var fin = await finalizeCustomKeyAdd(env, keyOnly, st.site || st.base || '', st.provider || '');
      await tg(env, 'sendMessage', {
        chat_id: chatId,
        text: fin.ok ? formatKeyAddSuccess(fin) : ('❌ ' + (fin.error || 'ثبت نشد')),
        reply_markup: { inline_keyboard: [[{ text: '🔑 کلیدها', callback_data: 'adm:keys' }, { text: '➕ یکی دیگر', callback_data: 'adm:addkey' }]] }
      });
      return true;
    }

    // addkey / addkey_site
    if (hasUrl && hasKey) {
      await admSetState(env, uid, null);
      var fin2 = await finalizeCustomKeyAdd(env, oneShotKey, oneShotBase.base, oneShotBase.provider);
      await tg(env, 'sendMessage', {
        chat_id: chatId,
        text: fin2.ok ? formatKeyAddSuccess(fin2) : ('❌ ' + (fin2.error || 'ثبت نشد')),
        reply_markup: { inline_keyboard: [[{ text: '🔑 کلیدها', callback_data: 'adm:keys' }, { text: '➕ یکی دیگر', callback_data: 'adm:addkey' }]] }
      });
      return true;
    }

    if (hasKey && knownFromKey) {
      await admSetState(env, uid, null);
      var fin3 = await finalizeCustomKeyAdd(env, oneShotKey, '', '');
      await tg(env, 'sendMessage', {
        chat_id: chatId,
        text: fin3.ok ? formatKeyAddSuccess(fin3) : ('❌ ' + (fin3.error || 'ثبت نشد')),
        reply_markup: { inline_keyboard: [[{ text: '🔑 کلیدها', callback_data: 'adm:keys' }, { text: '➕ یکی دیگر', callback_data: 'adm:addkey' }]] }
      });
      return true;
    }

    if (hasUrl) {
      await admSetState(env, uid, {
        t: 'addkey_key',
        site: oneShotBase.base,
        base: oneShotBase.base,
        provider: oneShotBase.provider || ''
      });
      await tg(env, 'sendMessage', {
        chat_id: chatId,
        text: '➕ افزودن کلید — مرحله ۲ از ۲\n\n' +
          '🌐 سایت: ' + oneShotBase.base + '\n' +
          '🏷 سرویس: ' + (oneShotBase.provider || 'Custom') + '\n\n' +
          '🔑 حالا کلید API این سایت را بفرست.\n\nلغو: /cancel',
        reply_markup: { inline_keyboard: [[{ text: '❌ لغو', callback_data: 'adm:keys' }]] }
      });
      return true;
    }

    // شاید چند کلید با پیشوند / نام provider
    var tokens = text.split(/[\s,;]+/).filter(Boolean);
    var forced = null;
    var pairs = [];
    tokens.forEach(function (tok) {
      if (PROVIDERS[tok.toLowerCase()]) { forced = tok.toLowerCase(); return; }
      pairs.push({ k: tok, p: forced });
      forced = null;
    });
    if (pairs.length && pairs.every(function (pr) {
      var pid = pr.p;
      if (!pid) Object.keys(PROVIDERS).forEach(function (id) { if (!pid && PROVIDERS[id].test(pr.k)) pid = id; });
      return !!pid;
    })) {
      await admSetState(env, uid, null);
      var linesOut = [];
      for (var pi = 0; pi < pairs.length; pi++) {
        var pr = pairs[pi];
        var pid2 = pr.p;
        if (!pid2) Object.keys(PROVIDERS).forEach(function (id) { if (!pid2 && PROVIDERS[id].test(pr.k)) pid2 = id; });
        var finP = await finalizeCustomKeyAdd(env, pr.k, (PROVIDERS[pid2] && PROVIDERS[pid2].base) || '', (PROVIDERS[pid2] && PROVIDERS[pid2].name) || pid2);
        linesOut.push(finP.ok ? ('✅ ' + finP.provider + ' ' + finP.keyPreview) : ('❌ ' + maskKey(pr.k) + ': ' + (finP.error || '')));
      }
      await tg(env, 'sendMessage', {
        chat_id: chatId,
        text: linesOut.join('\n'),
        reply_markup: { inline_keyboard: [[{ text: '🔑 کلیدها', callback_data: 'adm:keys' }]] }
      });
      return true;
    }

    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: '🌐 آدرس سایت را نفهمیدم.\n\nمثال:\nhttps://api.example.com/v1\n\nیا یک‌جا:\nhttps://api.example.com/v1 sk-xxxx\n\nلغو: /cancel',
      reply_markup: { inline_keyboard: [[{ text: '❌ لغو', callback_data: 'adm:keys' }]] }
    });
    return true;
  }
  if (st.t === 'docedit') {
    if (!text || text.length < 30) {
      await tg(env, 'sendMessage', {
        chat_id: chatId,
        text: '⚠️ متن خیلی کوتاه است (حداقل ۳۰ کاراکتر). دوباره بفرست یا /cancel'
      });
      return true;
    }
    var oldId = st.id;
    var oldName = st.name || 'سند';
    await admSetState(env, uid, null);
    if (!env.AI) {
      await tg(env, 'sendMessage', { chat_id: chatId, text: '❌ Workers AI برای embedding لازم است.' });
      return true;
    }
    var rep = await ragReplace(env, oldId, oldName, text.slice(0, 400000));
    if (!rep.ok) {
      await tg(env, 'sendMessage', { chat_id: chatId, text: '❌ ویرایش ناموفق: ' + (rep.reason || '') });
      return true;
    }
    await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: '✏️ «' + oldName + '» به‌روز شد (' + rep.chunks + ' بخش).',
      reply_markup: { inline_keyboard: [[{ text: '📚 اسناد', callback_data: 'adm:docs' }, { text: '🏠 منو', callback_data: 'adm:menu' }]] }
    });
    return true;
  }
  return false;
}

/** بررسی رمز و ثبت ادمین. رمز = LOGIN_PASS (همان رمز ورود پنل وب) */
async function tgAdminTryPass(env, msg, chatId, fromId, pass) {
  try { await tg(env, 'deleteMessage', { chat_id: chatId, message_id: msg.message_id }); } catch (e) {}
  if (!env.LOGIN_PASS || !env.BOT_KV) {
    await tgReply(env, chatId, '⚠️ LOGIN_PASS یا KV روی ورکر تنظیم نشده. متغیر TG_ADMIN_IDS را برابر ' + fromId + ' بگذار.');
    return;
  }
  var fk = 'tg_admfail_' + fromId, fails = 0;
  try { fails = parseInt((await env.BOT_KV.get(fk)) || '0', 10) || 0; } catch (e) {}
  if (fails >= 5) { await tgReply(env, chatId, '⛔ تلاش‌های اشتباه زیاد بود. یک ساعت بعد امتحان کن.'); return; }
  if (pass === env.LOGIN_PASS) {
    var list = (await env.BOT_KV.get('tg_admins', 'json')) || [];
    if (list.indexOf(fromId) === -1) list.push(fromId);
    await env.BOT_KV.put('tg_admins', JSON.stringify(list));
    await tgReply(env, chatId, '✅ تو حالا ادمین هستی. کیبورد به‌روز شد.',
      { reply_markup: tgKeyboardMarkup(await buildTgKeyboard(env, true)) });
    queueHideKeyboard(env, chatId, 10);
    await setAdminCommands(env, chatId);
    await admShowMenu(env, chatId, null);
    return;
  }
  try { await env.BOT_KV.put(fk, String(fails + 1), { expirationTtl: 3600 }); } catch (e) {}
  await tgReply(env, chatId, '⛔ رمز اشتباه است. (' + (fails + 1) + '/5)\nدوباره «⚙️ مدیریت» را بزن.');
}

/** /admin */
async function tgAdminEntry(env, msg, chatId) {
  var fromId = String((msg.from && msg.from.id) || chatId);
  if (await isTgAdmin(env, fromId)) {
    await setAdminCommands(env, chatId);
    await admShowMenu(env, chatId, null);
    return;
  }
  // اگر هنوز هیچ ادمینی ثبت نشده، فقط همان‌وقت اجازه ورود با رمز
  var hasAdmin = await tgHasAnyAdmin(env);
  if (!hasAdmin && env.LOGIN_PASS && env.BOT_KV) {
    var parts = String(msg.text || '').trim().split(/\s+/);
    if (parts[1]) { await tgAdminTryPass(env, msg, chatId, fromId, parts.slice(1).join(' ')); return; }
    await admSetState(env, 'tg_' + chatId, { t: 'admpass' });
    await tgReply(env, chatId,
      '🔐 راه‌اندازی ادمین (اولین بار)\n\n' +
      'رمز LOGIN_PASS را بفرست.\n(لغو: /cancel)'
    );
    return;
  }
  // کاربران عادی — هیچ راهنمای ادمین نشان داده نشود
  await tgReply(env, chatId, '⛔ این بخش در دسترس نیست.');
}

async function tgWebhook(request, env, ctx) {
  var up;
  try { up = await request.json(); } catch (e) {
    return new Response('ok');
  }

  if (up.callback_query) {
    var cq = up.callback_query;
    var data = cq.data || '';
    var cbChatId = cq.message.chat.id;
    var cbUid = 'tg_' + cbChatId;

    /* ===== تأیید / رد ثبت‌نام وب ===== */
    if ((data || '').indexOf('wreg_ok_') === 0 || (data || '').indexOf('wreg_no_') === 0) {
      try {
        var fromCb = cq.from && cq.from.id;
        if (!(await isTgAdmin(env, fromCb)) && !(await isTgAdmin(env, cbChatId))) {
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'فقط ادمین', show_alert: true });
          return;
        }
        var rid = data.replace(/^wreg_(ok|no)_/, '');
        if (data.indexOf('wreg_ok_') === 0) {
          var ap = await webApproveRegistration(env, rid, fromCb);
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: ap.ok ? 'فعال شد' : (ap.error || 'خطا'), show_alert: !ap.ok });
          try {
            await tg(env, 'editMessageText', {
              chat_id: cbChatId,
              message_id: cq.message.message_id,
              text: (cq.message.text || '') + '\n\n' + (ap.ok ? '✅ تأیید شد توسط ادمین — کاربر فعال است.' : ('⚠️ ' + (ap.error || 'خطا')))
            });
          } catch (eEd) {}
        } else {
          var rj = await webRejectRegistration(env, rid);
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: rj.ok ? 'رد شد' : (rj.error || 'خطا'), show_alert: !rj.ok });
          try {
            await tg(env, 'editMessageText', {
              chat_id: cbChatId,
              message_id: cq.message.message_id,
              text: (cq.message.text || '') + '\n\n❌ رد شد توسط ادمین.'
            });
          } catch (eEd2) {}
        }
      } catch (eWreg) {
        try { await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'خطا', show_alert: true }); } catch (e3) {}
      }
      return;
    }

    /* ===== Tools: دکمه «نمایش پاسخ‌ها» برای کوییز ===== */
    if ((data || '').indexOf('qzans:') === 0) {
      try {
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'پاسخ‌ها' });
        await tgReply(env, cbChatId, await novaToolQuizAnswers(env, data.slice(6)));
      } catch (eQa) {}
      return new Response('ok');
    }

    /* ===== UX: mode / more / short / feedback ===== */
    if ((data || '').indexOf('ux:') === 0) {
      var uxParts = String(data).split(':');
      var uxAct = uxParts[1] || '';
      var cbName = (cq.from && (cq.from.first_name || cq.from.username)) || 'کاربر';
      try {
        if (uxAct === 'mode' && uxParts[2]) {
          await saveUserMode(env, cbUid, uxParts[2]);
          var md = NOVA_CHAT_MODES[uxParts[2]] || NOVA_CHAT_MODES.general;
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'حالت: ' + md.fa });
          await tgReply(env, cbChatId, '🎭 حالت «' + md.fa + '» فعال شد.\n' + md.sysFa);
          return new Response('ok');
        }
        if (uxAct === 'more') {
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'ادامه…' });
          await tgProcessText(env, cbUid, cbChatId, 'ادامه بده و کامل‌تر توضیح بده', cbName);
          return new Response('ok');
        }
        if (uxAct === 'short') {
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'کوتاه…' });
          await tgProcessText(env, cbUid, cbChatId, 'همان جواب را خیلی کوتاه‌تر و در چند خط بگو', cbName);
          return new Response('ok');
        }
        if (uxAct === 'up' || uxAct === 'down') {
          var fid = uxParts[2] || '';
          await recordAnswerFeedback(env, fid, uxAct === 'up');
          await tg(env, 'answerCallbackQuery', {
            callback_query_id: cq.id,
            text: uxAct === 'up' ? 'ممنون از بازخورد 👍' : 'ثبت شد — سعی می‌کنیم بهتر شویم 👎'
          });
          return new Response('ok');
        }
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'OK' });
      } catch (eUx) {
        try { await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'خطا', show_alert: true }); } catch (e2) {}
      }
      return new Response('ok');
    }

    /* ===== Tools: پیشنهاد سوال (دکمه) ===== */
    if ((data || '').indexOf('sug:') === 0) {
      var sugId = String(data).slice(4);
      try { await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'در حال ارسال سوال...' }); } catch (eSq2) {}
      try {
        var sp = await advKvGet(env, 'sug_' + sugId + '_' + cbUid);
        if (sp) { var so = JSON.parse(sp); if (so && so.text) { await tgProcessText(env, cbUid, cbChatId, so.text, (cq.from && (cq.from.first_name || cq.from.username)) || 'کاربر'); } }
      } catch (eSp2) {}
      return new Response('ok');
    }

    if (data.indexOf('adm:') === 0) {
      try { await tgAdminCallback(env, ctx, cq); }
      catch (e) {
        console.log('[adm] callback error', e && e.message);
        try { await tg(env, 'sendMessage', { chat_id: cbChatId, text: '❌ خطا در پنل: ' + String((e && e.message) || e).slice(0, 200) }); } catch (e2) {}
      }
      return new Response('ok');
    }

    // TTS — بخوان
    if (data.indexOf('tts:play:') === 0) {
      var ttsKey = data.replace('tts:play:', '');
      try {
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'در حال ساخت صدا…' });
        var ttsText = env.BOT_KV ? await env.BOT_KV.get('tts:' + ttsKey) : null;
        if (!ttsText) {
          await tgReply(env, cbChatId, '⏱ متن صوتی منقضی شد؛ دوباره بپرس.');
          return new Response('ok');
        }
        var okV = await tgSendVoice(env, cbChatId, ttsText);
        if (okV) await metricsInc(env, 'stt', 1);
        // پیام خطا داخل tgSendVoice ارسال می‌شود
      } catch (e) {
        try { await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'خطا', show_alert: true }); } catch (e2) {}
      }
      return new Response('ok');
    }

    // ترجمه سریع متن ذخیره‌شده
    if (data.indexOf('tr:auto:') === 0) {
      var trKey = data.replace('tr:auto:', '');
      try {
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'ترجمه…' });
        var src = env.BOT_KV ? await env.BOT_KV.get('tts:' + trKey) : null;
        if (!src) {
          await tgReply(env, cbChatId, '⏱ متن منقضی شد.');
          return new Response('ok');
        }
        var isFa = /[\u0600-\u06FF]/.test(src);
        var trPrompt = isFa
          ? 'Translate the following Persian text to natural English. Only output the translation:\n\n' + src.slice(0, 2000)
          : 'متن زیر را به فارسی روان ترجمه کن. فقط ترجمه را بنویس:\n\n' + src.slice(0, 2000);
        var trR = await think(env, [{ role: 'user', content: trPrompt }], { maxTokens: 1200 });
        await tgReply(env, cbChatId, trR && trR.text ? ('🌐 ترجمه:\n\n' + trR.text) : '❌ ترجمه ناموفق');
      } catch (e) {
        try { await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'خطا', show_alert: true }); } catch (e2) {}
      }
      return new Response('ok');
    }

    // منوی پله‌ای اخبار — انتخاب دسته
    if (data.indexOf('news:cat:') === 0 || data === 'news:refresh') {
      try {
        var cat = data === 'news:refresh' ? 'refresh' : data.replace('news:cat:', '');
        await tg(env, 'answerCallbackQuery', {
          callback_query_id: cq.id,
          text: cat === 'refresh' ? 'تازه‌سازی…' : (cat === 'all' ? 'همه اخبار…' : ('اخبار ' + cat + '…'))
        });
        var q =
          cat === 'refresh' ? '/news_refresh' :
          cat === 'all' ? 'اخبار ۲۴ ساعت اخیر' :
          ('اخبار ' + cat);
        // پردازش همان مسیر چت
        var cbName = (cq.from && (cq.from.first_name || cq.from.username)) || 'کاربر';
        await tg(env, 'sendChatAction', { chat_id: cbChatId, action: 'typing' });
        await tgProcessText(env, cbUid, cbChatId, q, cbName);
      } catch (e) {
        try {
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'خطا', show_alert: true });
        } catch (e2) {}
      }
      return new Response('ok');
    }

    // ادامه اخبار بخش‌بخش
    if (data.indexOf('news:more:') === 0) {
      var moreId = data.replace('news:more:', '');
      try {
        var pack = env.BOT_KV ? await env.BOT_KV.get('news_more:' + moreId, 'json') : null;
        if (!pack || !pack.chunks || !pack.chunks.length) {
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'منقضی شده؛ دوباره اخبار را بگیر', show_alert: true });
          return new Response('ok');
        }
        var idx = pack.i || 0;
        var piece = pack.chunks[idx];
        var left = pack.chunks.length - idx - 1;
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'بخش بعد…' });
        if (left > 0) {
          pack.i = idx + 1;
          await env.BOT_KV.put('news_more:' + moreId, JSON.stringify(pack), { expirationTtl: 3600 });
          await tg(env, 'sendMessage', {
            chat_id: cbChatId,
            text: piece,
            disable_web_page_preview: true,
            reply_markup: {
              inline_keyboard: [[{ text: '▶️ ادامه (' + left + ' بخش دیگر)', callback_data: 'news:more:' + moreId }]]
            }
          });
        } else {
          try { await env.BOT_KV.delete('news_more:' + moreId); } catch (e) {}
          await tg(env, 'sendMessage', {
            chat_id: cbChatId,
            text: piece + '\n\n✅ پایان اخبار.',
            disable_web_page_preview: true
          });
        }
      } catch (e) {
        try { await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'خطا', show_alert: true }); } catch (e2) {}
      }
      return new Response('ok');
    }

    // ادامه نرخ ارز — صفحه بعد (⬇️)
    if (data.indexOf('fx:more:') === 0) {
      var fxId = data.replace('fx:more:', '');
      try {
        var fxPack = env.BOT_KV ? await env.BOT_KV.get('fx_more:' + fxId, 'json') : null;
        if (!fxPack || !fxPack.pages || !fxPack.pages.length) {
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'منقضی شده؛ دوباره «نرخ ارزها» را بزن', show_alert: true });
          return new Response('ok');
        }
        var fxIdx = fxPack.i || 1;
        if (fxIdx >= fxPack.pages.length) {
          await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'پایان لیست' });
          return new Response('ok');
        }
        var fxPiece = fxPack.pages[fxIdx];
        var fxLeft = fxPack.pages.length - fxIdx - 1;
        var fxPageNo = fxIdx + 1;
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'صفحه ' + fxPageNo + '…' });
        fxPack.i = fxIdx + 1;
        if (fxLeft > 0) {
          await env.BOT_KV.put('fx_more:' + fxId, JSON.stringify(fxPack), { expirationTtl: 3600 });
          await tg(env, 'sendMessage', {
            chat_id: cbChatId,
            text: fxPiece + '\n\n📄 صفحه ' + fxPageNo + ' از ' + fxPack.pages.length,
            disable_web_page_preview: true,
            reply_markup: {
              inline_keyboard: [[{ text: '⬇️ پایین / صفحه بعد (' + fxLeft + ')', callback_data: 'fx:more:' + fxId }]]
            }
          });
        } else {
          try { await env.BOT_KV.delete('fx_more:' + fxId); } catch (eFx) {}
          await tg(env, 'sendMessage', {
            chat_id: cbChatId,
            text: fxPiece + '\n\n📄 صفحه ' + fxPageNo + ' از ' + fxPack.pages.length + '\n✅ پایان لیست نرخ‌ها.',
            disable_web_page_preview: true
          });
        }
      } catch (eFx2) {
        try { await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'خطا', show_alert: true }); } catch (e3) {}
      }
      return new Response('ok');
    }

    // ===== NX: مرورگر صفحه‌بندی‌شده مدل =====
    if (data.indexOf('mprefresh:') === 0) {
      try {
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'در حال بارگذاری مدل‌ها…' });
        var refPid = data.slice('mprefresh:'.length);
        var refRole = await getUserRole(env, cbUid);
        await refreshProviderModels(env, cbChatId, cbUid, refRole, refPid, cq.message && cq.message.message_id);
      } catch (eRf) {
        try { await tgReply(env, cbChatId, 'خطا در بارگذاری: ' + (eRf.message || eRf)); } catch (e2) {}
      }
      return new Response('ok');
    }

    if (data.indexOf('mpprobe:') === 0) {
      try {
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'در حال تست…' });
        var probePid = data.slice('mpprobe:'.length);
        var probeRole = await getUserRole(env, cbUid);
        await runProviderModelProbe(env, cbChatId, cbUid, probeRole, probePid, cq.message && cq.message.message_id);
      } catch (ePr) {
        try { await tgReply(env, cbChatId, 'خطا در تست: ' + (ePr.message || ePr)); } catch (e2) {}
      }
      return new Response('ok');
    }

    if (data.indexOf('mp:') === 0) {
      try {
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id });
        // فرمت: mp:<pid>:<page>  — pid می‌تواند uk:uk_xxx باشد
        var mpRest = data.slice(3); // بعد از mp:
        var mpPage = 0;
        var mpPid = mpRest;
        var mpLastColon = mpRest.lastIndexOf(':');
        if (mpLastColon > 0) {
          var maybePage = mpRest.slice(mpLastColon + 1);
          if (/^\d+$/.test(maybePage) || maybePage === 'noop') {
            mpPage = parseInt(maybePage, 10) || 0;
            mpPid = mpRest.slice(0, mpLastColon);
          }
        }
        if (mpPid === 'noop') return new Response('ok');
        var mpRole = await getUserRole(env, cbUid);
        if (mpPid === '_') await showProviderMenu(env, cbChatId, cbUid, mpRole, cq.message.message_id);
        else await showProviderModels(env, cbChatId, cbUid, mpRole, mpPid, mpPage, cq.message.message_id);
      } catch (e) {}
      return new Response('ok');
    }

    if (data.indexOf('model:') === 0) {
      var token = data.replace('model:', '');
      var modelId = '', modelProv = '';
      var cbRole = await getUserRole(env, cbUid);

      if (token === 'addkey' || token === 'freekeys') {
        await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'راهنمای کلید' });
        await tgProcessText(env, cbUid, cbChatId, token === 'freekeys' ? '/freekeys' : '/addkey', (cq.from && cq.from.first_name) || 'کاربر');
        return new Response('ok');
      }

      if (token !== 'auto') {
        if (cbRole === 'public' && false) {
          await tg(env, 'answerCallbackQuery', {
            callback_query_id: cq.id,
            text: 'فقط خودکار برای شما',
            show_alert: true
          });
          return new Response('ok');
        }
        var cbMap = await loadModelCallbackMap(env, cbChatId);
        var ent = cbMap[token];
        if (!ent) {
          await tg(env, 'answerCallbackQuery', {
            callback_query_id: cq.id,
            text: 'لیست منقضی شده؛ دوباره /models را بزن'
          });
          return new Response('ok');
        }
        if (typeof ent === 'object') { modelId = ent.m || ''; modelProv = ent.p || ''; }
        else modelId = String(ent);
        if (cbRole !== 'admin') {
          var nxAccCb = await getAccess(env, cbUid);
          if (!accessAllows(nxAccCb, cbRole, modelProv, modelId)) {
            await tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'این مدل برای شما مجاز نیست', show_alert: true });
            return new Response('ok');
          }
        }
      }

      if (env.BOT_KV) {
        await env.BOT_KV.put('tg_model_' + cbUid, modelId ? JSON.stringify({ m: modelId, p: modelProv }) : 'auto');
      }

      await tg(env, 'answerCallbackQuery', {
        callback_query_id: cq.id,
        text: modelId ? 'مدل انتخاب شد ✓' : 'حالت خودکار فعال شد ✓'
      });

      await tgReply(env, cbChatId,
        modelId
          ? '✓ مدل انتخاب شد:\n' + modelId + '\n\nالان می‌تونی سوال بپرسی.'
          : '✓ حالت خودکار فعال شد.\nسیستم خودش بهترین مدل را انتخاب می‌کند.'
      );
    }
    return new Response('ok');
  }

  // ذخیره پست کانال وقتی ربات عضو است
  if (up.channel_post || up.edited_channel_post) {
    try {
      await storeChannelPost(env, up.channel_post || up.edited_channel_post);
    } catch (eCh) {}
    return new Response('ok');
  }

  var msg = up.message;
  if (!msg) return new Response('ok');

  // ذخیره پیام گروه‌ها / سوپرگروه‌ها وقتی ربات عضو است (برای خواندن بعدی)
  try {
    var ctype = (msg.chat && msg.chat.type) || '';
    if ((ctype === 'group' || ctype === 'supergroup') && (msg.text || msg.caption || msg.photo || msg.video || msg.document)) {
      // فقط پیام‌های واقعی کاربران — نه سرویس جویین
      if (!msg.left_chat_member && !msg.new_chat_members && !msg.group_chat_created) {
        await storeChannelPost(env, msg);
      }
    }
  } catch (eGrp) {}
  // اگر تلگرام همان آپدیت را دوباره فرستاد، دوباره پردازش نشود
  if (up.update_id && env.BOT_KV) {
    try {
      var dupKey = 'upd_' + up.update_id;
      if (await env.BOT_KV.get(dupKey)) return new Response('ok');
      await env.BOT_KV.put(dupKey, '1', { expirationTtl: 3600 });
    } catch (e) {}
  }
  var chatId = msg.chat.id;
  var uid = 'tg_' + chatId;
  var name = msg.chat.first_name || 'کاربر';

  var finished = false;
  var work = (async function () {
    try {
      var fromId = (msg.from && msg.from.id) || chatId;
      var isAdm = await isTgAdmin(env, fromId);

      // گروه‌ها: فقط با منشن یا /nova
      if (!isAdm && !shouldReplyInChat(msg, env)) return;

      // Rate limit
      if (FEATURES.rateLimit && !isAdm) {
        var rlOk = await rateLimit(env, 'chat:' + uid, RL_CHAT_MAX, RL_CHAT_WINDOW);
        if (!rlOk) {
          await tgReply(env, chatId, '⏳ تعداد پیام‌ها زیاد بود. چند دقیقه بعد دوباره امتحان کن.');
          return;
        }
      }
      await metricsInc(env, 'msgs', 1);
      // ثبت شناسه پیام کاربر برای پاک‌سازی بعدی چت
      try {
        if (msg && msg.message_id) await trackTgMsgId(env, chatId, msg.message_id);
      } catch (eTrackU) {}

      // Map rich keyboard buttons → commands / intents
      if (msg.text) {
        var btn = msg.text.trim();
        // اکشن سفارشی از پنل ادمین (اولویت)
        var usedCustomKb = false;
        try {
          var customAct = await resolveKeyboardButton(env, btn);
          if (customAct) {
            usedCustomKb = true;
            customAct = normalizeKeyboardAction(customAct, btn);
            if (customAct === '__news__') {
              await showNewsMenu(env, chatId);
              return;
            }
            if (customAct === '__support__') {
              await tgReply(env, chatId,
                '✉️ پشتیبانی\n\nپیام خود را این‌طور بفرست:\n/support متن پیام شما\n\nمثال:\n/support مشکل در انتخاب مدل دارم'
              );
              return;
            }
            if (customAct === '__hidekb__' || customAct === '/hidekb') {
              await hideKeyboardNow(env, chatId);
              return;
            }
            msg.text = customAct;
          }
        } catch (eAct) {}
        // اگر خود متن دکمه «پاک کردن» بود ولی اکشن اشتباه (بدون /) ذخیره شده
        if (/^(🗑️\s*)?پاک\s*کردن$|^\/?reset$/i.test(btn) && !/^\/reset$/i.test(String(msg.text || ''))) {
          msg.text = '/reset';
          usedCustomKb = true;
        }
        // نگاشت پیش‌فرض فقط اگر دکمه در منوی سفارشی نبود
        if (!usedCustomKb) {
          if (btn === '⚙️ مدیریت') msg.text = '/admin';
          else if (btn === '🎯 مدل‌ها') msg.text = '/models';
          else if (btn === '📊 وضعیت') msg.text = '/status';
          else if (btn === '📋 منو') msg.text = '/menu';
          else if (btn === '❓ راهنما') msg.text = '/help';
          else if (btn === '🗑️ پاک کردن' || btn === '/reset') msg.text = '/reset';
          else if (btn === '🔍 مهندسی معکوس' || btn === '/rea') msg.text = '/rea';
          else if (btn === '🔑 کلیدها') msg.text = '/keys';
          else if (btn === '📈 آمار') msg.text = '/stats';
          else if (btn === '🕐 ساعت') msg.text = 'ساعت چند است؟';
          else if (btn === '📰 اخبار' || btn === '📰 اخبار امروز' || btn === '📰 اخبار ۲۴س') {
            await showNewsMenu(env, chatId);
            return;
          }
          else if (btn === '🔄 تازه‌سازی اخبار') msg.text = '/news_refresh';
          else if (btn === '💰 ارز دیجیتال' || btn === 'ارز دیجیتال' || btn === 'کریپتو') msg.text = '/crypto';
          else if (btn === '💱 نرخ ارزها' || btn === '💵 قیمت دلار' || btn === '💰 قیمت دلار') msg.text = 'نرخ ارزها';
          else if (btn === '🌤️ آب و هوا' || btn === '🌤️ هوای تهران') msg.text = 'هوای تهران';
          else if (btn === '👥 کاربران') msg.text = '/users';
          else if (btn === '🔑 کاربران') msg.text = '/userkeys';
          else if (btn === '✉️ پشتیبانی' || btn === 'پشتیبانی') {
            await tgReply(env, chatId,
              '✉️ پشتیبانی\n\nپیام خود را این‌طور بفرست:\n/support متن پیام شما\n\nمثال:\n/support مشکل در انتخاب مدل دارم'
            );
            return;
          }
          else if (btn === '⬇️ بستن کیبورد' || btn === 'بستن کیبورد' || btn === '/hidekb') {
            await hideKeyboardNow(env, chatId);
            return;
          }
          else if (btn === 'کیبورد' || btn === '⌨️' || btn === '/keyboard' || btn === 'نوار') {
            var isAdmKb = await isTgAdmin(env, fromId);
            await tgReply(env, chatId, '⌨️ کیبورد فعال شد.', {
              reply_markup: tgKeyboardMarkup(await buildTgKeyboard(env, isAdmKb))
            });
            return;
          }
          else if (btn === '🔑 کلید رایگان' || btn === 'کلید رایگان' || btn === 'دریافت کلید') msg.text = '/freekeys';
          else if (btn === '📥 صندوق') msg.text = '/inbox';
          else if (btn === '🎭 حالت' || btn === 'حالت') msg.text = '/mode';
          else if (btn === '🧠 حافظه' || btn === 'حافظه') msg.text = '/memory';
          else if (btn === '📊 مصرف' || btn === 'مصرف') msg.text = '/usage';
        }
      }
      if (!isAdm && await isBanned(env, uid)) {
        await tgReply(env, chatId, '🚫 حساب شما مسدود شده است.');
        return;
      }
      if (!isAdm && msg.text) {
        if (msg.text.trim() === '/cancel') { await admSetState(env, uid, null); await tgReply(env, chatId, '↩️ لغو شد.'); return; }
        if (msg.text.charAt(0) !== '/' && msg.text.length <= 64) {
          var pst = await admGetState(env, uid);
          if (pst && pst.t === 'admpass') {
            await admSetState(env, uid, null);
            await tgAdminTryPass(env, msg, chatId, String(fromId), msg.text.trim());
            return;
          }
        }
      }
      await trackUser(env, uid, name, 'telegram');

      // ویزارد افزودن کلید شخصی (همه کاربران): سایت → کلید
      if (msg.text) {
        var uSt = null;
        try { uSt = await admGetState(env, uid); } catch (eUs) {}
        if (uSt && (uSt.t === 'uaddkey_site' || uSt.t === 'uaddkey_key')) {
          var ut = String(msg.text || '').trim();
          if (ut === '/cancel' || ut === 'لغو') {
            await admSetState(env, uid, null);
            await tgReply(env, chatId, '↩️ لغو شد.');
            return;
          }
          if (ut.charAt(0) === '/' && ut.indexOf('/addkey') !== 0) {
            // دستور دیگر — state را نگه ندار
            await admSetState(env, uid, null);
          } else if (uSt.t === 'uaddkey_site') {
            try { await tg(env, 'deleteMessage', { chat_id: chatId, message_id: msg.message_id }); } catch (eD1) {}
            var ub = extractApiBaseFromText(ut);
            var uk = extractApiKeyFromText(ut);
            if (ub && ub.base && uk && uk.length >= 8) {
              var modelsX = [];
              try { modelsX = await discoverUserKeyModels(env, { key: uk, site: ub.base, base: ub.base, name: ub.provider }); } catch (eX) {}
              await saveUserKey(env, uid, {
                provider: ub.provider || 'custom', name: ub.provider || 'کلید من',
                key: uk, base: ub.base, site: ub.base, freeOnly: !!ub.freeOnly,
                models: modelsX.slice(0, 80)
              }, name);
              await admSetState(env, uid, null);
              await tgReply(env, chatId,
                '✅ کلید شخصی ذخیره شد\n🏷 ' + (ub.provider || 'Custom') + '\n🌐 ' + ub.base + '\n' +
                (modelsX.length ? ('🤖 ' + modelsX.length + ' مدل:\n' + modelsX.slice(0, 12).map(function (m, i) { return (i + 1) + '. ' + m; }).join('\n')) : '⚠️ لیست مدل نیامد') +
                '\n\n🎯 /models'
              );
              return;
            }
            if (ub && ub.base) {
              await admSetState(env, uid, { t: 'uaddkey_key', site: ub.base, base: ub.base, provider: ub.provider || '' });
              await tgReply(env, chatId, '➕ مرحله ۲ از ۲\n🌐 ' + ub.base + '\n\n🔑 کلید API را بفرست.\nلغو: /cancel');
              return;
            }
            // فقط کلید معروف؟
            var knownK = false;
            Object.keys(PROVIDERS).forEach(function (id) { if (PROVIDERS[id].test(uk)) knownK = true; });
            if (uk && uk.length >= 8 && knownK) {
              var pKnown = 'openai';
              Object.keys(PROVIDERS).forEach(function (id) { if (PROVIDERS[id].test(uk)) pKnown = id; });
              var pvK = PROVIDERS[pKnown];
              await saveUserKey(env, uid, {
                provider: pKnown, name: (pvK && pvK.name) || pKnown,
                key: uk, base: (pvK && pvK.base) || '', site: (pvK && pvK.base) || ''
              }, name);
              await admSetState(env, uid, null);
              await tgReply(env, chatId, '✅ کلید «' + ((pvK && pvK.name) || pKnown) + '» ذخیره شد.\n🎯 /models');
              return;
            }
            await tgReply(env, chatId, '🌐 آدرس را نفهمیدم.\nمثال: https://api.example.com/v1\nلغو: /cancel');
            return;
          } else if (uSt.t === 'uaddkey_key') {
            try { await tg(env, 'deleteMessage', { chat_id: chatId, message_id: msg.message_id }); } catch (eD2) {}
            var uk2 = extractApiKeyFromText(ut);
            if (!uk2 || uk2.length < 8) {
              await tgReply(env, chatId, '❌ کلید معتبر نیست. دوباره بفرست یا /cancel');
              return;
            }
            var modelsY = [];
            try { modelsY = await discoverUserKeyModels(env, { key: uk2, site: uSt.site || uSt.base, base: uSt.base || uSt.site, name: uSt.provider }); } catch (eY) {}
            await saveUserKey(env, uid, {
              provider: uSt.provider || 'custom',
              name: uSt.provider || 'کلید من',
              key: uk2,
              base: uSt.base || uSt.site || '',
              site: uSt.site || uSt.base || '',
              models: modelsY.slice(0, 80)
            }, name);
            await admSetState(env, uid, null);
            await tgReply(env, chatId,
              '✅ کلید شخصی ذخیره شد\n🏷 ' + (uSt.provider || 'Custom') + '\n🌐 ' + (uSt.base || uSt.site || '') + '\n' +
              (modelsY.length ? ('🤖 مدل‌ها:\n' + modelsY.slice(0, 12).map(function (m, i) { return (i + 1) + '. ' + m; }).join('\n')) : '⚠️ لیست مدل نیامد — در چت تست کن') +
              '\n\n🎯 /models'
            );
            return;
          }
        }
      }

      // ورودی چندمرحله‌ای ادمین (ارسال همگانی، پیام به کاربر، افزودن کلید)
      if (isAdm && msg.text) {
        if (msg.text.trim() === '/cancel') {
          await admSetState(env, uid, null);
          await tgReply(env, chatId, '↩️ لغو شد.');
          return;
        }
        if (msg.text.charAt(0) !== '/') {
          var admSt = await admGetState(env, uid);
          if (admSt && await tgAdminHandleState(env, msg, chatId, uid, admSt)) return;
        }
      }

      if (msg.text && msg.text.indexOf('/') === 0) {
        var cmd = msg.text.trim().split(' ')[0].split('@')[0];
        if (cmd === '/admin') { await tgAdminEntry(env, msg, chatId); return; }
        if (cmd === '/users' || cmd === '/stats') {
          if (!isAdm) { await tgReply(env, chatId, '⛔ این دستور فقط برای ادمین است. (/admin)'); return; }
          if (cmd === '/users') await admShowUsers(env, chatId, null, 'a', 0);
          else await admShowStats(env, chatId, null);
          return;
        }
        if (cmd === '/health' || cmd === '/وضعیت_سیستم') {
          try {
            await tgReply(env, chatId, await novaHealthReport(env));
          } catch (eH) {
            await tgReply(env, chatId, 'خطا در گزارش سلامت: ' + (eH.message || eH));
          }
          return;
        }
        if (cmd === '/selftest' || cmd === '/آزمون') {
          try {
            await tgReply(env, chatId, '🧪 در حال خودآزمایی...');
            var stRes = await runSelfTest(env);
            await tgReply(env, chatId, formatSelfTestReport(stRes));
          } catch (eSt2) {
            await tgReply(env, chatId, 'خطا در خودآزمایی: ' + (eSt2.message || eSt2));
          }
          return;
        }
        if (cmd === '/rea' || cmd === '/معکوس' || cmd === '/reverse') {
          try { await saveUserMode(env, uid, 'rea'); } catch (eRea) {}
          await tgReply(env, chatId,
            '🔍 حالت مهندسی معکوس (با کلیدهای AI ربات)\n\n' +
            'این حالت داخل Nova است — ابزار لوکال REA جداست.\n\n' +
            '📤 چطور استفاده کنی:\n' +
            '۱) یک فایل کد بفرست (.js .py .ts .java .cs .go …)\n' +
            '۲) یا کپشن بگذار: «مهندسی معکوس کن»\n' +
            '۳) یا متن/کد را در چت بچسبان\n\n' +
            'خروجی: خلاصه · اجزا · رشته/API · ریسک · شبه‌کد در صورت امکان\n\n' +
            '⚠️ باینری خام (exe/dll) را کامل دیکامپایل نمی‌کند؛ برای آن REA لوکال:\n' +
            '`npx rea-agents setup`\n\n' +
            'خروج از حالت: /mode general'
          );
          return;
        }
        if (cmd === '/start') {
          try { await ensureKeyboardNormalized(env); } catch (eNk) {}
          await setBotMenu(env);
          if (isAdm) await setAdminCommands(env, chatId);
          var cap = capabilityReport(env);
          var startTxt = isAdm
            ? ('👋 ادمین، خوش آمدید — Nova ' + NOVA_VERSION + '\n\n' +
              '⚙️ /admin · 📥 /inbox · 👥 /users\n' +
              '🎯 /models · 🔑 /freekeys · 💰 /crypto')
            : ('👋 سلام ' + name + '!\nمن نوا ' + NOVA_VERSION + ' هستم.\n\n' +
              'امکانات:\n' +
              '💬 چت · 📰 اخبار · 💰 ارز دیجیتال · 🌤️ هوا\n' +
              '🎤 ویس · 📎 فایل · 🎨 تصویر\n\n' +
              '🔑 کلید رایگان AI:\n/freekeys → ثبت‌نام در سایت\n/addkey gemini KEY → ثبت کلید\n\n' +
              '✉️ پشتیبانی: /support متن پیام\n\n' +
              '🎯 /models · 📊 /status · 📋 /menu');
          await tgReply(env, chatId, startTxt, {
            reply_markup: tgKeyboardMarkup(await buildTgKeyboard(env, isAdm))
          });
          queueHideKeyboard(env, chatId, 10);
          // دوباره منوی دستورات را تنظیم کن (بعد از لاگ‌اوت هم فعال بماند)
          try { await setBotMenu(env); } catch (eM) {}
          return;
        }
        if (cmd === '/reset') {
          var resetInfo = await fullUserChatReset(env, uid, chatId);
          // حذف پیام‌های خودِ چت تلگرام (تا جایی که شناسه ذخیره شده)
          var alsoDel = [];
          try {
            if (msg && msg.message_id) alsoDel.push(msg.message_id);
          } catch (eMid) {}
          var delCount = 0;
          try {
            delCount = await clearTelegramChatMessages(env, chatId, alsoDel);
          } catch (eClr) {}
          // پیام کوتاه تایید (بعداً در ردیابی می‌ماند)
          try {
            var isAdmR = await isTgAdmin(env, chatId);
            await tgReply(env, chatId,
              '🗑️ ریست کامل شد\n' +
              '• حافظه ربات: پاک' + (resetInfo.hist ? ' (' + resetInfo.hist + ' پیام)' : '') + '\n' +
              '• پیام‌های چت تلگرام: ' + (delCount > 0 ? (delCount + ' پیام حذف شد') : 'شناسه‌ای برای حذف نبود (از این به بعد پیام‌ها ثبت می‌شوند)') + '\n' +
              '• آرشیو: ' + ((resetInfo.sessions || 0) + (resetInfo.archive || 0)) + ' مورد\n\n' +
              'اگر هنوز پیام قدیمی دیدی: در تلگرام Clear history را بزن (برای پیام‌هایی که قبل از این نسخه فرستاده شده‌اند).\n' +
              'حافظه شخصی: /forget',
              {
                reply_markup: tgKeyboardMarkup(await buildTgKeyboard(env, isAdmR))
              }
            );
            queueHideKeyboard(env, chatId, 10);
          } catch (eKbR) {}
          return;
        }

        // ========== Personal RAG Commands ==========
        if (cmd === '/myrag' || cmd === '/دانش' || cmd === '/mydocs') {
          var docs = await ragUserList(env, uid);
          if (!docs.length) {
            await tgReply(env, chatId, '📚 دانش شخصی شما خالی است.\n\nبرای اضافه کردن:\n/addrag متن یا توضیح\nیا فایل متنی بفرستید و بگویید «به دانش شخصی اضافه کن»');
            return;
          }
          var lines = ['📚 دانش شخصی شما (' + docs.length + ' سند):\n'];
          docs.forEach(function(d, i) {
            lines.push((i+1) + '. «' + d.name + '» — ' + d.chunks + ' بخش — ' + Math.round((d.size||0)/1000) + 'KB');
            lines.push('   حذف: /delrag ' + d.id);
          });
          lines.push('\n➕ اضافه کردن: /addrag متن شما');
          await tgReply(env, chatId, lines.join('\n'));
          return;
        }

        if (cmd === '/addrag') {
          var ragText = String(msg.text || '').replace(/^\/addrag\s*/i, '').trim();
          if (!ragText || ragText.length < 30) {
            await tgReply(env, chatId, '📝 متن را بعد از دستور بنویس:\n/addrag متن طولانی خودت اینجا\n\nحداقل ۳۰ کاراکتر لازم است.');
            return;
          }
          var name = ragText.slice(0, 40).replace(/\n/g, ' ') + (ragText.length > 40 ? '...' : '');
          await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
          var res = await ragUserIngest(env, uid, name, ragText);
          if (res.ok) {
            await tgReply(env, chatId, '✅ به دانش شخصی اضافه شد.\n📄 «' + name + '»\n🔢 ' + res.chunks + ' بخش\n\nحالا می‌توانی درباره‌اش سوال بپرسی.\nلیست: /myrag');
          } else {
            await tgReply(env, chatId, '❌ خطا: ' + (res.reason || 'ناموفق'));
          }
          return;
        }

        if (cmd === '/delrag') {
          var delId = String(msg.text || '').replace(/^\/delrag\s*/i, '').trim();
          if (!delId) {
            await tgReply(env, chatId, 'شناسه سند را بنویس:\n/delrag udoc_xxxx\n\nلیست اسناد: /myrag');
            return;
          }
          var ok = await ragUserDelete(env, uid, delId);
          await tgReply(env, chatId, ok ? '🗑️ سند حذف شد.\n/myrag' : '❌ سند پیدا نشد یا خطا رخ داد.');
          return;
        }
        // ========== End Personal RAG ==========

        if (cmd === '/models') {
          await showModels(env, chatId);
          return;
        }
        if (cmd === '/keys' || cmd === '/test') {
          // کلیدهای شخصی همه؛ وضعیت سرور فقط ادمین — مسیر متن
          await (async function(){ var _tx = msg.text.trim(); try { if (msg.reply_to_message && msg.reply_to_message.from && msg.reply_to_message.from.is_bot) { var _rt = msg.reply_to_message.text || msg.reply_to_message.caption || ''; if (_rt) _tx = injectReplyContext(_tx, _rt); } } catch(eRep){} await tgProcessText(env, uid, chatId, _tx, name); })();
          return;
        }
        if (cmd === '/fallback') {
          var cur = env.BOT_KV ? ((await env.BOT_KV.get('tg_fb_' + uid)) === 'on') : false;
          if (env.BOT_KV) await env.BOT_KV.put('tg_fb_' + uid, cur ? 'off' : 'on');
          await tgReply(env, chatId, cur
            ? '🔒 پشتیبان خاموش شد.\nفقط مدلی که انتخاب کرده‌ای جواب می‌دهد (اگر کند باشد صبر می‌کنم، اگر خطا بدهد خطا را نشان می‌دهم).'
            : '🔄 پشتیبان روشن شد.\nاگر مدل انتخابی ۲۵ ثانیه جواب نداد یا خطا داد، Cloudflare جواب می‌دهد و نامش زیر پیام نوشته می‌شود.');
          return;
        }
        if (cmd === '/debug') {
          if (!isAdm) { await tgReply(env, chatId, '⛔ این دستور فقط برای ادمین است. (/admin)'); return; }
          await tgDebug(env, uid, chatId);
          return;
        }
        if (cmd === '/export_settings' || cmd === '/export') {
          if (!isAdm) { await tgReply(env, chatId, '⛔ فقط ادمین.'); return; }
          try {
            var met = await metricsGet(env);
            var ks = await checkKeysStatus(env);
            var lines = [
              '📦 Export تنظیمات — Nova ' + NOVA_VERSION,
              'تاریخ: ' + nowFa(),
              '',
              '--- متریک امروز ---',
              met ? JSON.stringify(met) : 'ندارد',
              '',
              '--- وضعیت کلیدها (بدون مقدار خام) ---'
            ];
            (ks || []).forEach(function (x) {
              lines.push((x.connected ? '✅' : '❌') + ' ' + x.name + ' — keys:' + (x.keys || 0) + ' — ' + (x.detail || ''));
            });
            lines.push('', 'FEATURES: ' + JSON.stringify(FEATURES));
            await tgReply(env, chatId, lines.join('\n'));
          } catch (e) {
            await tgReply(env, chatId, '❌ export ناموفق: ' + (e.message || e));
          }
          return;
        }
        if (cmd === '/metrics') {
          if (!isAdm) { await tgReply(env, chatId, '⛔ فقط ادمین.'); return; }
          var mx = await metricsGet(env);
          await tgReply(env, chatId,
            '📈 متریک امروز:\n' +
            '💬 پیام: ' + ((mx && mx.msgs) || 0) + '\n' +
            '📰 اخبار: ' + ((mx && mx.news) || 0) + '\n' +
            '🖼 تصویر: ' + ((mx && mx.images) || 0) + '\n' +
            '🎙 صوت: ' + ((mx && mx.stt) || 0) + '\n' +
            '❌ خطا: ' + ((mx && mx.errors) || 0)
          );
          return;
        }
        if (cmd === '/menu') {
          await tgProcessText(env, uid, chatId, '/menu', name);
          return;
        }
        if (cmd === '/rates' || cmd === '/price' || cmd === '/fx') {
          await setBotMenu(env);
          await tgProcessText(env, uid, chatId, 'نرخ ارزها', name);
          return;
        }
        if (cmd === '/news') {
          await tgProcessText(env, uid, chatId, 'اخبار', name);
          return;
        }
        if (cmd === '/status') {
          await tgProcessText(env, uid, chatId, '/status', name);
          return;
        }
        if (cmd === '/help') {
          var helpAdm = await isTgAdmin(env, chatId);
          var helpTxt =
            '📖 راهنما — Nova ' + NOVA_VERSION + ':\n\n' +
            '• متن / ویس / عکس / فایل → پاسخ هوشمند\n' +
            '• «عکس ... بساز» → تصویرسازی\n' +
            '• 📰 اخبار → منوی دسته‌بندی\n' +
            '• /models → انتخاب مدل\n' +
            '• /freekeys → سایت‌های کلید رایگان AI\n' +
            '• /addkey gemini KEY → ثبت کلید شخصی\n' +
            '• /crypto → قیمت ارز دیجیتال\n' +
            '• /support متن → پیام به پشتیبانی\n' +
            '• /myrag → دانش شخصی شما\n' +
            '• /addrag متن → اضافه به دانش شخصی\n' +
            '• /status → وضعیت حساب\n' +
            '• /menu → منوی کامل\n' +
            '• /reset → پاک کردن تاریخچه';
          if (helpAdm) {
            helpTxt +=
              '\n\n⚙️ ادمین:\n' +
              '• /admin · /inbox · /users · /userkeys\n' +
              '• /setvip · /stats · /keys · /debug\n' +
              '• /alerts · /compare';
          }
          await tgReply(env, chatId, helpTxt);
          return;
        }
        if (cmd === '/digest') {
          await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
          var dig = await buildDailyDigest(env);
          await tgReply(env, chatId, dig || '⚠️ ساخت خلاصه ناموفق بود.');
          return;
        }
        if (cmd === '/tts' || cmd === '/speak' || cmd === '/بخوان') {
          var ttsArg = msg.text.replace(/^\/(tts|speak|بخوان)(@\w+)?\s*/i, '').trim();
          if (!ttsArg) {
            await tgReply(env, chatId,
              '🔊 تبدیل متن به صدا\n\n' +
              '• /tts متن شما اینجا\n' +
              '• یا فایل متنی بفرست با کپشن: صدا\n' +
              '• یا روی یک پیام ریپلای کن و بنویس: /tts');
            return;
          }
          await tgSendVoice(env, chatId, ttsArg);
          return;
        }
        if (cmd === '/digest_on') {
          await toggleDigestSub(env, chatId, true);
          await tgReply(env, chatId, '✅ خلاصه صبحگاهی برای این چت فعال شد.\n(نیاز به Cron Trigger روی ورکر دارد)');
          return;
        }
        if (cmd === '/digest_off') {
          await toggleDigestSub(env, chatId, false);
          await tgReply(env, chatId, '🔕 خلاصه صبحگاهی خاموش شد.');
          return;
        }
        if (cmd === '/prefs') {
          var prefArg = msg.text.replace(/^\/prefs(@\w+)?\s*/i, '').trim();
          if (!prefArg) {
            var curP = await getUserNewsCats(env, uid);
            await tgReply(env, chatId, '📌 ترجیح فعلی: ' + (curP.length ? curP.join('، ') : 'همه دسته‌ها') +
              '\n\nمثال:\n/prefs جنگ,اقتصادی\n/prefs clear');
            return;
          }
          if (/^clear|پاک|حذف/i.test(prefArg)) {
            await setUserNewsCats(env, uid, []);
            await tgReply(env, chatId, '✓ ترجیح خبر پاک شد (همه دسته‌ها).');
            return;
          }
          var cats = prefArg.split(/[,،\s]+/).map(function (x) { return x.trim(); }).filter(Boolean);
          await setUserNewsCats(env, uid, cats);
          await tgReply(env, chatId, '✓ ترجیح ذخیره شد: ' + cats.join('، '));
          return;
        }
        if (cmd === '/alerts') {
          if (!isAdm) { await tgReply(env, chatId, '⛔ فقط ادمین'); return; }
          var aArg = msg.text.replace(/^\/alerts(@\w+)?\s*/i, '').trim();
          if (!aArg) {
            var curA = await loadAlertKeywords(env);
            await tgReply(env, chatId, '🔑 کلیدواژه‌های هشدار:\n' + (curA.length ? curA.join('، ') : '(خالی)') +
              '\n\nمثال: /alerts غزه,زلزله,دلار');
            return;
          }
          if (/^clear|پاک/i.test(aArg)) {
            await saveAlertKeywords(env, []);
            await tgReply(env, chatId, '✓ هشدارها پاک شد');
            return;
          }
          var kws = aArg.split(/[,،]+/).map(function (x) { return x.trim(); }).filter(Boolean);
          await saveAlertKeywords(env, kws);
          await tgReply(env, chatId, '✓ هشدار ذخیره شد: ' + kws.join('، '));
          return;
        }
        if (cmd === '/compare') {
          if (!isAdm) { await tgReply(env, chatId, '⛔ فقط ادمین'); return; }
          // فرمت: /compare modelA | modelB | سوال
          var body = msg.text.replace(/^\/compare(@\w+)?\s*/i, '').trim();
          var parts = body.split('|').map(function (x) { return x.trim(); });
          if (parts.length < 3) {
            await tgReply(env, chatId, 'فرمت:\n/compare llama-3.2-3b-instruct | gemini-2.5-flash | سوال اینجا');
            return;
          }
          await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
          var mA = parts[0], mB = parts[1], q = parts.slice(2).join(' | ');
          var cmp = await compareModels(env, q, mA, '', mB, '');
          var outCmp = '⚖️ مقایسه مدل‌ها\n\n' +
            '🔹 A: ' + mA + '\n' + ((cmp.a && cmp.a.text) || ('❌ ' + ((cmp.a && cmp.a.error) || 'بدون جواب'))) + '\n\n' +
            '🔹 B: ' + mB + '\n' + ((cmp.b && cmp.b.text) || ('❌ ' + ((cmp.b && cmp.b.error) || 'بدون جواب')));
          await tgReply(env, chatId, outCmp.slice(0, 4000));
          return;
        }
        if (cmd === '/news_refresh' || cmd === '/newsrefresh') {
          await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
          try {
            await cacheDel(env, 'news:' + hashStr('ایران:fa'));
            await cacheDel(env, 'news:' + hashStr('world:en'));
            await cacheDel(env, 'digest:daily');
          } catch (e) {}
          var fresh = await withTimeout(newsRSS('اخبار ۲۴ ساعت اخیر', env, true), 14000);
          if (fresh) {
            if (typeof fresh === 'object' && fresh.type === 'news_chunks') {
              await tgSendNewsChunks(env, chatId, fresh.chunks);
            } else if (typeof fresh === 'string' && fresh.length > 1300) {
              await tgSendNewsChunks(env, chatId, splitNewsChunks(fresh, 1300));
            } else {
              await tgReply(env, chatId, typeof fresh === 'string' ? fresh : String(fresh));
            }
            var plainN = typeof fresh === 'string' ? fresh : (fresh.chunks || []).join('\n');
            try { await checkNewsAlerts(env, plainN); } catch (e3) {}
          } else {
            try { await notifyAdmins(env, '⚠️ /news_refresh ناموفق — همه فیدها شکست خوردند.'); } catch (e2) {}
            await tgReply(env, chatId, '⚠️ تازه‌سازی اخبار ناموفق بود. کمی بعد دوباره امتحان کن.');
          }
          return;
        }
        // دستورات دیگر (/crypto /freekeys /support /addkey /inbox …) → مسیر اصلی متن
        await (async function(){ var _tx = msg.text.trim(); try { if (msg.reply_to_message && msg.reply_to_message.from && msg.reply_to_message.from.is_bot) { var _rt = msg.reply_to_message.text || msg.reply_to_message.caption || ''; if (_rt) _tx = injectReplyContext(_tx, _rt); } } catch(eRep){} await tgProcessText(env, uid, chatId, _tx, name); })();
        return;
      }

      // ویس تلگرام / فایل صوتی (audio message)
      if (msg.voice || msg.audio) {
        await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
        var aObj = msg.voice || msg.audio;
        var ab = await tgDownload(env, aObj.file_id);
        if (!ab) {
          await tgReply(env, chatId, '❌ دانلود صدا ناموفق.');
          return;
        }
        // ویس تلگرام: ogg/opus — نام فایل درست برای Whisper مهم است
        var aMime = msg.voice ? 'audio/ogg' : (aObj.mime_type || 'audio/mpeg');
        var aName = aObj.file_name || (msg.voice ? 'voice.ogg' : 'audio.mp3');
        if (msg.voice && !/\.ogg$/i.test(aName)) aName = 'voice.ogg';
        var tr = await withTimeout(transcribe(env, ab, aMime, aName), 60000);
        if (!tr || !tr.text) {
          await tgReply(env, chatId,
            '❌ تشخیص گفتار ناموفق بود.\n' +
            '• ویس کوتاه‌تر (۳–۲۰ ثانیه) و واضح بفرست\n' +
            '• کلید Groq را در پنل چک کن\n' +
            '• یا Workers AI (Whisper) را bind کن');
          return;
        }
        var spoken = String(tr.text).trim();
        await tgReply(env, chatId, '🎙️ «' + spoken + '»\n_via ' + (tr.providerName || 'STT') + '_');
        // ویس را مثل پیام متنی پردازش کن (خبر، قیمت، سوال…)
        var capVoice = (msg.caption || '').trim();
        var toProcess = capVoice ? (capVoice + '\n' + spoken) : spoken;
        if (toProcess.length >= 2) {
          await tgProcessText(env, uid, chatId, toProcess, name);
        }
        try {
          var hv = await getHistory(env, uid);
          hv.push(
            { role: 'user', content: '[صدا] ' + spoken },
            { role: 'assistant', content: '🎙️ ' + spoken }
          );
          await saveHistory(env, uid, hv);
        } catch (e) {}
        return;
      }

      if (msg.document) {
        await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
        var ab2 = await tgDownload(env, msg.document.file_id);
        if (!ab2) {
          await tgReply(env, chatId, '❌ دانلود فايل ناموفق.');
          return;
        }
        var fname = msg.document.file_name || 'فايل';
        var mime2 = msg.document.mime_type || '';

        // فایل صوتی/آهنگ که به‌صورت document آمده (مثل m4a، mp3)
        if (isAudioLikeFile(mime2, fname)) {
          var trDoc = await withTimeout(transcribe(env, ab2, mime2, fname), 50000);
          if (!trDoc || !trDoc.text) {
            await tgReply(env, chatId,
              '❌ تبدیل فایل صوتی «' + fname + '» به متن ناموفق.\n' +
              '💡 کلید Groq لازم است. اگر فقط موسیقی بدون کلام است، متنی برای استخراج وجود ندارد.');
            return;
          }
          await tgReply(env, chatId, '🎵 متن داخل «' + fname + '»:\n' + trDoc.text);
          // فقط اگر کپشن/سوال همراه فایل بود، چت را اجرا کن
          var caption = (msg.caption || '').trim();
          if (caption) {
            await tgProcessText(env, uid, chatId, caption + '\n\n[متن فایل صوتی]:\n' + trDoc.text, name);
          }
          try {
            var hd = await getHistory(env, uid);
            hd.push(
              { role: 'user', content: '[صدا] ' + fname },
              { role: 'assistant', content: '🎵 ' + trDoc.text }
            );
            await saveHistory(env, uid, hd);
          } catch (e) {}
          return;
        }

        // باینری در حالت rea: استخراج رشته‌های قابل‌خواندن + تحلیل AI
        var modeBin = 'general';
        try { modeBin = await loadUserMode(env, uid); } catch (eMb) {}
        var capBin = (msg.caption || '').trim();
        if (!isTextLikeFile(mime2, fname) && !isAudioLikeFile(mime2, fname) &&
            (modeBin === 'rea' || isReaRequest(capBin))) {
          try {
            var u8b = new Uint8Array(ab2);
            var strs = [];
            var curS = '';
            for (var bi = 0; bi < Math.min(u8b.length, 800000); bi++) {
              var c = u8b[bi];
              if (c >= 32 && c < 127) {
                curS += String.fromCharCode(c);
              } else {
                if (curS.length >= 6) strs.push(curS);
                curS = '';
              }
            }
            if (curS.length >= 6) strs.push(curS);
            // یکتا و محدود
            var seenS = {};
            var uniq = [];
            for (var si = 0; si < strs.length && uniq.length < 200; si++) {
              var s = strs[si].slice(0, 200);
              if (seenS[s]) continue;
              seenS[s] = 1;
              uniq.push(s);
            }
            var binMsg =
              (capBin || 'این فایل باینری را تا حد ممکن مهندسی معکوس کن.') +
              '\n\n[فایل باینری: ' + fname + ' · حجم: ' + u8b.length + ' بایت]\n' +
              'رشته‌های قابل‌خواندن استخراج‌شده:\n' +
              uniq.slice(0, 120).join('\n') +
              '\n\nاز روی رشته‌ها حدس بزن هدف برنامه، APIها و فناوری چیست. بگو دیکامپایل کامل نداری.';
            await tgReply(env, chatId, '🔍 استخراج رشته از باینری «' + fname + '» و تحلیل…');
            await tgProcessText(env, uid, chatId, binMsg, name);
            return;
          } catch (eBin) {
            await tgReply(env, chatId, '❌ خواندن باینری ناموفق: ' + (eBin.message || eBin));
            return;
          }
        }

        // فایل متنی: هم mime هم پسوند چک می‌شود (تلگرام گاهی
        // application/octet-stream می‌فرستد حتی برای .txt/.md)
        var isTextFile2 = isTextLikeFile(mime2, fname);
        if (isTextFile2) {
          var text = '';
          try { text = new TextDecoder().decode(ab2); } catch (e) {}
          var capTxt = (msg.caption || '').trim();
          // تبدیل فایل متنی به صدا: کپشن «صدا» / tts / بخوان
          if (/^(صدا|صوت|tts|speak|بخوان|بخون|audio)/i.test(capTxt) || /تبدیل\s*به\s*صدا|به\s*صدا/i.test(capTxt)) {
            var speakBody = text.replace(/\s+/g, ' ').trim().slice(0, 1500);
            if (!speakBody) {
              await tgReply(env, chatId, '❌ فایل متنی خالی است.');
              return;
            }
            await tgReply(env, chatId, '🔊 در حال تبدیل «' + fname + '» به صدا…');
            var okFileTts = await tgSendVoice(env, chatId, speakBody);
            if (!okFileTts) {
              await tgReply(env, chatId, 'اگر فایل خیلی بلند است، فقط اول متن را با /tts بفرست.');
            }
            return;
          }

          // مهندسی معکوس: حالت rea یا کپشن مرتبط → تحلیل ساخت‌یافته با AI
          var modeNow = 'general';
          try { modeNow = await loadUserMode(env, uid); } catch (eM) {}
          if (modeNow === 'rea' || isReaRequest(capTxt) || (!capTxt && modeNow === 'rea')) {
            var reaLimit = 100000;
            var reaBody = text.slice(0, reaLimit);
            var reaTrunc = text.length > reaLimit;
            try { await ragIngest(env, fname, text.slice(0, 400000)); } catch (eRagR) {}
            var reaMsg =
              (capTxt || 'این فایل را مهندسی معکوس / تحلیل ساختاری کن.') +
              '\n\n[فایل: ' + fname + (reaTrunc ? ' — فقط بخش اول' : '') + ']\n' +
              '```\n' + reaBody + '\n```\n\n' +
              'ساختار جواب: خلاصه عملکرد · اجزا و جریان · رشته‌ها/API/نقاط مهم · ریسک · شبه‌کد یا بازطراحی در صورت امکان.';
            await tgReply(env, chatId, '🔍 در حال تحلیل مهندسی معکوس «' + fname + '»…');
            // ذخیره پیش‌نمایش منبع؛ نتیجه کامل بعد از جواب مدل در history می‌ماند
            try {
              await saveReaArchive(env, {
                uid: uid,
                fname: fname,
                analysis: '(در حال تحلیل در چت — نتیجه کامل در history)\n\n' + reaMsg.slice(0, 5000),
                sourcePreview: reaBody.slice(0, 8000),
                model: '',
                provider: '',
                channel: 'telegram'
              });
            } catch (eReaSv) {}
            await tgProcessText(env, uid, chatId, reaMsg, name);
            return;
          }

          // برنامه‌نویسی: کپشن درخواست رفع باگ / نسخه جدید / بنویس
          // فایل را مستقیم به مدل بده (نه فقط RAG) تا کد کامل و تمیز برگردد
          if (capTxt && isCodeRequest(capTxt)) {
            var codeLimit = 90000; // حدوداً برای context مدل‌های رایج
            var codeBody = text.slice(0, codeLimit);
            var truncated = text.length > codeLimit;
            // ذخیره در RAG برای سوال‌های بعدی
            try { await ragIngest(env, fname, text.slice(0, 400000)); } catch (eRag) {}
            var codeMsg =
              capTxt +
              '\n\n[فایل کد: ' + fname + (truncated ? ' — فقط ' + codeLimit + ' کاراکتر اول به دلیل حجم زیاد' : '') + ']\n' +
              '```\n' + codeBody + '\n```\n\n' +
              'دستور: کد را کامل و تمیز بازنویسی/رفع باگ کن. خروجی فقط توضیح کوتاه + بلاک کد کامل.';
            await tgReply(env, chatId, '🛠️ در حال بررسی و ' + (truncated ? 'بازنویسی بخش اول «' : 'بازنویسی «') + fname + '»…');
            await tgProcessText(env, uid, chatId, codeMsg, name);
            return;
          }

          // بدون کپشن برنامه‌نویسی: فقط RAG
          var rag = await ragIngest(env, fname, text.slice(0, 400000));
          await tgReply(env, chatId,
            (rag.ok ? '📁 «' + fname + '» ذخیره شد (' + rag.chunks + ' بخش). حالا سوال بپرس!\n\n💡 برای رفع باگ/نسخه جدید، فایل را با کپشن بفرست، مثلاً:\n«رفع باگ و نسخه جدیدشو بساز»' : '❌ ذخیره ناموفق: ' + (rag.reason || '')) +
            '\n\n💡 برای تبدیل به صدا، فایل را با کپشن «صدا» بفرست.');
          return;
        }

        var b64doc = b64(new Uint8Array(ab2));
        var du = 'data:' + mime2 + ';base64,' + b64doc;
        var isPdf2 = mime2 === 'application/pdf' || /\.pdf$/i.test(fname);
        var srDoc = null;

        // PDF: تحلیل واقعی با Gemini (inline_data)، نه به‌عنوان عکس
        if (isPdf2) {
          srDoc = await withTimeout(analyzePDF(env, 'اين فايل را کامل تحليل کن.', b64doc), FILE_ANALYSIS_TIMEOUT);
        }
        if (!srDoc) {
          srDoc = await withTimeout(seeFile(env, 'اين فايل را کامل تحليل کن.', du, mime2, uid), FILE_ANALYSIS_TIMEOUT);
        }

        if (srDoc && isPdf2 && srDoc.text.length > 100) {
          await ragIngest(env, fname, 'تحليل ' + fname + ':\n' + srDoc.text);
        }

        await tgReply(env, chatId,
          srDoc ? '👁️ «' + fname + '»:\n' + srDoc.text : '❌ تحلیل ناموفق (تایم‌اوت یا بدون سرویس).\n💡 /addkey gemini KEY یا کلید سیستم Gemini را در env بگذار.');
        return;
      }

      if (msg.photo && msg.photo.length) {
        await tg(env, 'sendChatAction', { chat_id: chatId, action: 'upload_photo' });
        // سایز متوسط ترجیح — عکس خیلی بزرگ API vision را می‌شکند
        var phList = msg.photo;
        var phPick = phList[Math.min(phList.length - 1, Math.max(0, phList.length - 2))];
        // اگر کوچک‌تر از ۱۰۰کیلوبایت است، بزرگ‌ترین را بگیر
        if (phPick && phPick.file_size && phPick.file_size < 80000 && phList.length > 1) {
          phPick = phList[phList.length - 1];
        }
        var ab3 = await tgDownload(env, phPick.file_id);
        if (!ab3 && phList.length > 1) {
          ab3 = await tgDownload(env, phList[phList.length - 1].file_id);
        }
        if (!ab3) {
          await tgReply(env, chatId, '❌ دانلود عکس ناموفق.');
          return;
        }
        // ویرایش تصویر: کپشن با «ویرایش: ...» یا «edit: ...»
        var capPhoto = String(msg.caption || '').trim();
        if (FEATURES.imageEdit && env.AI && /^(ویرایش|edit|imgedit)\s*[:：]/i.test(capPhoto)) {
          var editPrompt = capPhoto.replace(/^(ویرایش|edit|imgedit)\s*[:：]\s*/i, '').trim() || 'improve this image';
          try {
            var ed = await novaImageEdit(env, ab3, editPrompt);
            if (ed.ok && ed.bytes) {
              var fdE = new FormData();
              fdE.append('chat_id', String(chatId));
              fdE.append('photo', new Blob([ed.bytes], { type: ed.mime || 'image/png' }), 'edit.png');
              fdE.append('caption', '🖼️ ' + editPrompt.slice(0, 180) + '\n— ' + (ed.model || ''));
              var _sp1 = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendPhoto', { method: 'POST', body: fdE });
              try { await trackTgFromResponse(env, chatId, _sp1); } catch (eSp1) {}
              return;
            }
            await tgReply(env, chatId, '❌ ویرایش تصویر: ' + (ed.error || 'ناموفق'));
            return;
          } catch (eEd) {
            await tgReply(env, chatId, '❌ ویرایش: ' + (eEd.message || eEd));
            return;
          }
        }
        var bytes3 = new Uint8Array(ab3);
        var mime3 = detectImageMime(bytes3) || 'image/jpeg';
        var du2 = 'data:' + mime3 + ';base64,' + b64(bytes3);
        var visionQ = capPhoto || 'این تصویر را کامل و دقیق توضیح بده. هر متن، عدد، لوگو و جزئیات مهم را بنویس.';
        try {
          await tg(env, 'sendMessage', { chat_id: chatId, text: '🖼️ در حال تحلیل عکس…' });
        } catch (eWait) {}
        await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
        var sr2 = null;
        try {
          sr2 = await withTimeout(seeFile(env, visionQ, du2, mime3, uid), FILE_ANALYSIS_TIMEOUT);
        } catch (eVis) {
          sr2 = { error: (eVis && eVis.message) || 'exception' };
        }
        if (!sr2 || !sr2.text) {
          var why = (sr2 && sr2.error) ? String(sr2.error).slice(0, 400)
            : (!sr2 ? 'تایم‌اوت — زمان Worker تمام شد' : 'پاسخ خالی');
          await tgReply(env, chatId,
            '❌ تحلیل عکس ناموفق\n' +
            '📋 ' + why + '\n\n' +
            '✅ برای تحلیل خوب عکس حداقل یکی لازم است:\n' +
            '۱) پنل ادمین → کلید Gemini (شروع با AIza) — بهترین کیفیت\n' +
            '۲) Cloudflare → Worker → Bindings → AI\n' +
            '۳) کلید OpenRouter / Groq با مدل vision\n\n' +
            '💡 /selftest را بزن تا وضعیت کلیدها مشخص شود.');
          return;
        }
        var visionFoot = buildTruthFooter(sr2) || '';
        await tgReply(env, chatId, '🖼️ ' + sr2.text + visionFoot);
        var h = await getHistory(env, uid);
        h.push(
          { role: 'user', content: '[عکس]' + (capPhoto ? (' ' + capPhoto) : '') },
          { role: 'assistant', content: sr2.text }
        );
        await saveHistory(env, uid, h);
        return;
      }

      if (msg.text) {
        await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' });
        await (async function(){ var _tx = msg.text.trim(); try { if (msg.reply_to_message && msg.reply_to_message.from && msg.reply_to_message.from.is_bot) { var _rt = msg.reply_to_message.text || msg.reply_to_message.caption || ''; if (_rt) _tx = injectReplyContext(_tx, _rt); } } catch(eRep){} await tgProcessText(env, uid, chatId, _tx, name); })();
      }
    } catch (e) {
      try {
        await tgReply(env, chatId, '❌ خطا: ' + e.message);
      } catch (e2) {}
    }
  })().then(function () { finished = true; }).catch(function () { finished = true; });

  // فقط اگر کار واقعاً تمام نشده هشدار بده — نه بعد از جواب موفق
  var watchdog = new Promise(function (resolve) {
    setTimeout(function () {
      if (finished) return resolve();
      // یک بار دیگر کوتاه صبر؛ ممکن است جواب تازه ارسال شده باشد
      setTimeout(function () {
        if (finished) return resolve();
        tgReply(env, chatId, '⏱ پردازش بیش از حد طول کشید و متوقف شد.\nاگر جواب را دیدی، این پیام را نادیده بگیر.\nوگرنه دوباره بفرست یا /models → مدل خودکار.')
          .catch(function () {})
          .then(resolve);
      }, 8000);
    }, 55000);
  });

  var done = Promise.race([work, watchdog]);
  // بعد از اتمام پردازش: اگر کیبورد نشان داده شده، بعد از ~۱۰ثانیه جمع شود
  ctx.waitUntil(
    Promise.resolve(work)
      .then(function () { finished = true; })
      .catch(function () { finished = true; })
      .then(function () { return flushHideKeyboardJobs(env, null); })
  );
  await done;

  return new Response('ok');
}


