  /* اگر پنل با ?admin_token=... باز شده باشد، توکن به همه درخواست‌های API هم اضافه می‌شود */
  var ADMIN_TOKEN = "";
  try{ ADMIN_TOKEN = new URLSearchParams(location.search).get("admin_token") || ""; }catch(e){}

  function api(path, opt){
    opt = opt || {};
    opt.credentials = "same-origin";
    opt.cache = "no-store";
    if(ADMIN_TOKEN){
      path += (path.indexOf("?") === -1 ? "?" : "&") + "admin_token=" + encodeURIComponent(ADMIN_TOKEN);
    }
    var ctrl = null;
    var timer = null;
    try {
      if (typeof AbortController !== "undefined") {
        ctrl = new AbortController();
        opt.signal = ctrl.signal;
        timer = setTimeout(function(){ try { ctrl.abort(); } catch(e){} }, 20000);
      }
    } catch(eA) {}
    return fetch(path, opt).then(function(r){
      return r.text().then(function(t){
        if(timer) clearTimeout(timer);
        var d;
        try { d = JSON.parse(t); }
        catch(e) {
          d = { ok:false, error: (t && t.indexOf("<html") >= 0) ? "نشست منقضی — دوباره وارد شو" : "پاسخ نامعتبر" };
        }
        d._status = r.status;
        if (r.status === 401 || r.status === 403) d.error = d.error || "غیرمجاز — دوباره وارد ادمین شو";
        return d;
      });
    }).catch(function(e){
      if(timer) clearTimeout(timer);
      var msg = (e && e.name === "AbortError") ? "زمان تمام شد (timeout)" : ("خطای شبکه: " + (e && e.message || ""));
      return { ok:false, error: msg, _status:0 };
    });
  }

