  async function loadSecLog() {
    var box = document.getElementById("secLogList");
    var msg = document.getElementById("secLogMsg");
    if (!box) return;
    box.innerHTML = "<p class='muted'>...</p>";
    try {
      var r = await fetch("/api/admin/security-log?limit=80", { credentials: "same-origin" });
      var d = await r.json();
      if (!d || !d.ok) {
        box.innerHTML = "<p style='color:#dc2626'>" + esc((d && d.error) || "خطا") + "</p>";
        return;
      }
      var ev = d.events || [];
      if (!ev.length) {
        box.innerHTML = "<p class='muted'>هنوز رویدادی ثبت نشده. با یک ورود اشتباه یا درخواست غیرمجاز اینجا پر می‌شود.</p>";
        if (msg) msg.textContent = "";
        return;
      }
      var h = "<table style='width:100%;border-collapse:collapse'><thead><tr>" +
        "<th style='text-align:right;padding:6px;border-bottom:1px solid #e2e8f0'>نوع</th>" +
        "<th style='text-align:right;padding:6px;border-bottom:1px solid #e2e8f0'>IP</th>" +
        "<th style='text-align:right;padding:6px;border-bottom:1px solid #e2e8f0'>مسیر / جزئیات</th>" +
        "<th style='text-align:right;padding:6px;border-bottom:1px solid #e2e8f0'>زمان</th>" +
        "</tr></thead><tbody>";
      for (var i = 0; i < ev.length; i++) {
        var e = ev[i] || {};
        var when = e.ts ? new Date(e.ts).toLocaleString("fa-IR", { timeZone: "Asia/Tehran" }) : "—";
        var detail = (e.path ? esc(String(e.path).slice(0, 60)) : "") +
          (e.msg ? ("<br><span class='muted'>" + esc(String(e.msg).slice(0, 120)) + "</span>") : "") +
          (e.user ? ("<br><span class='muted'>user: " + esc(String(e.user).slice(0, 40)) + "</span>") : "");
        h += "<tr style='border-bottom:1px solid #f1f5f9'>" +
          "<td style='padding:8px 6px;color:" + kindColor(e.kind) + ";font-weight:600'>" + esc(kindLabel(e.kind)) + "</td>" +
          "<td style='padding:8px 6px;direction:ltr;text-align:left;font-family:monospace;font-size:.8rem'>" + esc(e.ip || "?") + "</td>" +
          "<td style='padding:8px 6px'>" + (detail || "—") + "</td>" +
          "<td style='padding:8px 6px;white-space:nowrap;font-size:.8rem'>" + esc(when) + "</td></tr>";
      }
      h += "</tbody></table>";
      box.innerHTML = h;
      if (msg) msg.textContent = "مجموع: " + (d.count || ev.length) + " رویداد";
    } catch (err) {
      box.innerHTML = "<p style='color:#dc2626'>" + esc(err.message || String(err)) + "</p>";
    }
  }
