/** تبدیل ارز (با نرخ لحظه‌ای) */
function currencyLabelFa(code) {
  var c = String(code || '').toUpperCase();
  var map = {
    USD: 'دلار', EUR: 'یورو', GBP: 'پوند', JPY: 'ین', TRY: 'لیر', CNY: 'یوان',
    AED: 'درهم', IRR: 'ریال', IRT: 'تومان', BTC: 'بیت‌کوین', ETH: 'اتریوم'
  };
  return map[c] || c;
}

function fmtMoneyFa(n) {
  var x = Number(n);
  if (!isFinite(x)) return String(n);
  // اعداد بزرگ را گرد کن
  if (Math.abs(x) >= 1000) x = Math.round(x);
  else if (Math.abs(x) >= 1) x = Math.round(x * 100) / 100;
  else x = Math.round(x * 10000) / 10000;
  try { return x.toLocaleString('fa-IR'); } catch (e) { return String(x); }
}

async function convertCurrency(amount, fromCur, toCur) {
  fromCur = String(fromCur || '').toUpperCase().trim();
  toCur = String(toCur || '').toUpperCase().trim();
  var FA_MAP = {
    'ریال': 'IRR', 'تومان': 'IRT', 'تومن': 'IRT', 'TOMAN': 'IRT', 'TOMANS': 'IRT', 'IRT': 'IRT',
    'IRAN': 'IRR', 'IRR': 'IRR',
    'دلار': 'USD', 'USD': 'USD', 'یورو': 'EUR', 'EUR': 'EUR',
    'پوند': 'GBP', 'GBP': 'GBP', 'ین': 'JPY', 'JPY': 'JPY',
    'لیر': 'TRY', 'TRY': 'TRY', 'یوان': 'CNY', 'یوآن': 'CNY', 'CNY': 'CNY',
    'درهم': 'AED', 'AED': 'AED'
  };
  fromCur = FA_MAP[fromCur] || FA_MAP[normalizeUnitToken(fromCur)] || fromCur;
  toCur = FA_MAP[toCur] || FA_MAP[normalizeUnitToken(toCur)] || toCur;

  var fromIsToman = fromCur === 'IRT';
  var toIsToman = toCur === 'IRT';
  var apiFrom = fromIsToman ? 'IRR' : fromCur;
  var apiTo = toIsToman ? 'IRR' : toCur;

  if (apiFrom === apiTo) {
    var same = amount;
    if (fromIsToman && !toIsToman) same = amount * 10;
    if (!fromIsToman && toIsToman) same = amount / 10;
    return {
      ok: true, value: same, rate: same / (amount || 1),
      from: fromCur, to: toCur,
      displayFrom: currencyLabelFa(fromIsToman ? 'IRT' : fromCur),
      displayTo: currencyLabelFa(toIsToman ? 'IRT' : toCur)
    };
  }

  var url = 'https://open.er-api.com/v6/latest/' + encodeURIComponent(apiFrom);
  var r;
  try { r = await toolsFetch(url, { headers: { 'User-Agent': 'Mozilla/5.0 NovaAI' } }, 10000); }
  catch (e) { return { ok: false, error: 'نرخ ارز در دسترس نیست' }; }
  if (!r || !r.ok) return { ok: false, error: 'نرخ ارز در دسترس نیست (کد ' + (r ? r.status : 0) + ')' };
  var d;
  try { d = await r.json(); } catch (e2) { return { ok: false, error: 'پاسخ نرخ ارز نامعتبر' }; }
  var rate = d && d.rates && d.rates[apiTo];
  if (!rate) return { ok: false, error: 'نرخ ' + currencyLabelFa(apiTo) + ' پیدا نشد' };
  var amtApi = fromIsToman ? amount * 10 : amount;
  var valApi = amtApi * rate;
  var value = toIsToman ? valApi / 10 : valApi;
  return {
    ok: true,
    value: value,
    rate: value / (amount || 1),
    from: fromCur,
    to: toCur,
    displayFrom: currencyLabelFa(fromIsToman ? 'IRT' : fromCur),
    displayTo: currencyLabelFa(toIsToman ? 'IRT' : toCur),
    updated: d.time_last_update_utc,
    source: 'open.er-api'
  };
}

function parseConvertRequest(raw) {
  var s = String(raw || '').replace(/^\/(convert|conv|تبدیل)\s*/i, '').trim();
  if (!s) {
    return { error: 'نمونه:\n• /convert 100 میلیون تومان به دلار\n• /convert 10 km to mile\n• /convert 25c to f' };
  }

  s = (typeof toEnDigits === 'function' ? toEnDigits(s) : s)
    .replace(/,/g, ' ').replace(/،/g, ' ').replace(/\s+/g, ' ').trim();

  // «100 میلیون تومان به دلار چند هست»
  var fa = s.match(/^([\d.]+)\s*(میلیارد|میلیون|هزار)?\s*(تومان|تومن|ریال|دلار|یورو|لیر|پوند|درهم|usd|eur|irr|irt|gbp|try|aed)?\s*(?:به|to|in|→|->|=)\s*(تومان|تومن|ریال|دلار|یورو|لیر|پوند|درهم|usd|eur|irr|irt|gbp|try|aed)/i);
  if (fa) {
    var amt0 = fa[1] + (fa[2] ? ' ' + fa[2] : '');
    var amount0 = (typeof parseFaAmount === 'function') ? parseFaAmount(amt0) : parseFloat(fa[1]);
    if (!isFinite(amount0)) return { error: 'عدد را نفهمیدم' };
    return { amount: amount0, from: (fa[3] || 'تومان').trim(), to: (fa[4] || '').trim(), faMoney: true };
  }

  // «100 میلیون تومان دلار» بدون «به»
  var fa2 = s.match(/^([\d.]+)\s*(میلیارد|میلیون|هزار)?\s*(تومان|تومن|ریال)\s+(دلار|یورو)/i);
  if (fa2) {
    var a2 = fa2[1] + (fa2[2] ? ' ' + fa2[2] : '');
    var amount2 = (typeof parseFaAmount === 'function') ? parseFaAmount(a2) : parseFloat(fa2[1]);
    if (isFinite(amount2)) return { amount: amount2, from: fa2[3], to: fa2[4], faMoney: true };
  }

  // استاندارد: 10 km to mile / 100 usd to irr
  var m = s.match(/^([-+]?[\d.]+)\s*([\w\u0600-\u06FF]+)?\s*(?:به|in|to|→|->)\s*([\w\u0600-\u06FF]+)\s*$/i);
  if (m) {
    var val = parseFloat(m[1]);
    if (isNaN(val)) return { error: 'عدد را نفهمیدم' };
    if (m[2] && /میلیون|هزار|میلیارد/i.test(m[2]) && typeof parseFaAmount === 'function') {
      val = parseFaAmount(m[1] + ' ' + m[2]);
    }
    return { amount: val, from: m[2] || '', to: m[3] || '' };
  }

  var m2 = s.match(/^([-+]?[\d.]+)\s*(\S+)\s+(?:به|در|to)\s+(\S+)\s*$/i);
  if (m2) {
    var v2 = parseFloat(m2[1]);
    if (!isNaN(v2)) return { amount: v2, from: m2[2], to: m2[3] };
  }

  return { error: 'قالب را نفهمیدم.\nنمونه‌ها:\n• /convert 100 میلیون تومان به دلار\n• /convert 50 usd to irr\n• /convert 10 km to mile\n• /convert 25c to f' };
}


async function novaToolConvert(env, chatId, raw) {
  var p = parseConvertRequest(raw);
  if (p.error) return typeof p.error === 'string' ? ('❌ ' + p.error) : p;

  var fromL = String(p.from || '').toLowerCase();
  var toL = String(p.to || '').toLowerCase();
  var isToman = /تومان|تومن|irt|rial|ریال|irr/.test(fromL) || /تومان|تومن|irt|rial|ریال|irr/.test(toL);
  var isUsd = /دلار|dollar|usd/.test(fromL) || /دلار|dollar|usd/.test(toL);
  var isEur = /یورو|euro|eur/.test(fromL) || /یورو|euro|eur/.test(toL);

  // ارز ایرانی → نرخ آزاد tgju + جواب فارسی
  if ((isToman && (isUsd || isEur)) || p.faMoney) {
    try {
      var natural = await tryPriceConversion(
        String(p.amount) + ' ' + (p.from || 'تومان') + ' به ' + (p.to || 'دلار'),
        env
      );
      if (natural) return natural;

      var rate = await fetchUsdTomanRate(env);
      if (rate && isToman && isUsd) {
        var fromIsToman = /تومان|تومن|irt|ریال|irr/.test(fromL) || (!fromL && p.faMoney);
        if (fromIsToman) {
          var usd = p.amount / rate;
          return '💱 تبدیل ارز (نرخ آزاد لحظه‌ای)\n\n' +
            '💵 هر ۱ دلار ≈ ' + rate.toLocaleString('fa-IR') + ' تومان\n' +
            '📥 مبلغ: ' + Number(p.amount).toLocaleString('fa-IR') + ' تومان\n' +
            '📤 معادل ≈ ' + usd.toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' دلار\n\n' +
            '⚠️ نرخ تقریبی بازار آزاد است.\n🕐 ' + (typeof nowFa === 'function' ? nowFa() : '');
        } else {
          var tom = p.amount * rate;
          return '💱 تبدیل ارز (نرخ آزاد لحظه‌ای)\n\n' +
            '💵 هر ۱ دلار ≈ ' + rate.toLocaleString('fa-IR') + ' تومان\n' +
            '📥 مبلغ: ' + Number(p.amount).toLocaleString('en-US') + ' دلار\n' +
            '📤 معادل ≈ ' + Math.round(tom).toLocaleString('fa-IR') + ' تومان\n\n' +
            '⚠️ نرخ تقریبی بازار آزاد است.\n🕐 ' + (typeof nowFa === 'function' ? nowFa() : '');
        }
      }
    } catch (eFa) {}
  }

  var off = tryConvertOffline(p.amount, p.from, p.to);
  if (off !== null) {
    var unitHint = (normalizeUnitToken(p.from) === 'c' || normalizeUnitToken(p.to) === 'c' ||
      normalizeUnitToken(p.from) === 'f' || normalizeUnitToken(p.to) === 'f') ? ' درجه' : '';
    return '🔄 ' + fmtMoneyFa(p.amount) + ' ' + p.from + ' = ' + fmtMoneyFa(off) + ' ' + p.to + unitHint;
  }

  var cur = await convertCurrency(p.amount, p.from, p.to);
  if (cur.ok) {
    var df = cur.displayFrom || currencyLabelFa(cur.from);
    var dt = cur.displayTo || currencyLabelFa(cur.to);
    var extra = '';
    if (cur.to === 'IRT' || cur.to === 'IRR' || dt === 'تومان' || dt === 'ریال') {
      extra += '\n⚠️ این نرخ تقریبی منبع عمومی است؛ با بازار آزاد ممکن است فرق داشته باشد.';
    }
    if (cur.updated) {
      try {
        var dtFa = new Date(cur.updated).toLocaleString('fa-IR', { timeZone: 'Asia/Tehran' });
        extra += '\n🕐 به‌روزرسانی: ' + dtFa;
      } catch (eD) {
        extra += '\n🕐 به‌روزرسانی: ' + String(cur.updated);
      }
    }
    return '💱 ' + fmtMoneyFa(p.amount) + ' ' + df + ' = ' + fmtMoneyFa(cur.value) + ' ' + dt +
      '\nنرخ تقریبی: هر ۱ ' + df + ' ≈ ' + fmtMoneyFa(cur.rate) + ' ' + dt + extra;
  }
  return '❌ ' + (cur.error || 'تبدیل ناموفق') +
    '\n\nنمونه:\n• /convert ۱۰۰ میلیون تومان به دلار\n• /convert ۱۰۰ دلار به تومان\n• /convert 10 km to mile';
}


