/* ============================================================================
 *  6) 🧠 ساخت کوییز / فلش‌کارت از متن یا سند
 * ========================================================================== */

async function novaToolQuiz(env, chatId, uid, raw) {
  var s = String(raw || '').replace(/^\/(quiz|کوییز|آزمون|تست)\s*/i, '').trim();

  var ctx = '';
  var sourceName = '';
  var m = s.match(/^(doc|سند)\s+(\S+)\s*([\s\S]*)$/i);
  if (m && typeof ragGetText === 'function') {
    var doc = await ragGetText(env, m[2]);
    if (doc) {
      ctx = doc.text.slice(0, 9000);
      sourceName = doc.name;
      if (m[3] && m[3].trim()) s = m[3].trim();
      else s = '';
    }
  }

  if (!ctx) {
    if (!s || s.length < 80) {
      return '🧠 ساخت کوییز\n\n' +
        'نمونه‌ها:\n' +
        '• /quiz متن آموزشی اینجا...\n' +
        '• /quiz doc udoc_xxxx از بخش ذخیره‌شگرام بپرس\n' +
        '• /quiz 5 (تعداد سؤال، همراه متن)\n';
    }
    ctx = s.slice(0, 9000);
  }

  var wantN = 5;
  var nMatch = s.match(/^\s*(\d{1,2})\s+(?=\S)/);
  if (nMatch) { wantN = Math.min(20, Math.max(3, parseInt(nMatch[1], 10))); s = s.slice(nMatch[0].length).trim(); }

  if (typeof ragUserQuery === 'function') {
    try {
      var personal = await ragUserQuery(env, uid, (sourceName || s || ctx).slice(0, 400));
      if (personal) ctx = personal + '\n\n' + ctx;
    } catch (e) {}
  }

  var msgs = [{
    role: 'system',
    content: 'تو یک معلم سخت‌گیر هستی. از متن داده‌شده چند سؤال چهارگزینه‌ای می‌سازی و فقط و فقط JSON معتبر برمی‌گردانی.\n' +
      'قالب دقیق (بدون هیچ توضیح اضافه، بدون markdown):\n' +
      '{"questions":[{"q":"سؤال","options":["الف","ب","ج","د"],"answer":0,"why":"دلیل کوتاه"}]}\n' +
      'قواعد: answer اندیس گزینه درست است (۰ تا ۳). why حداکثر ۱ جمله. هرگز جای‌خالی نگذار.'
  }, {
    role: 'user',
    content: 'از این متن ' + wantN + ' سؤال بساز:\n\n"""' + ctx + '"""'
  }];

  var out = await think(env, msgs, { maxTokens: 3000, timeout: 60000 });
  if (!out || !out.text) return '❌ ساخت کوییز ناموفق: ' + ((out && out.error) || 'timeout');

  var jsonText = String(out.text).replace(/```json/gi, '').replace(/```/g, '').trim();
  var start = jsonText.indexOf('{');
  var endQ = jsonText.lastIndexOf('}');
  if (start === -1 || endQ === -1 || endQ <= start) {
    return '🧠 پاسخ مدل JSON معتبر نبود. دوباره تلاش کن یا متن را کوتاه‌تر بده.\n\n' +
      'پاسخ خام:\n' + jsonText.slice(0, 600);
  }
  var parsed;
  try { parsed = JSON.parse(jsonText.slice(start, endQ + 1)); }
  catch (e) { return '❌ JSON مدل قابل خواندن نبود. دوباره تلاش کن.'; }

  var qs = (parsed && parsed.questions) || [];
  if (!qs.length) return '❌ مدل سؤالی نساخت.';

  var quizId = toolsId('qz');
  await toolsKvPut(env, 'quiz_' + quizId, JSON.stringify({
    uid: uid, chatId: chatId, src: sourceName || '', at: Date.now()
  }), 60 * 60 * 24 * 7);

  var lines = ['🧠 کوییز ' + (sourceName ? '— «' + sourceName + '»' : '') + '\n'];
  qs.slice(0, 20).forEach(function (q, i) {
    lines.push('');
    lines.push('<b>' + (i + 1) + ') ' + escapeHtml(String(q.q || '')) + '</b>');
    (q.options || []).slice(0, 5).forEach(function (o, oi) {
      lines.push('   ' + ['الف', 'ب', 'ج', 'د', 'هـ'][oi] + ') ' + escapeHtml(String(o)));
    });
  });
  lines.push('');
  lines.push('🆔 ' + quizId);
  lines.push('📖 پاسخ‌ها: /quizans ' + quizId + '');

  var kb = [];
  kb.push([{ text: '📖 نمایش پاسخ‌ها', callback_data: 'qzans:' + quizId }]);

  return {
    ok: true,
    text: lines.join('\n'),
    markup: kb.length ? { inline_keyboard: kb } : null
  };
}

