var CRYPTO_ALIAS = {
  'btc': 'bitcoin', 'بیت‌کوین': 'bitcoin', 'بیت کوین': 'bitcoin', 'بیتکوین': 'bitcoin',
  'eth': 'ethereum', 'اتریوم': 'ethereum', 'اتر': 'ethereum',
  'sol': 'solana', 'سولانا': 'solana',
  'bnb': 'binancecoin', 'بایننس': 'binancecoin',
  'xrp': 'ripple', 'ریپل': 'ripple',
  'ada': 'cardano', 'کاردانو': 'cardano',
  'doge': 'dogecoin', 'دوج': 'dogecoin',
  'ton': 'toncoin', 'تتر': 'tether', 'usdt': 'tether'
};

function parsePriceAlert(raw) {
  var s = String(raw || '').replace(/^\/(alert|pricealert|هشدار)\s*/i, '').trim();
  if (!s) return null;

  // نمونه: btc > 100000 | btc>=100000 | btc بالای 100000 | بیت کوین زیر 60k
  var m = s.match(/^(\S+)\s*(>=|<=|>|<|بالای|زیر|بیشتر از|کمتر از|بی\s*تر از)\s*\$?([\d.,]+)\s*(k|m)?\s*$/i);
  if (!m) return { error: 'قالب: /alert btc > 100000 یا /alert بیت‌کوین زیر 60000' };
  var sym = m[1].trim().toLowerCase();
  var id = CRYPTO_ALIAS[sym] || CRYPTO_ALIAS[sym.replace(/\s+/g, ' ')] || sym;
  var opRaw = m[2];
  var op = opRaw;
  if (/بالای|بیشتر از|>/.test(opRaw)) op = '>';
  if (/زیر|کمتر از|بی\s*تر از|</.test(opRaw)) op = '<';
  if (opRaw === '>=') op = '>=';
  if (opRaw === '<=') op = '<=';
  var val = parseFloat(m[3].replace(/,/g, ''));
  var mult = (m[4] || '').toLowerCase();
  if (mult === 'k') val *= 1000;
  if (mult === 'm') val *= 1000000;
  if (isNaN(val)) return { error: 'عدد نامعتبر' };
  return { id: id, op: op, value: val };
}

async function novaToolAlertAdd(env, chatId, uid, raw) {
  var p = parsePriceAlert(raw);
  if (!p) {
    var list0 = await alertListAll(env);
    var mine0 = list0.filter(function (a) { return a.uid === uid; });
    if (!mine0.length) {
      return '📈 هشدار قیمت\n\nهنوز هشداری نساخته‌اید.\n\n' +
        'نمونه‌ها:\n' +
        '• /alert btc > 100000\n' +
        '• /alert eth زیر 2000\n' +
        '• /alert بیت‌کوین بالای 90k\n' +
        '• /alertlist — لیست هشدارهای شما';
    }
    return await novaToolAlertList(env, chatId, uid);
  }
  if (p.error) return '❌ ' + p.error;

  var all = await alertListAll(env);
  all.push({
    id: toolsId('al'), uid: uid, chatId: chatId,
    coin: p.id, op: p.op, value: p.value, ts: Date.now(), fired: false
  });
  await alertSaveAll(env, all);
  return '📈 هشدار ثبت شد.\n\n' + await novaToolAlertList(env, chatId, uid);
}

async function novaToolAlertList(env, chatId, uid) {
  var all = await alertListAll(env);
  var mine = all.filter(function (a) { return a.uid === uid; });
  if (!mine.length) {
    return '📈 هشدارهای شما: خالی\n\nنمونه: /alert btc > 100000';
  }
  var sym = { bitcoin: 'BTC', ethereum: 'ETH', solana: 'SOL', binancecoin: 'BNB', ripple: 'XRP', cardano: 'ADA', dogecoin: 'DOGE', tether: 'USDT', toncoin: 'TON' };
  var lines = ['📈 هشدارهای شما (' + mine.length + '):\n'];
  mine.forEach(function (a, i) {
    lines.push((i + 1) + '. ' + (sym[a.coin] || a.coin.toUpperCase()) + ' ' +
      (a.op === '>' ? 'بالای ' : a.op === '>=' ? '≥ ' : a.op === '<' ? 'زیر ' : '≤ ') +
      '$' + fmtNum(a.value) +
      (a.fired ? '  🔔 (قبلاً فعال شد)' : '') + '\n   🆔 ' + a.id);
  });
  lines.push('\nحذف: /alertdel ID   بررسی فوری: /alertcheck');
  return lines.join('\n');
}

async function novaToolAlertDel(env, chatId, uid, id) {
  var all = await alertListAll(env);
  var before = all.length;
  all = all.filter(function (a) { return !(a.uid === uid && a.id === id); });
  await alertSaveAll(env, all);
  if (all.length === before) return '❌ هشداری با این شناسه نیست.';
  return '🗑️ هشدار حذف شد.\n\n' + await novaToolAlertList(env, chatId, uid);
}

/** بررسی هشدارهای قیمت (از cron) */
async function novaRunPriceAlerts(env) {
  if (!env.BOT_KV) return 0;
  var all = await alertListAll(env);
  if (!all.length) return 0;
  var active = all.filter(function (a) { return !a.fired; });
  if (!active.length) return 0;

  var coins = {};
  active.forEach(function (a) { coins[a.coin] = 1; });
  var ids = Object.keys(coins).join(',');
  var prices = null;

  try {
    var r = await toolsFetch(
      'https://api.coingecko.com/api/v3/simple/price?ids=' + encodeURIComponent(ids) + '&vs_currencies=usd',
      { headers: { 'Accept': 'application/json', 'User-Agent': 'Mozilla/5.0 NovaAI' } }, 12000);
    if (r && r.ok) prices = await r.json();
  } catch (e) {}

  if (!prices) {
    try {
      if (typeof fetchCryptoPricesFull === 'function') {
        var full = await fetchCryptoPricesFull();
        if (full && full.data) {
          prices = {};
          Object.keys(full.data).forEach(function (k) { prices[k] = { usd: full.data[k].usd }; });
        }
      }
    } catch (e2) {}
  }
  if (!prices) return 0;

  var sym = { bitcoin: 'BTC', ethereum: 'ETH', solana: 'SOL', binancecoin: 'BNB', ripple: 'XRP', cardano: 'ADA', dogecoin: 'DOGE', tether: 'USDT', toncoin: 'TON' };
  var fired = 0;
  for (var i = 0; i < all.length; i++) {
    var a = all[i];
    if (a.fired) continue;
    var p = prices[a.coin] && prices[a.coin].usd;
    if (!p) continue;
    var hit = false;
    if (a.op === '>') hit = p > a.value;
    else if (a.op === '>=') hit = p >= a.value;
    else if (a.op === '<') hit = p < a.value;
    else if (a.op === '<=') hit = p <= a.value;
    if (!hit) continue;

    a.fired = true;
    a.firedAt = Date.now();
    a.actual = p;
    fired++;
    var chatId = String(a.chatId || '').replace(/^tg_/, '');
    if (chatId && env.TELEGRAM_BOT_TOKEN) {
      try {
        await tg(env, 'sendMessage', {
          chat_id: chatId,
          text: '🔔 <b>هشدار قیمت فعال شد</b>\n\n' +
            (sym[a.coin] || a.coin.toUpperCase()) + ' ' +
            (a.op === '>' ? 'از ' + a.value + ' عبور کرد' : a.op === '>=' ? 'به ' + a.value + ' رسید یا بالاتر رفت' :
             a.op === '<' ? 'به زیر ' + a.value + ' رسید' : 'به ' + a.value + ' رسید یا پایین‌تر رفت') + '\n\n' +
            '💵 قیمت فعلی: $' + fmtNum(p) + '\n🕐 ' + fmtWhenFa(Date.now()) +
            '\n\n🆔 ' + a.id + ' (برای غیرفعال‌کردن: /alertdel ' + a.id + ')'
        });
      } catch (e3) {}
    }
  }
  if (fired) await alertSaveAll(env, all);
  return fired;
}

/* ============================================================================
 *  8) 🔍 جستجو در تاریخچه چت + خروجی گرفتن
 * ========================================================================== */

async function novaToolChatSearch(env, uid, chatId, raw) {
  var q = String(raw || '').replace(/^\/(findchat|searchchat|جستجو)\s*/i, '').trim();
  if (!q) return '🔍 نمونه: /findchat کلمه کلیدی';
  var needle = q.toLowerCase();

  var hist = [];
  try { hist = await getHistory(env, uid); } catch (e) { hist = []; }

  var hits = [];
  for (var i = 0; i < (hist || []).length; i++) {
    var m = hist[i];
    var c = String(m.content != null ? m.content : (m.text || ''));
    if (c.toLowerCase().indexOf(needle) !== -1) {
      hits.push({ i: i, role: m.role, text: c });
    }
  }

  // اگر در تاریخچه زنده نبود، آرشیو را هم بگرد
  var archived = 0;
  if (typeof loadMsgArchive === 'function') {
    try {
      var arch = await loadMsgArchive(env, 200);
      archived = (arch || []).filter(function (a) {
        return String(a.user || '').toLowerCase().indexOf(needle) !== -1 ||
               String(a.bot || '').toLowerCase().indexOf(needle) !== -1;
      }).length;
    } catch (e2) {}
  }

  if (!hits.length && !archived) {
    return '🔍 چیزی برای «' + q + '» پیدا نشد.\n' +
      (typeof getHistory === 'function' ? 'تعداد پیام‌های تاریخچه فعلی: ' + ((hist || []).length) + '\n' : '') +
      'شاید پیام در گفتگوی بایگانی‌شده باشد.';
  }

  var out = ['🔍 نتایج «' + q + '» — ' + hits.length + ' مورد در تاریخچه فعلی' +
    (archived ? ' · ' + archived + ' مورد در آرشیو' : '') + '\n'];
  hits.slice(-12).forEach(function (h) {
    var snippet = h.text.replace(/\s+/g, ' ');
    var pos = snippet.toLowerCase().indexOf(needle);
    var start = Math.max(0, pos - 90);
    var cut = snippet.slice(start, start + 320);
    out.push('\n' + (h.role === 'user' ? '👤 شما' : '🤖 نوا') + ':\n… ' + cut + (snippet.length > start + 320 ? ' …' : ''));
  });
  if (!hits.length) {
    out.push('\n(فقط در آرشیو پیدا شد — با پنل ادمین ببینید)');
  }
  return out.join('\n');
}

async function novaToolExport(env, uid, chatId, raw) {
  var fmt = String(raw || '').replace(/^\/export\s*/i, '').trim().toLowerCase();
  var hist = [];
  try { hist = await getHistory(env, uid); } catch (e) {}

  if (!hist || !hist.length) return '📤 تاریخچه‌ای برای خروجی وجود ندارد.';

  var title = 'Nova Chat — ' + (typeof nowFa === 'function' ? nowFa() : new Date().toISOString());
  var body;
  var ext = 'md';
  var mime = 'text/markdown';

  if (fmt === 'json') {
    body = JSON.stringify({
      exportedAt: new Date().toISOString(),
      uid: uid,
      count: hist.length,
      messages: hist.map(function (m) {
        return { role: m.role, content: m.content != null ? m.content : (m.text || '') };
      })
    }, null, 2);
    ext = 'json'; mime = 'application/json';
  } else if (fmt === 'txt') {
    body = title + '\n' + '='.repeat(40) + '\n\n' + hist.map(function (m) {
      return (m.role === 'user' ? '👤 You:\n' : '🤖 Nova:\n') + String(m.content != null ? m.content : (m.text || ''));
    }).join('\n\n');
    ext = 'txt'; mime = 'text/plain';
  } else {
    body = '# ' + title + '\n\n' + hist.map(function (m) {
      var who = m.role === 'user' ? '👤 شما' : (m.role === 'assistant' ? '🤖 نوا' : '⚙️ سیستم');
      var c = String(m.content != null ? m.content : (m.text || ''));
      return '### ' + who + '\n\n' + c + '\n';
    }).join('\n---\n\n');
  }

  var fname = 'nova-chat-' + Date.now().toString(36) + '.' + ext;
  var sent = false;
  if (env.TELEGRAM_BOT_TOKEN) {
    try {
      var fd = new FormData();
      fd.append('chat_id', String(chatId));
      fd.append('document', new Blob([body], { type: mime + ';charset=utf-8' }), fname);
      fd.append('caption', '📤 خروجی گفتگو — ' + hist.length + ' پیام');
      var r = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendDocument', { method: 'POST', body: fd });
      sent = !!(r && r.ok);
    } catch (e) {}
  }
  if (!sent) {
    return { ok: true, file: { name: fname, text: body, mime: mime } };
  }
  return '📤 خروجی ارسال شد (' + hist.length + ' پیام · ' + ext + ').\nبرای فرمت‌های دیگر: /export json یا /export txt';
}

/* ============================================================================
 *  9) 🧾 خلاصه صوت/ویدیوی بلند
 * ========================================================================== */

/** خلاصه‌سازی متن بلند (برای ویدیو/پادکست) */
async function summarizeLongText(env, text, lang, maxChars) {
  text = String(text || '');
  maxChars = maxChars || 200000;
  if (text.length > maxChars) text = text.slice(0, maxChars);
  if (text.trim().length < 120) return { ok: false, error: 'متن کوتاه است' };

  // تکه‌بندی و خلاصه هر تکه، سپس خلاصه نهایی
  var pieces = [];
  var step = 6000;
  for (var i = 0; i < text.length; i += step) pieces.push(text.slice(i, i + step));
  if (pieces.length > 12) pieces = pieces.slice(0, 12);

  var partials = [];
  for (var p = 0; p < pieces.length; p++) {
    var r = await think(env, [
      { role: 'system', content: 'متن را دقیق و کوتاه خلاصه کن. نکات مهم، اعداد، اسم‌ها و نتیجه‌گیری را نگه دار. فارسی بنویس.' },
      { role: 'user', content: 'بخش ' + (p + 1) + ' از ' + pieces.length + ':\n\n' + pieces[p] }
    ], { maxTokens: 700, timeout: 30000 });
    if (r && r.text) partials.push('• ' + r.text);
    if (partials.length >= 12) break;
  }
  if (!partials.length) return { ok: false, error: 'مدل خلاصه نکرد' };

  var merged = partials.join('\n');
  var final = merged;
  if (merged.length > 2500) {
    var fr = await think(env, [
      { role: 'system', content: 'از خلاصه‌های زیر یک خلاصه نهایی یکپارچه بساز: ۵ تا ۱۰ نکته کلیدی + یک جمع‌بندی. فارسی.' },
      { role: 'user', content: merged.slice(0, 12000) }
    ], { maxTokens: 1200, timeout: 40000 });
    final = (fr && fr.text) ? fr.text : merged.slice(0, 3000);
  }
  return { ok: true, text: final, chunks: pieces.length };
}

/* ============================================================================
 *  10) 🎲 ابزارهای کوچک متفرقه
 * ========================================================================== */

/** شانس / قرعه‌کشی */
function pickRandom(list, n) {
  var arr = (list || []).slice();
  var out = [];
  while (arr.length && out.length < (n || 1)) {
    out.push(arr.splice(Math.floor(Math.random() * arr.length), 1)[0]);
  }
  return out;
}

/** متن → نقشه ذهنی ساده (Markdown) */
function toMindMap(text) {
  var lines = String(text || '').split(/\n+/).map(function (l) { return l.trim(); }).filter(Boolean);
  var root = lines.shift() || 'موضوع';
  var out = ['- ' + root];
  lines.slice(0, 40).forEach(function (l) {
    var t = l.replace(/^[-*•]\s*/, '').replace(/^#+\s*/, '').trim();
    if (!t) return;
    if (/^[\d.)\s-]+$/.test(t)) return;
    out.push('  - ' + t.slice(0, 120));
  });
  return out.join('\n');
}

/** آمار متن */
function textStats(text) {
  var t = String(text || '');
  var words = (t.match(/\S+/g) || []).length;
  var chars = t.length;
  var fa = (t.match(/[\u0600-\u06FF]/g) || []).length;
  var en = (t.match(/[a-zA-Z]/g) || []).length;
  var sents = (t.match(/[.!?؟…\n]/g) || []).length;
  var lines = t.split('\n').length;
  return {
    chars: chars, words: words, fa: fa, en: en,
    sentences: Math.max(1, sents), lines: lines,
    readingMin: Math.max(1, Math.round(words / 200))
  };
}

/* ============================================================================
 *  11) API وب برای ابزارها (اختیاری)
 * ========================================================================== */

async function novaToolsApi(request, env, cors, url) {
  if (typeof isAuthed === 'function' && !(await isAuthed(request, env))) {
    return jsonError('غيرمجاز', cors, 401);
  }
  var action = url.pathname.replace('/api/tools', '').replace(/^\//, '') || 'convert';
  var q = url.searchParams;

  try {
    if (action === 'link' && request.method === 'GET') {
      var r = await novaToolLinkSummary(env, 0, q.get('url') || '');
      return json(r.ok ? { ok: true, summary: r.text } : { ok: false, error: r.error }, cors);
    }
    if (action === 'convert' && request.method === 'GET') {
      var raw = (q.get('q') || q.get('from') || '') +
        (q.get('from') ? ' ' + q.get('from') + ' to ' + (q.get('to') || '') : '');
      var t = await novaToolConvert(env, 0, raw);
      return json({ ok: true, result: t }, cors);
    }
    if (action === 'stats' && request.method === 'GET') {
      return json({ ok: true, stats: textStats(q.get('text') || '') }, cors);
    }
    if (action === 'mindmap' && request.method === 'GET') {
      return json({ ok: true, map: toMindMap(q.get('text') || '') }, cors);
    }
    return jsonError('ابزار ناشناخته', cors, 404);
  } catch (e) {
    return jsonError('خطا: ' + (e.message || ''), cors, 500);
  }
}

/* ============================================================================
 *  12) Cron / زمان‌بندی — این تابع را در scheduled() صدا بزن
 * ========================================================================== */

async function novaScheduledTick(env) {
  var result = { reminders: 0, priceAlerts: 0 };
  try {
    result.reminders = await novaRunDueReminders(env);
  } catch (e) {
    try { await notifyAdmins(env, '❌ خطای یادآورها: ' + (e.message || e)); } catch (e2) {}
  }
  try {
    result.priceAlerts = await novaRunPriceAlerts(env);
  } catch (e3) {
    try { await notifyAdmins(env, '❌ خطای هشدار قیمت: ' + (e3.message || e3)); } catch (e4) {}
  }
  console.log('[nova-tools] tick', JSON.stringify(result));
  return result;
}

/* ============================================================================
 *  13) روتر مرکزی — این تابع را در tgProcessTextInner صدا بزن
 * ========================================================================== */


/* ============================================================================
/* ==========================================================================
 * NOVA CHANNEL READER v3 — integrated into full worker
 * Fixed: subrequest limits, strict intent, no Google scrape, clear diagnostics
 * ========================================================================== */

/* ============================================================================
 * NOVA CHANNEL READER v3 — بازنویسی کامل
 * سبک‌تر، قابل‌اعتمادتر، بدون گیر کردن روی سقف subrequest
 * با پیام خطای دقیق و تشخیص intent سخت‌گیرتر
 *
 * نحوه استفاده:
 * 1) توابع زیر را در فایل اصلی Worker پیدا کن و کاملاً جایگزین نسخه‌ی قبلی‌شان کن.
 * 2) داخل novaMaybeHandle بلوک follow-up قدیمی را با نسخه‌ی انتهای این فایل عوض کن.
 * 3) تابع storeChannelPost را در مسیر دریافت پیام‌های گروه/کانال (webhook) صدا بزن
 *    تا پست‌های کانال‌هایی که ربات عضو آن‌هاست ذخیره شوند.
 * ========================================================================== */

/** استخراج یوزرنیم کانال/گروه از لینک، منشن یا متن آزاد */
function parseChannelUsername(raw) {
  var s = String(raw || '').trim();
  if (!s) return null;

  var linkMatch = s.match(/(?:https?:\/\/)?(?:t\.me|telegram\.me)\/(?:s\/)?([a-zA-Z][a-zA-Z0-9_]{3,31})(?:\/\d+)?/i);
  if (linkMatch) return linkMatch[1].toLowerCase();

  var atMatch = s.match(/@([a-zA-Z][a-zA-Z0-9_]{3,31})\b/);
  if (atMatch) return atMatch[1].toLowerCase();

  s = s.replace(/^\/(channel|chan|کانال|کانال‌خوان|channelread)\s*/i, '').trim();
  s = s.replace(/\b(نیم\s*ساعت|یک\s*ساعت|دو\s*ساعت|امروز|دیروز|ساعت|دقیقه|روز|هفته|\d+[mhd]|آخرین|پیام|پست|مطلب|گروه|کانال)\b/gi, ' ');
  s = s.replace(/https?:\/\/\S+/gi, ' ');
  s = s.replace(/@/g, ' ');
  var parts = s.trim().split(/[\s\/?#،,]+/).filter(Boolean);
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i].replace(/[^a-zA-Z0-9_]/g, '');
    if (p.length >= 4 && p.length <= 32 && /^[a-zA-Z]/.test(p)) return p.toLowerCase();
  }
  return null;
}

/** استخراج username + postId از لینک پیام مشخص t.me/name/123 */
function parseTelegramPostRef(raw) {
  var s = String(raw || '');
  var m = s.match(/(?:https?:\/\/)?(?:t\.me|telegram\.me)\/(?:s\/)?([a-zA-Z][a-zA-Z0-9_]{3,31})(?:\/(\d+))?/i);
  if (!m) m = s.match(/@([a-zA-Z][a-zA-Z0-9_]{3,31})\s*\/\s*(\d+)/);
  if (!m) return null;
  return { username: m[1].toLowerCase(), postId: m[2] || '' };
}

/** تعداد پست درخواستی: «۵ پست» / «آخرین 5 تا» / last 5 */
function parsePostLimit(text) {
  var t = (typeof toEnDigits === 'function' ? toEnDigits(text) : String(text || '')).toLowerCase();
  var m = t.match(/(?:آخرین\s*)?(\d+)\s*(?:تا\s*)?(?:پست|مطلب|پیام|عدد|posts?|messages?)/i);
  if (m) { var n = parseInt(m[1], 10); if (n >= 1 && n <= 30) return n; }
  m = t.match(/(?:last|latest)\s*(\d+)/i);
  if (m) { var n2 = parseInt(m[1], 10); if (n2 >= 1 && n2 <= 30) return n2; }
  m = t.match(/(\d+)\s*تا\b/);
  if (m && /پست|مطلب|پیام|کانال|آخرین/.test(t)) {
    var n3 = parseInt(m[1], 10);
    if (n3 >= 1 && n3 <= 30) return n3;
  }
  return 0;
}

/** پارس زمان نسبی: 30m / 1h / 2d / نیم ساعت / یک ساعت و ... */
function parseRelativeTime(text) {
  var t = (typeof toEnDigits === 'function'
    ? toEnDigits(String(text || '').toLowerCase())
    : String(text || '').toLowerCase()).trim();
  if (!t) return 30 * 60 * 1000;
  if (/نیم\s*ساعت|نیمساعت|نیمه/.test(t)) return 30 * 60 * 1000;
  if (/همین\s*الان|الان|just\s*now/.test(t)) return 15 * 60 * 1000;
  if (/امروز/.test(t) && !/\d+\s*ساعت/.test(t)) return 24 * 60 * 60 * 1000;
  if (/دیروز/.test(t)) return 48 * 60 * 60 * 1000;
  if (/این\s*هفته|هفته\s*اخیر/.test(t)) return 7 * 24 * 60 * 60 * 1000;

  var faNum = {
    'یک': 1, '۱': 1, 'دو': 2, '۲': 2, 'سه': 3, '۳': 3, 'چهار': 4, '۴': 4,
    'پنج': 5, '۵': 5, 'شش': 6, '۶': 6, 'هفت': 7, '۷': 7, 'هشت': 8, '۸': 8,
    'نه': 9, '۹': 9, 'ده': 10, '۱۰': 10, 'دوازده': 12, 'بیست': 20,
    'بیست و چهار': 24, 'بیست‌وچهار': 24
  };
  for (var fk in faNum) {
    if (t.indexOf(fk) !== -1) {
      if (/ساعت/.test(t)) return faNum[fk] * 60 * 60 * 1000;
      if (/دقیقه/.test(t)) return faNum[fk] * 60 * 1000;
      if (/روز/.test(t)) return faNum[fk] * 24 * 60 * 60 * 1000;
    }
  }

  var m = t.match(/(\d+)\s*(ساعت|دقیقه|روز|هفته|minute|min|mins|hour|hours|hr|h|day|days|d|week|weeks|w|m|s|sec)\b/i);
  if (m) {
    var n = parseInt(m[1], 10), u = m[2].toLowerCase();
    if (/ساعت|hour|hr|^h$/.test(u)) return n * 60 * 60 * 1000;
    if (/دقیقه|min/.test(u)) return n * 60 * 1000;
    if (/روز|day|^d$/.test(u)) return n * 24 * 60 * 60 * 1000;
    if (/هفته|week|^w$/.test(u)) return n * 7 * 24 * 60 * 60 * 1000;
    if (/^m$/.test(u)) return n * 60 * 1000;
    if (/^s|sec/.test(u)) return n * 1000;
  }
  return 30 * 60 * 1000;
}

function escapeHtmlChannel(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/** آخرین کانالی که کاربر درباره‌اش حرف زده */
async function rememberUserChannel(env, uid, username, title) {
  if (!env || !env.BOT_KV || !uid || !username) return;
  try {
    username = String(username).toLowerCase().replace(/^@/, '');
    await env.BOT_KV.put('lastch_' + uid, JSON.stringify({
      username: username,
      title: title || username,
      ts: Date.now()
    }), { expirationTtl: 60 * 60 * 24 * 7 });
  } catch (e) {}
}

async function getLastUserChannel(env, uid) {
  if (!env || !env.BOT_KV || !uid) return null;
  try {
    var j = await env.BOT_KV.get('lastch_' + uid, 'json');
    if (j && j.username) return j;
  } catch (e) {}
  return null;
}

/* ---- ذخیره‌ی پست‌های کانال/گروهی که ربات واقعاً عضوشه (مسیر ۱۰۰٪ قابل‌اعتماد) ---- */
async function storeChannelPost(env, post) {
  if (!env || !env.BOT_KV || !post) return;
  try {
    var chat = post.chat || {};
    var uname = String(chat.username || '').toLowerCase().replace(/^@/, '');
    var cid = String(chat.id || '');
    if (!uname && !cid) return;

    var keyId = uname || ('id' + cid.replace(/^-100/, '').replace(/[^0-9-]/g, ''));
    var key = 'chposts_' + keyId;
    var list = (await env.BOT_KV.get(key, 'json')) || [];
    if (!Array.isArray(list)) list = [];

    var text = String(post.text || post.caption || '').trim();
    var media = '';
    if (post.video || post.video_note) media = 'video';
    else if (post.photo) media = 'photo';
    else if (post.document) media = 'document';
    else if (post.audio || post.voice) media = 'audio';
    else if (post.poll) media = 'poll';

    var entry = {
      id: String(post.message_id || ''),
      text: text.slice(0, 3500),
      dateTs: (post.date ? post.date * 1000 : Date.now()),
      date: post.date ? new Date(post.date * 1000).toISOString() : '',
      views: post.views ? String(post.views) : '',
      link: uname ? ('https://t.me/' + uname + '/' + post.message_id) : '',
      media: media,
      chatId: cid,
      username: uname,
      title: chat.title || uname || cid
    };

    list = list.filter(function (x) { return String(x.id) !== entry.id; });
    list.unshift(entry);
    if (list.length > 80) list = list.slice(0, 80);

    await env.BOT_KV.put(key, JSON.stringify(list), { expirationTtl: 60 * 60 * 24 * 21 });
    if (uname) {
      await env.BOT_KV.put('chmap_' + uname, JSON.stringify({
        id: cid,
        title: entry.title,
        ts: Date.now()
      }), { expirationTtl: 60 * 60 * 24 * 60 });
    }
  } catch (e) {}
}

async function loadStoredChannelPosts(env, username) {
  if (!env || !env.BOT_KV) return [];
  username = String(username || '').toLowerCase().replace(/^@/, '');
  if (!username) return [];
  try {
    var list = (await env.BOT_KV.get('chposts_' + username, 'json')) || [];
    if (Array.isArray(list) && list.length) return list;

    var map = await env.BOT_KV.get('chmap_' + username, 'json');
    if (map && map.id) {
      var kid = 'id' + String(map.id).replace(/^-100/, '').replace(/[^0-9-]/g, '');
      list = (await env.BOT_KV.get('chposts_' + kid, 'json')) || [];
      if (Array.isArray(list) && list.length) return list;
    }
  } catch (e) {}
  return [];
}

/* ---- پیش‌نمایش عمومی t.me/s/username (فقط کانال‌های عمومی) ---- */
async function fetchPublicChannelPosts(username, maxPosts) {
  maxPosts = maxPosts || 20;
  username = String(username || '').replace(/^@/, '').toLowerCase().trim();
  if (!username) return { ok: false, error: 'نام کانال مشخص نیست' };

  var url = 'https://t.me/s/' + encodeURIComponent(username);
  var html = '';
  try {
    var r = await fetchT(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'en-US,en;q=0.9,fa;q=0.8'
      }
    }, 10000);
    if (!r || !r.ok) {
      return { ok: false, error: 'کانال پیدا نشد یا خصوصی است (کد ' + (r ? r.status : 0) + ')' };
    }
    html = await r.text();
  } catch (e) {
    return { ok: false, error: 'خطا در دریافت صفحه: ' + (e.message || e) };
  }

  if (!html || html.length < 500) {
    return { ok: false, error: 'صفحه کانال خالی یا غیرقابل دسترس است' };
  }
  if (/not found|صفحه پیدا نشد|does not exist/i.test(html) && html.indexOf('data-post=') === -1) {
    return { ok: false, error: 'کانال «@' + username + '» پیدا نشد (ممکن است خصوصی یا گروه باشد)' };
  }

  var title = username;
  var titleMatch = html.match(/og:title"\s*content="([^"]+)"/i) || html.match(/<title>([^<]+)<\/title>/i);
  if (titleMatch) {
    title = titleMatch[1].replace(/\s*[–—-]\s*Telegram\s*$/i, '').trim() || username;
  }

  var posts = [];
  var rePost = /data-post="([^"]+?)\/(\d+)"/gi;
  var matches = [], m;
  while ((m = rePost.exec(html)) !== null) {
    matches.push({ id: m[2], index: m.index });
  }

  for (var i = 0; i < matches.length && posts.length < maxPosts; i++) {
    var start = matches[i].index;
    var end = (i + 1 < matches.length) ? matches[i + 1].index : Math.min(start + 6000, html.length);
    var block = html.slice(start, end);
    var msgId = matches[i].id;

    var mediaType = '';
    if (/tgme_widget_message_video/i.test(block)) mediaType = 'video';
    else if (/tgme_widget_message_photo/i.test(block)) mediaType = 'photo';
    else if (/tgme_widget_message_document/i.test(block)) mediaType = 'document';
    else if (/tgme_widget_message_poll/i.test(block)) mediaType = 'poll';

    var text = '';
    var textOpen = block.match(/class="tgme_widget_message_text[^"]*"[^>]*>/i);
    if (!textOpen) textOpen = block.match(/class="tgme_widget_message_caption[^"]*"[^>]*>/i);
    if (textOpen) {
      var restTxt = block.slice(block.indexOf(textOpen[0]) + textOpen[0].length);
      var cut = restTxt.search(/<div class="tgme_widget_message_(footer|info|reactions|views|date|link|buttons|forwarded)/i);
      if (cut < 0) cut = restTxt.search(/<span class="tgme_widget_message_meta/i);
      if (cut < 0) cut = Math.min(restTxt.length, 4000);
      text = restTxt.slice(0, cut);
    }

    if (text) {
      text = text
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/?a[^>]*>/gi, '')
        .replace(/<[^>]+>/g, ' ')
        .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&nbsp;/g, ' ').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
        .replace(/&#\d+;/g, '')
        .replace(/[ \t]+/g, ' ')
        .replace(/\s*\n\s*/g, '\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    }

    if (!text) {
      if (mediaType === 'video') text = '🎬 [ویدیو]';
      else if (mediaType === 'photo') text = '🖼 [عکس]';
      else if (mediaType === 'document') text = '📎 [فایل]';
      else if (mediaType === 'poll') text = '📊 [نظرسنجی]';
    }

    var dateStr = '', dateTs = 0;
    var dateMatch = block.match(/datetime="([^"]+)"/i);
    if (dateMatch) {
      dateStr = dateMatch[1];
      dateTs = Date.parse(dateStr) || 0;
    }

    var views = '';
    var viewsMatch = block.match(/class="tgme_widget_message_views"[^>]*>([^<]+)/i);
    if (viewsMatch) views = viewsMatch[1].trim();

    posts.push({
      id: msgId,
      text: String(text || '').slice(0, 3500),
      date: dateStr,
      dateTs: dateTs,
      views: views,
      link: 'https://t.me/' + username + '/' + msgId,
      media: mediaType || ''
    });
  }

  posts.sort(function (a, b) {
    return (b.dateTs || 0) - (a.dateTs || 0) ||
           (parseInt(b.id, 10) || 0) - (parseInt(a.id, 10) || 0);
  });

  if (!posts.length) {
    return { ok: false, error: 'پیش‌نمایش عمومی خالی است (احتمالاً گروه یا خصوصی است)' };
  }

  return {
    ok: true,
    channel: username,
    title: title,
    posts: posts,
    fetchedAt: Date.now()
  };
}

/** خواندن یک پست مشخص از صفحه عمومی t.me/username/id */
async function fetchSingleTelegramPost(username, postId) {
  username = String(username || '').replace(/^@/, '').toLowerCase();
  postId = String(postId || '').replace(/\D/g, '');
  if (!username || !postId) return null;

  var url = 'https://t.me/' + encodeURIComponent(username) + '/' + postId + '?embed=1&mode=tme';
  var html = '';
  try {
    var r = await fetchT(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept-Language': 'fa,en;q=0.9'
      }
    }, 8000);
    if (r && r.ok) html = await r.text();
  } catch (e) {}

  if (!html || html.length < 200) return null;

  var text = '';
  var m = html.match(/class="tgme_widget_message_text[^"]*"[^>]*>([\s\S]*?)<\/div>/i);
  if (m) text = m[1];
  if (!text) {
    m = html.match(/class="tgme_widget_message_caption[^"]*"[^>]*>([\s\S]*?)<\/div>/i);
    if (m) text = m[1];
  }
  if (!text) {
    m = html.match(/og:description"\s*content="([^"]*)"/i);
    if (m) text = m[1];
  }

  if (text) {
    text = text
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"')
      .replace(/&#(\d+);/g, function (_, n) {
        try { return String.fromCharCode(+n); } catch (e) { return ''; }
      })
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .replace(/[ \t]{2,}/g, ' ')
      .trim();
  }

  var title = '';
  var tm = html.match(/og:title"\s*content="([^"]+)"/i);
  if (tm) title = tm[1].replace(/\s*[–—-]\s*Telegram\s*$/i, '').trim();

  var dateStr = '', dateTs = 0;
  var dm = html.match(/datetime="([^"]+)"/i);
  if (dm) {
    dateStr = dm[1];
    dateTs = Date.parse(dateStr) || 0;
  }

  if (!text || text.length < 2) return null;
  if (/ارائه‌دهنده سرویس‌های پیشرفته مبتنی بر Cloudflare/i.test(text) && text.length < 200) return null;

  return {
    id: postId,
    text: text.slice(0, 3500),
    date: dateStr,
    dateTs: dateTs,
    views: '',
    link: 'https://t.me/' + username + '/' + postId,
    media: '',
    title: title
  };
}

/**
 * خواندن چند پست آخر با شروع از یک postId شناخته‌شده
 * نسخه‌ی سبک‌شده با سقف سخت روی تعداد درخواست‌ها (جلوگیری از سقف subrequest)
 */
async function fetchRecentByPostIds(username, startId, count) {
  username = String(username || '').replace(/^@/, '').toLowerCase();
  startId = parseInt(String(startId || '0').replace(/\D/g, ''), 10) || 0;
  count = Math.min(Math.max(count || 5, 1), 8);
  if (!username || startId < 1) return { ok: false, posts: [] };

  async function exists(id) {
    if (id < 1) return null;
    try {
      var p = await fetchSingleTelegramPost(username, String(id));
      return (p && p.text) ? p : null;
    } catch (e) { return null; }
  }

  // فقط یک موج پروب کوچک — جلو و عقب از نقطه‌ی شروع
  var probeIds = [startId, startId + 1, startId + 2, startId + 3, startId - 1];
  var hits = await Promise.all(probeIds.map(exists));

  var maxId = startId;
  for (var i = 0; i < hits.length; i++) {
    if (hits[i] && hits[i].text) {
      var idNum = parseInt(hits[i].id, 10);
      if (idNum > maxId) maxId = idNum;
    }
  }

  var ids = [];
  for (var n = 0; n < count; n++) {
    var id = maxId - n;
    if (id >= 1) ids.push(id);
  }

  var finalHits = await Promise.all(ids.map(exists));
  var posts = [];
  finalHits.forEach(function (p) {
    if (p && p.text) posts.push(p);
  });

  posts.sort(function (a, b) {
    return (parseInt(b.id, 10) || 0) - (parseInt(a.id, 10) || 0);
  });

  if (!posts.length) return { ok: false, posts: [] };

  return {
    ok: true,
    channel: username,
    title: (posts[0] && posts[0].title) || username,
    posts: posts,
    fetchedAt: Date.now(),
    via: 'post-ids',
    maxId: maxId
  };
}

/** تشخیص intent سخت‌گیرتر — فقط وقتی لینک/منشن تلگرام واقعاً در متن هست */
function isChannelReadIntent(text) {
  var t = String(text || '');
  if (/^\/(channel|chan|کانال|کانال‌خوان|channelread)\b/i.test(t.trim())) return true;

  var hasTgLink = /(?:https?:\/\/)?(?:t\.me|telegram\.me)\//i.test(t);
  var hasAt = /@[a-zA-Z][a-zA-Z0-9_]{3,31}\b/.test(t);
  if (!hasTgLink && !hasAt) return false;

  return /آخرین|پست|مطلب|خبر|بخون|بخوان|بفرست|نشان\s*بده|چی\s*گفت|چی\s*نوشت|پیام/i.test(t) ||
         t.trim().length < 70;
}

/** follow-up فقط وقتی مجاز است که کاربر همین اواخر (کمتر از ۱۰ دقیقه) کانالی مطرح کرده */
async function isChannelFollowUp(env, uid, text) {
  var t = String(text || '');
  var wantsMore = /آخرین\s*\d*\s*(مطلب|پست|پیام)|^\s*\d+\s*(تا\s*)?(پست|مطلب)\b|پست\s*(های)?\s*\d+\s*ساعت|چه\s*(مطلب|پست)\s*(جدید)?|موضوعش\s*چ(ه|ی)/i.test(t);
  if (!wantsMore) return null;

  try {
    var last = await getLastUserChannel(env, uid);
    if (last && last.username && (Date.now() - (last.ts || 0)) < 10 * 60 * 1000) {
      return last.username;
    }
  } catch (e) {}
  return null;
}

/** استخراج موضوع جستجو از متن کاربر (بدون نام کانال و زمان) */
function extractChannelTopic(raw, username) {
  var s = String(raw || '');
  s = s.replace(new RegExp('@?' + (username || ''), 'ig'), ' ');
  s = s.replace(/(?:https?:\/\/)?(?:t\.me|telegram\.me)\/\S+/gi, ' ');
  s = s.replace(/\/(channel|chan|کانال)\b/ig, ' ');
  s = s.replace(/\d+\s*(ساعت|دقیقه|روز|پست|مطلب|تا|h|m|d)\b/gi, ' ');
  s = s.replace(/آخرین|بفرست|بده|بخون|بخوان|نشان\s*بده|پیدا\s*کن|چه\s*(مطلب|پست|موضوع)|موضوع|ارسالی|کانال|گروه|پیش|اخیر|امروز|دیروز/gi, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  if (s.length < 2 || s.length > 80) return '';
  return s;
}

/**
 * تابع اصلی — نسخه‌ی نهایی:
 * ۱) پیش‌نمایش عمومی t.me/s (فقط کانال، سریع)
 * ۲) پست‌های ذخیره‌شده از عضویت واقعی ربات (مسیر قابل‌اعتماد برای گروه+کانال خصوصی)
 * ۳) اگر لینک یک پیام مشخص داده شده، از همان‌جا با سقف کم به عقب بخوان
 * با دِدلاین زمانی سخت و پیام خطای دقیق.
 */
async function novaToolChannel(env, chatId, uid, raw) {
  var s = String(raw || '').trim();
  var postRef = parseTelegramPostRef(s);
  var seedPostId = (postRef && postRef.postId) ? postRef.postId : '';
  var username = parseChannelUsername(s) || (postRef && postRef.username) || '';

  if (!username) {
    var fu = await isChannelFollowUp(env, uid, s);
    if (fu) username = fu;
  }
  if (!username) {
    var last = await getLastUserChannel(env, uid);
    if (last && last.username && /کانال|گروه/.test(s)) username = last.username;
  }

  if (!username) {
    return '📢 خواندن کانال/گروه تلگرام\n\n' +
      'اول لینک یا @نام کانال را بفرست، بعد بپرس:\n' +
      '• آخرین ۵ پست\n' +
      '• پست‌های ۲۴ ساعت\n\n' +
      '✅ کانال عمومی: خودکار کار می‌کند\n' +
      '✅ گروه یا کانال خصوصی: ربات را عضو کنید، یا لینک یک پیام مشخص بفرستید (مثلاً t.me/name/123)';
  }

  try { await rememberUserChannel(env, uid, username); } catch (e) {}

  var deadline = Date.now() + 18000; // سقف سخت — قبل از رسیدن به watchdog خارجی
  var diag = [];

  // اگر لینک پست مشخص بود، اول خود همان پست را بخوان (سریع و قطعی)
  if (seedPostId) {
    try {
      var one = await fetchSingleTelegramPost(username, seedPostId);
      if (one && one.text) {
        var linesOne = [
          '📢 <b>@' + escapeHtmlChannel(username) + '</b>' +
            (one.title ? (' — ' + escapeHtmlChannel(one.title)) : ''),
          '🔗 پست #' + seedPostId,
          '────────────',
          escapeHtmlChannel(one.text),
          '',
          '🔗 ' + one.link,
          '────────────',
          'پست‌های بیشتر: /channel @' + username + ' 5 پست'
        ];
        return {
          ok: true,
          text: linesOne.join('\n'),
          parse_mode: 'HTML',
          disable_web_page_preview: true
        };
      }
      diag.push('پست #' + seedPostId + ' قابل خواندن نبود');
    } catch (e) {
      diag.push('خواندن پست مشخص: ' + (e.message || e));
    }
  }

  // مرحله ۱: پیش‌نمایش عمومی (فقط کانال‌ها جواب می‌دهند)
  var data = null;
  try {
    data = await fetchPublicChannelPosts(username, 15);
    if (!data.ok) diag.push('پیش‌نمایش عمومی: ' + data.error);
  } catch (e) {
    diag.push('پیش‌نمایش عمومی: ' + (e.message || e));
  }

  // مرحله ۲: پست‌های ذخیره‌شده از عضویت واقعی ربات
  var stored = [];
  try { stored = await loadStoredChannelPosts(env, username); } catch (e) {}
  if (!stored.length) {
    diag.push('ربات عضو این گروه/کانال نیست (یا هنوز پیامی در آن رد و بدل نشده)');
  }

  // مرحله ۳: اگر لینک پیام مشخص داشتیم ولی بالا جواب نگرفتیم، با سقف کم عقب بخوان
  var walked = null;
  if ((!data || !data.ok) && !stored.length && seedPostId && Date.now() < deadline - 4000) {
    try {
      walked = await fetchRecentByPostIds(username, seedPostId, 5);
      if (!walked.ok) diag.push('خواندن پست‌های اطراف: ناموفق');
    } catch (e) {
      diag.push('خواندن پست‌های اطراف: ' + (e.message || e));
    }
  } else if ((!data || !data.ok) && !stored.length && !seedPostId) {
    diag.push('بدون لینک پیام مشخص، گروه بدون عضویت ربات قابل خواندن نیست');
  }

  var merged = [];
  var seen = {};
  function add(p) {
    if (!p) return;
    var k = String(p.id || p.text || '').slice(0, 40);
    if (seen[k]) return;
    seen[k] = 1;
    merged.push(p);
  }

  if (data && data.ok) data.posts.forEach(add);
  if (walked && walked.ok) walked.posts.forEach(add);
  stored.forEach(add);

  if (!merged.length) {
    return '❌ برای @' + username + ' چیزی پیدا نشد.\n\n' +
      'دلایل بررسی‌شده:\n• ' + diag.join('\n• ') + '\n\n' +
      '✅ راه‌حل مطمئن:\n' +
      '۱) ربات را به گروه/کانال اضافه کن (ترجیحاً ادمین)\n' +
      '۲) چند پیام جدید در آن رد و بدل شود\n' +
      '۳) یا همین الان یک لینک پیام مشخص بفرست: t.me/' + username + '/123';
  }

  merged.sort(function (a, b) {
    var ta = a.dateTs || 0, tb = b.dateTs || 0;
    if (tb !== ta) return tb - ta;
    return (parseInt(b.id, 10) || 0) - (parseInt(a.id, 10) || 0);
  });

  var postLimit = parsePostLimit(s) || 10;
  var timePart = s.replace(new RegExp('@?' + username, 'i'), '').trim();
  var hasExplicitTime = /\d+\s*(ساعت|دقیقه|روز|h\b|hour|min)|نیم\s*ساعت|یک\s*ساعت|امروز|۲۴\s*ساعت|24\s*ساعت/i.test(timePart);

  var windowLabel, recent;
  if (hasExplicitTime) {
    var windowMs = parseRelativeTime(timePart);
    var since = Date.now() - windowMs;
    recent = merged.filter(function (p) {
      return !p.dateTs || p.dateTs >= since;
    }).slice(0, postLimit);
    if (!recent.length) recent = merged.slice(0, postLimit);
    windowLabel = windowMs <= 90 * 60 * 1000
      ? Math.round(windowMs / 60000) + ' دقیقه اخیر'
      : Math.round(windowMs / 3600000) + ' ساعت اخیر';
  } else {
    recent = merged.slice(0, postLimit);
    windowLabel = 'آخرین ' + recent.length + ' پست';
  }

  var title = (data && data.title && data.title !== username)
    ? (data.title + ' (@' + username + ')')
    : ('@' + username);

  var sourceNote = stored.length && (!data || !data.ok)
    ? ' · عضویت ربات'
    : (walked && walked.ok ? ' · لینک پیام' : ' · پیش‌نمایش عمومی');

  var lines = [
    '📢 <b>' + escapeHtmlChannel(title) + '</b>',
    '⏱ ' + windowLabel + sourceNote,
    '────────────'
  ];

  recent.forEach(function (p, idx) {
    var header = (idx + 1) + '. ';
    if (p.date) {
      try {
        var d = new Date(p.date);
        if (!isNaN(d.getTime())) {
          header += '🕐 ' + d.toLocaleString('fa-IR', {
            timeZone: 'Asia/Tehran',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
          }) + ' ';
        }
      } catch (e) {}
    }
    lines.push(header.trim());
    if (p.text) {
      lines.push(escapeHtmlChannel(p.text.length > 900 ? p.text.slice(0, 900) + '…' : p.text));
    }
    if (p.link) lines.push('🔗 ' + p.link);
    lines.push('');
  });

  lines.push('────────────');
  lines.push('🔄 تازه‌سازی: /channel @' + username);

  return {
    ok: true,
    text: lines.join('\n'),
    parse_mode: 'HTML',
    disable_web_page_preview: true
  };
}


/* ============================================================================
 * بلوک جایگزین داخل novaMaybeHandle
 * بلوک follow-up قدیمی را با این عوض کن:
 * ==========================================================================
 *
 *   // ---------- 📢 خواندن کانال (دستور + لینک صریح + follow-up کوتاه‌مدت) ----------
 *   var chIntent = isChannelReadIntent(t);
 *   if (!chIntent && env && uid) {
 *     var fuCh = await isChannelFollowUp(env, uid, t);
 *     if (fuCh) chIntent = true;
 *   }
 *   if (chIntent) {
 *     try { await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' }); } catch (e) {}
 *     var chRes = await novaToolChannel(env, chatId, uid, t);
 *     var userAskedFa = /[\u0600-\u06FF]/.test(t);
 *
 *     if (typeof chRes === 'string') {
 *       var msg1 = chRes;
 *       if (userAskedFa) {
 *         try { msg1 = await translateChannelOutputToFa(env, chRes); } catch (e) {}
 *       }
 *       await tgReply(env, chatId, msg1);
 *     } else if (chRes && chRes.ok) {
 *       var msg2 = chRes.text;
 *       if (userAskedFa) {
 *         try { msg2 = await translateChannelOutputToFa(env, chRes.text); } catch (e) {}
 *       }
 *       await tgSendSafe(env, 'sendMessage', {
 *         chat_id: chatId,
 *         text: msg2,
 *         parse_mode: chRes.parse_mode || 'HTML',
 *         disable_web_page_preview: true
 *       });
 *     } else {
 *       await tgReply(env, chatId, '❌ خطا در خواندن کانال');
 *     }
 *     return true;
 *   }
 *
 * ==========================================================================
 *
 * نکته مهم برای گروه‌ها:
 * در مسیر webhook (وقتی پیام از گروه/کانال می‌آید) حتماً این را صدا بزن:
 *
 *   if (msg.chat && (msg.chat.type === 'channel' || msg.chat.type === 'supergroup' || msg.chat.type === 'group')) {
 *     try { await storeChannelPost(env, msg); } catch (e) {}
 *   }
 *
 * بدون این خط، مسیر «عضویت ربات» هیچ‌وقت پر نمی‌شود.
 * ========================================================================== */

/* ---- ترجمه خروجی کانال به فارسی (حفظ‌شده از نسخه قبلی) ---- */
function needsFaTranslation(text) {
  var s = String(text || '');
  var fa = (s.match(/[\u0600-\u06FF]/g) || []).length;
  var en = (s.match(/[A-Za-z]/g) || []).length;
  if (en < 25) return false;
  // اگر انگلیسی/غیرفارسی بیشتر از فارسی باشد
  return en > fa * 1.2;
}

/** ترجمه خروجی کانال به فارسی */
async function translateChannelOutputToFa(env, text) {
  text = String(text || '').trim();
  if (!text || !needsFaTranslation(text)) return text;

  // 1) think (مدل اصلی)
  try {
    if (typeof think === 'function') {
      var tr = await think(env, [
        {
          role: 'system',
          content: 'تو مترجم فارسی هستی. پست‌های کانال تلگرام را به فارسی روان ترجمه کن. ساختار شماره‌ها، ایموجی‌ها و لینک‌ها را حفظ کن. فقط متن ترجمه‌شده بده، بدون توضیح اضافه.'
        },
        { role: 'user', content: text.slice(0, 3500) }
      ], { maxTokens: 1800 });
      if (tr && tr.text && String(tr.text).trim().length > 30) {
        return String(tr.text).trim();
      }
    }
  } catch (e1) {}

  // 2) خط‌به‌خط با CF Translate
  if (env && env.AI) {
    try {
      var lines = text.split(/\n/);
      var out = [];
      for (var i = 0; i < lines.length && i < 40; i++) {
        var line = lines[i];
        var plain = line.replace(/<[^>]+>/g, '').trim();
        if (!plain || plain.length < 3) { out.push(line); continue; }
        // هدر/لینک/جداکننده را دست نزن
        if (/^https?:\/\//i.test(plain) || /^🔗/.test(plain) || /^─+/.test(plain) || /^📢/.test(plain) || /^⏱/.test(plain)) {
          out.push(line);
          continue;
        }
        // اگر خط فارسی است و انگلیسی کمی دارد
        var fa = (plain.match(/[\u0600-\u06FF]/g) || []).length;
        var en = (plain.match(/[A-Za-z]/g) || []).length;
        if (en < 8 || fa > en) { out.push(line); continue; }
        try {
          var r = await env.AI.run(CF_TRANSLATE, {
            text: plain.slice(0, 450),
            source_lang: 'en',
            target_lang: 'fa'
          });
          if (r && r.translated_text) {
            // اگر خط با شماره شروع شده شماره را نگه دار
            var num = plain.match(/^(\d+\.\s*)/);
            out.push((num ? num[1] : '') + r.translated_text);
          } else out.push(line);
        } catch (eL) { out.push(line); }
      }
      return out.join('\n');
    } catch (e2) {}
  }
  return text;
}



async function novaMaybeHandle(env, uid, chatId, text, name) {
  text = String(text || '');
  var t = text.trim();
  var low = t.toLowerCase();

  /* ---------- راهنمای گروه ---------- */
  if (/^\/(grouphelp|راهنماگروه|عضویت\s*گروه)\b/i.test(t) || /چطور\s*ربات\s*را\s*(به\s*)?گروه/.test(t)) {
    await tgReply(env, chatId,
      '👥 خواندن گروه در تلگرام\n\n' +
      'تلگرام تاریخچهٔ گروه را بدون عضویت نمی‌دهد.\n' +
      'برای اینکه ربات پست‌های یک گروه را بخواند:\n\n' +
      '۱) ربات را به گروه اضافه کن\n' +
      '۲) ترجیحاً ادمین کن (برای دیدن همه پیام‌ها)\n' +
      '۳) از آن لحظه پیام‌های جدید ذخیره می‌شوند\n' +
      '۴) در چت خصوصی بگو:\n' +
      '   /channel @username_group 5 پست\n\n' +
      '📌 لینک یک پیام مشخص:\n' +
      '   آخرین مطلب t.me/name/123\n' +
      '   (گاهی بدون عضویت هم همان یک پیام خوانده می‌شود)\n\n' +
      '📢 کانال عمومی نیاز به عضویت ندارد.'
    );
    return true;
  }

  /* ---------- 📢 فقط لینک کانال فرستاده → ذخیره برای سوال بعدی ---------- */
  if (typeof parseChannelUsername === 'function') {
    var onlyLink = t.match(/^(?:https?:\/\/)?(?:t\.me|telegram\.me)\/([a-zA-Z][a-zA-Z0-9_]{3,31})\/?$/i);
    var onlyAt = t.match(/^@([a-zA-Z][a-zA-Z0-9_]{3,31})$/);
    var sharedCh = onlyLink ? onlyLink[1].toLowerCase() : (onlyAt ? onlyAt[1].toLowerCase() : parseChannelUsername(t));
    // پیام کوتاه فقط لینک/منشن کانال
    if (sharedCh && t.length < 80 && !isChannelReadIntent(t)) {
      try { await rememberUserChannel(env, uid, sharedCh); } catch (e0) {}
      // اگر فقط لینک بود، پیشنهاد بده
      if (onlyLink || onlyAt || /^https?:\/\/t\.me\//i.test(t)) {
        await tgReply(env, chatId,
          '✅ کانال @' + sharedCh + ' ذخیره شد.\n\n' +
          'حالا بپرس مثلاً:\n' +
          '• آخرین مطلب کانال\n' +
          '• ۵ پست آخر\n' +
          '• پست‌های ۲۴ ساعت\n' +
          '• /channel @' + sharedCh + ' 5 پست');
        return true;
      }
    }
  }

  /* ---------- 📢 خواندن کانال (دستور + لینک صریح + follow-up کوتاه‌مدت) ---------- */
  var chIntent = (typeof isChannelReadIntent === 'function' && isChannelReadIntent(t));
  if (!chIntent && env && uid && typeof isChannelFollowUp === 'function') {
    try {
      var fuCh = await isChannelFollowUp(env, uid, t);
      if (fuCh) chIntent = true;
    } catch (eFu) {}
  }
  if (chIntent) {
    try { await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' }); } catch (e) {}
    var chRes = await novaToolChannel(env, chatId, uid, t);
    var userAskedFa = /[\u0600-\u06FF]/.test(t);
    if (typeof chRes === 'string') {
      var msg1 = chRes;
      if (userAskedFa) {
        try { msg1 = await translateChannelOutputToFa(env, chRes); } catch (eTr1) {}
      }
      await tgReply(env, chatId, msg1);
      try {
        if (env.BOT_KV) await env.BOT_KV.put('lastchres_' + uid, JSON.stringify({ text: msg1, ts: Date.now() }), { expirationTtl: 3600 });
      } catch (eS1) {}
    } else if (chRes && chRes.ok) {
      var msg2 = chRes.text;
      if (userAskedFa) {
        try { msg2 = await translateChannelOutputToFa(env, chRes.text); } catch (eTr2) {}
      }
      await tgSendSafe(env, 'sendMessage', {
        chat_id: chatId,
        text: msg2,
        parse_mode: chRes.parse_mode || 'HTML',
        disable_web_page_preview: true
      });
      try {
        if (env.BOT_KV) await env.BOT_KV.put('lastchres_' + uid, JSON.stringify({ text: msg2, ts: Date.now() }), { expirationTtl: 3600 });
      } catch (eS2) {}
    } else {
      await tgReply(env, chatId, '❌ خطا در خواندن کانال');
    }
    return true;
  }

  /* ---------- ترجمه/خلاصه فارسیِ آخرین نتیجه کانال ---------- */
  if (/^(فارسی\s*بگو|به\s*فارسی|ترجمه\s*کن|ترجمه‌?اش\s*کن|خلاصه\s*فارسی|فارسی\s*کن|بگو\s*فارسی)/i.test(t.trim()) ||
      (/فارسی/.test(t) && /بگو|ترجمه|خلاصه|کن/.test(t) && t.length < 40)) {
    try {
      var lastRes = env.BOT_KV ? await env.BOT_KV.get('lastchres_' + uid, 'json') : null;
      if (lastRes && lastRes.text && (Date.now() - (lastRes.ts || 0)) < 3600000) {
        try { await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' }); } catch (eT) {}
        var src = String(lastRes.text)
          .replace(/<[^>]+>/g, ' ')
          .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
          .replace(/🔗\s*https?:\/\/\S+/g, '')
          .replace(/────────────/g, '\n')
          .replace(/[ \t]+\n/g, '\n')
          .replace(/\n{3,}/g, '\n\n')
          .trim()
          .slice(0, 3200);
        var out = '';
        // 1) مدل اصلی ربات
        try {
          if (typeof think === 'function') {
            var tr = await think(env, [
              { role: 'system', content: 'تو یک مترجم حرفه‌ای به فارسی هستی. متن پست‌های کانال را به فارسی روان ترجمه یا خلاصه کن. شماره پست‌ها را نگه دار. فقط فارسی بنویس.' },
              { role: 'user', content: src }
            ], { maxTokens: 1500 });
            if (tr && tr.text) out = String(tr.text).trim();
          }
        } catch (eThink) {}
        // 2) ترجمه خط‌به‌خط با CF Translate
        if (!out && env.AI) {
          try {
            var lines = src.split(/\n/).filter(function (l) { return l.trim().length > 2; }).slice(0, 12);
            var faLines = [];
            for (var li = 0; li < lines.length; li++) {
              var line = lines[li].trim();
              if (/^[\d\.\)\s🕐👁📢⏱─]+$/.test(line) || line.length < 4) {
                faLines.push(line);
                continue;
              }
              // اگر خودش فارسی است نگه دار
              if (/[\u0600-\u06FF]/.test(line) && !/[a-zA-Z]{4,}/.test(line)) {
                faLines.push(line);
                continue;
              }
              try {
                var tr2 = await env.AI.run(CF_TRANSLATE, {
                  text: line.slice(0, 450),
                  source_lang: 'en',
                  target_lang: 'fa'
                });
                faLines.push((tr2 && tr2.translated_text) ? tr2.translated_text : line);
              } catch (eLine) {
                faLines.push(line);
              }
            }
            out = faLines.join('\n');
          } catch (eCf) {}
        }
        if (out) {
          await tgReply(env, chatId, '🌐 ترجمه فارسی آخرین پست‌های کانال:\n\n' + out.slice(0, 4000));
          return true;
        }
        await tgReply(env, chatId, '❌ ترجمه انجام نشد. یک‌بار دیگر /channel را بزن و بعد بگو «فارسی بگو».');
        return true;
      } else {
        await tgReply(env, chatId, 'هنوز پست کانالی در حافظه نیست.\nاول بنویس مثلاً:\nآخرین مطلب کانال @keygen_channel\nبعد بگو: فارسی بگو');
        return true;
      }
    } catch (eF) {}
  }


  /* ---------- 🔗 خلاصه لینک ---------- */
  if (/^\/(link|summarize|summarise|خلاصه|خلاصه‌لینک|خلاصه\s*لینک)\b/i.test(t) ||
      /^https?:\/\//i.test(t) || /^(لینک|این سایت را خلاصه|این لینک)\b/i.test(t)) {
    var url = extractFirstUrl(t);
    if (!url && /^\/(link|summarize|summarise|خلاصه|خلاصه‌لینک)/i.test(t)) url = t.replace(/^\/\S+\s*/, '').trim();
    if (!url) return false;

    try { await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' }); } catch (e) {}
    var r = await novaToolLinkSummary(env, chatId, url);
    await tgReply(env, chatId, r.ok ? r.text : ('❌ ' + r.error));
    return true;
  }

  /* ---------- 🔳 QR ---------- */
  if (/^\/(qr|qrcode|بارکد)\b/i.test(t)) {
    var payload = t.replace(/^\/\S+\s*/, '').trim();
    if (!payload) { await tgReply(env, chatId, '🔳 نمونه: /qr https://example.com یا /qr متن دلخواه'); return true; }
    var q = await novaToolQr(env, chatId, payload);
    if (!q.ok) { await tgReply(env, chatId, '❌ ' + q.error); return true; }
    try {
      var fd = new FormData();
      fd.append('chat_id', String(chatId));
      fd.append('photo', new Blob([q.image], { type: q.mime }), 'qr.png');
      fd.append('caption', q.caption);
      await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendPhoto', { method: 'POST', body: fd });
    } catch (e2) {
      await tgReply(env, chatId, q.caption);
    }
    return true;
  }


  /* ---------- ⏰ یادآور ---------- */
  if (/^\/(remind|alarm|یادآور|یاداور)\b/i.test(t)) {
    var rc = parseRemindCommand(t);
    if (rc && rc.error) { await tgReply(env, chatId, '❌ ' + rc.error); return true; }
    if (rc && rc.at) {
      if (!env.BOT_KV) { await tgReply(env, chatId, '❌ KV تنظیم نشده — یادآور نیاز به BOT_KV دارد.'); return true; }
      if (rc.at - Date.now() < 20000) { await tgReply(env, chatId, '⏰ زمان باید حداقل ۲۰ ثانیه دیگر باشد.'); return true; }
      await remindAdd(env, uid, rc.at, rc.text, chatId);
      await tgReply(env, chatId,
        '⏰ یادآور ثبت شد\n\n🔔 ' + rc.text + '\n📅 ' + fmtWhenFa(rc.at) +
        '\n⏳ ' + fmtDelta(rc.at - Date.now()) + '\n\n🆔 ' + (await remindList(env, uid)).slice(-1)[0].id +
        '\n(لیست: /remindlist · حذف: /reminddel ID)');
      return true;
    }
    await tgReply(env, chatId, await novaToolRemindHelp(env, chatId, uid));
    return true;
  }
  if (/^\/(remindlist|یاداورها|یادآورها)\b/i.test(t)) {
    await tgReply(env, chatId, await novaToolRemindHelp(env, chatId, uid));
    return true;
  }
  if (/^\/(reminddel|delremind)\b/i.test(t)) {
    var rid = t.replace(/^\/\S+\s*/, '').trim();
    if (!rid) { await tgReply(env, chatId, 'نمونه: /reminddel ID'); return true; }
    await tgReply(env, chatId, await novaToolRemindDel(env, chatId, uid, rid));
    return true;
  }

  /* ---------- ✅ To-Do ---------- */
  if (/^\/(todo|کارها|تسک|task)\b/i.test(t)) {
    if (!env.BOT_KV) { await tgReply(env, chatId, '❌ KV تنظیم نشده.'); return true; }
    var tres = await novaToolTodo(env, chatId, uid, t);
    await tgReply(env, chatId, typeof tres === 'string' ? tres : JSON.stringify(tres));
    return true;
  }

  /* ---------- 🔄 تبدیل واحد / ارز ---------- */
  if (/^\/(convert|conv|toc|تبدیل)\b/i.test(t)) {
    var cv = await novaToolConvert(env, chatId, t);
    await tgReply(env, chatId, typeof cv === 'string' ? cv : JSON.stringify(cv));
    return true;
  }

  /* ---------- 🧠 کوییز ---------- */
  if (/^\/(quiz|کوییز|آزمون)\b/i.test(t)) {
    try { await tg(env, 'sendChatAction', { chat_id: chatId, action: 'typing' }); } catch (e) {}
    var qz = await novaToolQuiz(env, chatId, uid, t);
    if (typeof qz === 'string') await tgReply(env, chatId, qz);
    else await tgSendSafe(env, 'sendMessage', {
      chat_id: chatId, text: qz.text, parse_mode: 'HTML',
      disable_web_page_preview: true,
      reply_markup: qz.markup || undefined
    });
    return true;
  }
  if (/^\/(quizans)\b/i.test(t)) {
    var qid = t.replace(/^\/\S+\s*/, '').trim();
    await tgReply(env, chatId, await novaToolQuizAnswers(env, qid));
    return true;
  }

  /* ---------- 📈 هشدار قیمت ---------- */
  if (/^\/(alert|pricealert|هشدار)\b/i.test(t)) {
    var al = await novaToolAlertAdd(env, chatId, uid, t);
    await tgReply(env, chatId, al);
    return true;
  }
  if (/^\/(alertlist|هشدارها)\b/i.test(t)) {
    await tgReply(env, chatId, await novaToolAlertList(env, chatId, uid));
    return true;
  }
  if (/^\/(alertdel|delalert)\b/i.test(t)) {
    var aid = t.replace(/^\/\S+\s*/, '').trim();
    if (!aid) { await tgReply(env, chatId, 'نمونه: /alertdel ID'); return true; }
    await tgReply(env, chatId, await novaToolAlertDel(env, chatId, uid, aid));
    return true;
  }
  if (/^\/alertcheck\b/i.test(t)) {
    var n = await novaRunPriceAlerts(env);
    await tgReply(env, chatId, n ? ('🔔 ' + n + ' هشدار فعال شد.') : '✅ هیچ هشداری به شرط نرسید.');
    return true;
  }

  /* ---------- 🔍 جستجو در چت ---------- */
  if (/^\/(findchat|searchchat|جستجو)\b/i.test(t)) {
    await tgReply(env, chatId, await novaToolChatSearch(env, uid, chatId, t));
    return true;
  }

  /* ---------- 📤 خروجی گفتگو ---------- */
  if (/^\/(chatlog|dumpchat)\b/i.test(t)) {
    var ex = await novaToolExport(env, uid, chatId, t.replace(/^\/(chatlog|dumpchat)\s*/i, '/export '));
    if (typeof ex === 'string') await tgReply(env, chatId, ex);
    else if (ex && ex.file) {
      try {
        var fd2 = new FormData();
        fd2.append('chat_id', String(chatId));
        fd2.append('document', new Blob([ex.file.text], { type: ex.file.mime }), ex.file.name);
        await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendDocument', { method: 'POST', body: fd2 });
      } catch (e3) {
        await tgReply(env, chatId, '📤 فایل:\n\n' + ex.file.text.slice(0, 3000));
      }
    }
    return true;
  }

  /* ---------- 📊 آمار متن ---------- */
  if (/^\/(stats|wordcount|آمار|شمارش)\b/i.test(t)) {
    var body = t.replace(/^\/\S+\s*/, '').trim();
    if (!body) { await tgReply(env, chatId, '📊 نمونه: /stats متن شما اینجا'); return true; }
    var st = textStats(body);
    await tgReply(env, chatId,
      '📊 آمار متن\n\n' +
      '🔤 کلمات: ' + st.words.toLocaleString('fa-IR') + '\n' +
      '🔡 کاراکترها: ' + st.chars.toLocaleString('fa-IR') + '\n' +
      '🟢 حروف فارسی: ' + st.fa.toLocaleString('fa-IR') + '\n' +
      '🔵 حروف انگلیسی: ' + st.en.toLocaleString('fa-IR') + '\n' +
      '📍 خطوط: ' + st.lines.toLocaleString('fa-IR') + '\n' +
      '⏱ زمان مطالعه تقریبی: ' + st.readingMin + ' دقیقه');
    return true;
  }

  /* ---------- 🗺 نقشه ذهنی ---------- */
  if (/^\/(mindmap|نقشه)\b/i.test(t)) {
    var mb = t.replace(/^\/\S+\s*/, '').trim();
    if (!mb) { await tgReply(env, chatId, '🗺 نمونه: /mindmap متن شما اینجا'); return true; }
    await tgReply(env, chatId, '🗺 نقشه ذهنی:\n\n```\n' + toMindMap(mb) + '\n```');
    return true;
  }

  /* ---------- 🎲 قرعه‌کشی ---------- */
  if (/^\/(shuffle|random|قرعه|انتخاب)\b/i.test(t)) {
    var items = t.replace(/^\/\S+\s*/, '').split(/[,،\n|]+/).map(function (x) { return x.trim(); }).filter(Boolean);
    if (items.length < 2) { await tgReply(env, chatId, '🎲 نمونه: /shuffle گزینه۱، گزینه۲، گزینه۳'); return true; }
    var w = pickRandom(items, 1)[0];
    await tgReply(env, chatId, '🎲 قرعه کشی از ' + items.length + ' گزینه:\n\n👉 <b>' + escapeHtml(w) + '</b>');
    return true;
  }

  return false;
}

