var NOVA_ADV_VERSION = 'v26.19.0-adv';

function advJson(x){ try{ return JSON.stringify(x); }catch(e){ return '{}'; } }
async function advKvGet(env,k,t){ if(!env.BOT_KV) return null; try{ return await env.BOT_KV.get(k,t); }catch(e){ return null; } }
async function advKvPut(env,k,v,ttl){ if(!env.BOT_KV) return; try{ var o={}; if(ttl)o.expirationTtl=ttl; await env.BOT_KV.put(k,v,o); }catch(e){} }
async function advKvDel(env,k){ if(!env.BOT_KV) return; try{ await env.BOT_KV.delete(k); }catch(e){} }
function advId(p){ return p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }

/* 1) AGENT — Function Calling چندمرحله‌ای */
var AGENT_TOOLS = [
  {name:'هوا', desc:'آب‌وهوای یک شهر. ورودی: نام شهر'},
  {name:'قیمت', desc:'قیمت دلار/طلا/رمزارز. ورودی: موضوع مثلا دلار'},
  {name:'اخبار', desc:'اخبار اخیر. ورودی: موضوع خبر'},
  {name:'جستجو', desc:'جستجوی وب. ورودی: عبارت جستجو'},
  {name:'ترجمه', desc:'ترجمه متن. ورودی: کل متنی که باید ترجمه شود'},
  {name:'ریاضی', desc:'محاسبه ریاضی. ورودی: عبارت'},
  {name:'دانش_کاربر', desc:'دانش شخصی کاربر. ورودی: سوال'},
  {name:'پایان', desc:'هیچ ابزاری لازم نیست؛ جواب نهایی را آماده کن. ورودی: متن جواب نهایی به فارسی'}
];
var AGENT_TOOL_JSON = AGENT_TOOLS.map(function(t){return '- '+t.name+': '+t.desc;}).join('\n');
async function novaAgentStep(env, uid, question, history, scratch){
  var sys = 'تو یک عامل (Agent) هستی که با ابزارها صحبت می‌کنی. ' +
    'در هر مرحله فقط و فقط یک JSON خروجی بده: {"tool":"<نام ابزار>","input":"<ورودی>"}. ' +
    'وقتی جواب لازم است، از ابزار "پایان" استفاده کن و در input کل متن جواب نهایی را بنویس.\n' +
    'ابزارها:\n'+AGENT_TOOL_JSON+'\n' +
    'سؤال کاربر: '+question+'\n' +
    (scratch ? 'سوابق ابزارها:\n'+scratch : '') +
    '\nفقط JSON برگردان، بدون markdown.';
  var r = await think(env, [{role:'system',content:sys}].concat(history.slice(-6)).concat([{role:'user',content:question}]), {maxTokens:500, timeout:20000});
  return r && r.text ? r.text : '';
}
async function novaRunTool(env, uid, name, input){
  name = String(name||'').toLowerCase().trim();
  input = String(input||'').trim();
  try{
    if(name==='هوا'||name==='weather'){ var w = await getWeather(input, env); return w ? ('Weather: '+w) : 'no'; }
    if(name==='قیمت'||name==='price'||name==='prices'){ var p = await livePrices(input, env); return p || 'no'; }
    if(name==='اخبار'||name==='news'){ var n = await newsRSS(input, env); return typeof n==='string'?n:(n&&n.chunks?n.chunks.join('\n'):'no'); }
    if(name==='جستجو'||name==='search'){ var s = await searchWeb(input, env); return s||'no'; }
    if(name==='ترجمه'||name==='translate'){ if(env.AI){ try{ var t=await env.AI.run(CF_TRANSLATE,{text:input,source_lang:'fa',target_lang:'en'}); if(t&&t.translated_text) return t.translated_text; }catch(e){} } var tr=await think(env,[{role:'user',content:'Translate to English:\n'+input}],{maxTokens:800}); return (tr&&tr.text)||'no'; }
    if(name==='ریاضی'||name==='math'||name==='calc'){ var m=evalMath(input); return m===null?'cannot':'= '+m; }
    if(name==='دانش_کاربر'||name==='rag'||name==='memory'){ var m2=await ragUserQuery(env,uid,input); return m2||'no'; }
    return 'unknown tool';
  }catch(e){ return 'error: '+(e.message||e); }
}
async function novaToolAgent(env, uid, chatId, question){
  var history=[]; try{ history = await getHistory(env, uid); }catch(e){}
  var scratch='';
  for(var step=0; step<4; step++){
    var raw = await novaAgentStep(env, uid, question, history, scratch);
    var t = String(raw).replace(/```json/gi,'').replace(/```/g,'').trim();
    var jStart=t.indexOf('{'), jEnd=t.lastIndexOf('}');
    if(jStart===-1||jEnd===-1){ break; }
    var obj; try{ obj=JSON.parse(t.slice(jStart,jEnd+1)); }catch(e){ scratch += '\nStep '+(step+1)+': invalid JSON '+t.slice(0,200); continue; }
    if(!obj.tool) continue;
    if(obj.tool==='پایان' || obj.tool==='final' || obj.tool==='finish'){
      return {ok:true, answer: String(obj.input||obj.answer||'پایان'), steps: step+1};
    }
    var out = await novaRunTool(env, uid, obj.tool, obj.input);
    scratch += '\nStep '+(step+1)+' ['+obj.tool+'] input='+(obj.input||'')+' -> '+(typeof out==='string'?out.slice(0,1200):'');
  }
  var fin = await think(env, [{role:'system',content:'از سوابق ابزار و سؤال کاربر، جواب نهایی فارسی و مفید بده.'},{role:'user',content:'سؤال: '+question+'\n\nسوابق:\n'+scratch}], {maxTokens:1500, timeout:30000});
  return {ok:true, answer:(fin&&fin.text)?fin.text:('نتونستم کامل حلش کنم. سوابق:\n'+scratch.slice(0,1500)), steps:4};
}

/* 2) پلاگین webhook */
async function plugListAll(env){ var l = await advKvGet(env,'plugins','json'); return Array.isArray(l)?l:[]; }
async function plugSave(env,l){ await advKvPut(env,'plugins', JSON.stringify(l.slice(0,50))); }
async function plugExecute(env, name, query){
  var l=await plugListAll(env);
  var p=l.filter(function(x){return x.name===name;})[0];
  if(!p) return '❌ پلاگین «'+name+'» نیست. لیست: /plug list';
  try{
    var method=(p.method||'POST').toUpperCase();
    var r = await fetch(p.url, {method:method, headers:Object.assign({'Content-Type':'application/json'}, p.headers||{}), body: method==='GET'?undefined:JSON.stringify({query:query, input:query})});
    var txt=await r.text();
    return '🔌 «'+name+'» پاسخ:\n'+txt.slice(0,3000);
  }catch(e){ return '❌ خطا در webhook: '+(e.message||e); }
}

/* 3) JS Interpreter */
async function novaRunJs(code){
  // SECURITY: JS interpreter disabled by default — use /run (Piston) instead.
  // To re-enable for trusted admins only, set FEATURES.codeExecJs = true AND pass admin check upstream.
  if (!FEATURES.codeExec || FEATURES.codeExecJs === false) {
    return '❌ مفسر JS داخلی غیرفعال است (امنیت). از /run js استفاده کنید (sandbox خارجی).';
  }
  code = String(code||'');
  var blocked = /\.fetch|\bfetch\b|\brequire\b|\bimport\b|\bprocess\b|\bglobalThis\b|\bglobal\b|\bwindow\b|\bself\b|\bdocument\b|WebSocket|XMLHttpRequest|importScripts|new\s+Worker|\bFunction\b|\beval\b|\bsetTimeout\b|\bsetInterval\b|\bProxy\b|\bReflect\b|\b__proto__\b|\bconstructor\b|\bprototype\b|\batob\b|\bbtoa\b|\bDeno\b|\bBun\b|\bcrypto\b|\bSubtleCrypto\b|\bSharedArrayBuffer\b|\bAtomics\b|\bWebAssembly\b|\bqueueMicrotask\b|\bFinalizationRegistry\b|\bthis\s*\[|\barguments\b|\bwith\s*\(/i;
  if(blocked.test(code)) return '❌ عبارات شبکه/سیستم/خطرناک در مفسر مجاز نیستند (sandbox).';
  if(code.length > 2000) return '❌ کد خیلی بلند است (حداکثر ۲۰۰۰ کاراکتر).';
  var logs=[];
  var fakeConsole={log:function(){logs.push([].slice.call(arguments).map(String).join(' ').slice(0,200)); if(logs.length>50) logs.shift();},warn:function(){logs.push('(warn) '+[].slice.call(arguments).map(String).join(' ').slice(0,200));},error:function(){logs.push('(err) '+[].slice.call(arguments).map(String).join(' ').slice(0,200));}};
  try{
    var fn = new Function('console', '"use strict"; return (async()=>{'+code+'\n})()');
    var res = await Promise.race([fn(fakeConsole), new Promise(function(r){setTimeout(function(){r('__TIMEOUT__');},3000);})]);
    if(res==='__TIMEOUT__') return '⏱ زمان اجرا تمام شد (۳ ثانیه).';
    return '📤 خروجی:\n'+(logs.length?logs.join('\n'):'(بدون console.log)')+'\n\n📥 نتیجه:\n'+String(res).slice(0,800);
  }catch(e){ return '❌ خطای JS: '+(e.message||e)+'\n\n(خروجی قبلی:\n'+(logs.join('\n')||'-')+')'; }
}

/* 4) Workflow */
async function flowListAll(env){ var l=await advKvGet(env,'flows','json'); return Array.isArray(l)?l:[]; }
async function flowSave(env,l){ await advKvPut(env,'flows', advJson(l.slice(0,100))); }
function parseFlowSchedule(s){
  s=String(s||'').toLowerCase();
  var m=s.match(/every\s*(\d+)\s*(m|min|h|d)/); if(m){ var n=parseInt(m[1],10),u=m[2]; return {kind:'every', ms:n*(u==='m'||u==='min'?60000:u==='h'?3600000:86400000)}; }
  if(/every day/.test(s)||/هر روز/.test(s)){ var t=s.match(/(\d{1,2})[:.](\d{2})/); return {kind:'daily', hour:t?parseInt(t[1],10):8, minute:t?parseInt(t[2],10):0}; }
  if(/every hour/.test(s)||/هر ساعت/.test(s)) return {kind:'hourly'};
  return null;
}
async function novaRunWorkflows(env){
  if(!env.BOT_KV) return 0;
  var list=await flowListAll(env); if(!list.length) return 0;
  var now=Date.now(); var fired=0;
  for(var i=0;i<list.length;i++){
    var f=list[i]; if(f.paused) continue;
    var due=false;
    if(f.sched==='every'){ if(!f.next || f.next<=now) due=true; }
    else if(f.sched==='hourly'){ var h=Math.floor(now/3600000); due=!f.lastFiredHour || f.lastFiredHour!==h; }
    else if(f.sched==='daily'){ var d=new Date(now); var todayKey=d.toISOString().slice(0,10); var slot=new Date(); slot.setHours(f.hour,f.minute,0,0); if(slot.getTime()<=now && f.lastFired!==todayKey) due=true; }
    if(!due) continue;
    var chatId=String(f.chatId||'').replace(/^tg_/,'');
    if(!chatId || !env.TELEGRAM_BOT_TOKEN) continue;
    try{
      if(f.task && f.task.indexOf('run:')===0){
        var cmd=f.task.slice(4).trim();
        if(cmd.charAt(0)!=='/') cmd='/'+cmd;
        await tgProcessText(env, f.uid, chatId, cmd, f.name||'flow');
      }else{
        await tg(env,'sendMessage',{chat_id:chatId, text:'⏰ Workflow: '+(f.task||'')});
      }
      fired++;
      if(f.sched==='daily') f.lastFired=new Date(now).toISOString().slice(0,10);
      else if(f.sched==='hourly') f.lastFiredHour=Math.floor(now/3600000);
      else f.next = now + f.ms;
      f.lastRun=now;
    }catch(e){}
  }
  if(fired) await flowSave(env,list);
  return fired;
}

/* 5) پیشنهاد سوال بعدی */
async function novaSuggestions(env, uid, lastQuestion, lastAnswer){
  var q=String(lastQuestion||'').slice(0,1500), a=String(lastAnswer||'').slice(0,2000);
  var r = await think(env,[
    {role:'system',content:'از سوال و جواب کاربر، سه پیشنهاد پرسش بعدی کوتاه و مرتبط به فارسی بده. فقط یک JSON بده: {"suggestions":["...","...","..."]}. بدون markdown.'},
    {role:'user',content:'سوال: '+q+'\n\nجواب: '+a}
  ],{maxTokens:400, timeout:20000});
  if(!r||!r.text) return [];
  var t=String(r.text).replace(/```json/gi,'').replace(/```/g,'').trim();
  var s=t.indexOf('{'), e=t.lastIndexOf('}'); if(s===-1||e===-1) return [];
  try{ var o=JSON.parse(t.slice(s,e+1)); return (o.suggestions||[]).slice(0,3); }catch(e2){return [];}
}
async function novaSendSuggestions(env, chatId, uid, lastQuestion, lastAnswer){
  var sugs = await novaSuggestions(env, uid, lastQuestion, lastAnswer);
  if(!sugs.length) return;
  var kb=[];
  for(var i=0;i<sugs.length;i++){
    var id=advId('sg'); await advKvPut(env,'sug_'+id+'_'+uid, JSON.stringify({text:sugs[i], chatId:chatId}), 86400*3);
    kb.push([{text: '💡 '+sugs[i].slice(0,60), callback_data:'sug:'+id}]);
  }
  try{ await tg(env,'sendMessage',{chat_id:chatId, text:'💡 ادامه احتمالی:', reply_markup:{inline_keyboard:kb}}); }catch(e){}
}

async function novaAdvancedTick(env){
  try{ var n=await novaRunWorkflows(env); if(n) try{ await notifyAdmins(env,'Workflow: '+n+'ون اجرا شد'); }catch(e){} }catch(eA){ try{ await notifyAdmins(env,'❌ advanced cron: '+(eA.message||eA)); }catch(e2){} }
}

async function novaAdvancedHandle(env, uid, chatId, text, name){
  var t = String(text||'').trim();
  var low=t.toLowerCase();
  if(/^\/(agent|ایجنت|ایجنت)\b/i.test(t)){
    var q=t.replace(/^\/\S+\s*/,'').trim();
    if(!q){ await tgReply(env,chatId,'🧠 نمونه: /agent قیمت بیت‌کوین را بگیر و با کد تحلیل کن'); return true; }
    try{ await tg(env,'sendChatAction',{chat_id:chatId,action:'typing'}); }catch(e){}
    var ar = FEATURES.realAgent ? await novaRealAgent(env,uid,chatId,q) : await novaToolAgent(env,uid,chatId,q);
    var agentText = (ar && (ar.ok!==false) && (ar.text || ar.answer)) ? (ar.text || ar.answer) : '';
    if (!agentText) {
      await tgReply(env,chatId, '❌ '+(ar && ar.error || 'agent failed'));
      return true;
    }
    await tgReplyWithCodeFiles(env, chatId, agentText, '');
    return true;
  }
  if(/^\/(plug|plugin|ابزار)\b/i.test(t)){
    var body=t.replace(/^\/\S+\s*/,'').trim();
    var isAdm = (typeof getUserRole==='function') ? (await getUserRole(env,uid))==='admin' : false;
    var parts=body.split(/\s+/);
    var sub=(parts.shift()||'list').toLowerCase();
    if(sub==='list' || sub==='ls' || sub==='' ){ var l=await plugListAll(env); if(!l.length){ await tgReply(env,chatId,'🔌 پلاگینی نیست. افزودن (ادمین): /plug add name https://example.com/hook'); return true; } var lines=['🔌 پلاگین‌ها:']; l.forEach(function(p,i){lines.push((i+1)+'. '+p.name+' → '+p.url);}); await tgReply(env,chatId,lines.join('\n')); return true; }
    if(sub==='add'){ if(!isAdm){ await tgReply(env,chatId,'⛔ فقط ادمین می‌تواند پلاگین اضافه کند.'); return true; } var nm=parts.shift(); var url=parts.shift(); var method=(parts.shift()||'POST'); if(!nm||!url){ await tgReply(env,chatId,'فرمت: /plug add NAME URL [METHOD]'); return true; } var l2=await plugListAll(env); l2.push({name:nm,url:url,method:method,ts:Date.now()}); await plugSave(env,l2); await tgReply(env,chatId,'✅ پلاگین «'+nm+'» اضافه شد. اجرا: /plug run '+nm+' <سوال>'); return true; }
    if(sub==='del'||sub==='rm'||sub==='delete'){ if(!isAdm){ await tgReply(env,chatId,'⛔ فقط ادمین.'); return true; } var nm2=parts.shift(); var l3=await plugListAll(env); var bef=l3.length; l3=l3.filter(function(p){return p.name!==nm2;}); await plugSave(env,l3); await tgReply(env,chatId,l3.length===bef?'❌ نیست.':'🗑️ حذف شد.'); return true; }
    if(sub==='run'){ var nm3=parts.shift(); var query=parts.join(' ').trim(); if(!nm3||!query){ await tgReply(env,chatId,'فرمت: /plug run NAME query'); return true; } await tgReply(env,chatId, await plugExecute(env,nm3,query)); return true; }
    var direct=sub; var directQ=parts.join(' ').trim();
    await tgReply(env,chatId, await plugExecute(env,direct,directQ||'')); return true;
  }
  if(/^\/(js|runjs|evaljs|codejs)\b/i.test(t)){
    var code=t.replace(/^\/\S+\s*/,'').trim();
    if(!code){ await tgReply(env,chatId,'🧮 نمونه: /js console.log([1,2,3].reduce((a,b)=>a+b,0))'); return true; }
    try{ await tg(env,'sendChatAction',{chat_id:chatId,action:'typing'}); }catch(e){}
    await tgReply(env,chatId, await novaRunJs(code)); return true;
  }
  if(/^\/(run|exec|code|پایتون|python)\b/i.test(t) && !/^\/(runjs)/i.test(t)){
    var raw=t.replace(/^\/\S+\s*/,'').trim();
    if(!raw){ await tgReply(env,chatId,'💻 اجرای واقعی کد (Piston):\n/run python\nprint(2+2)\n\n/run js\nconsole.log(1+1)'); return true; }
    var lang='python', code=raw;
    var lines=raw.split('\n');
    var first=(lines[0]||'').trim().toLowerCase();
    if(/^(python|py|js|javascript|node|ts|typescript|c|cpp|java|go|rust|ruby|php|bash|r)\b/.test(first) && lines.length>1){
      lang=first.split(/\s+/)[0]; code=lines.slice(1).join('\n');
    } else {
      var mm=raw.match(/^```(\w+)\n([\s\S]*?)```/);
      if(mm){ lang=mm[1]; code=mm[2]; }
    }
    try{ await tg(env,'sendChatAction',{chat_id:chatId,action:'typing'}); }catch(e){}
    var ex=await novaExecCode(lang, code);
    await tgReply(env,chatId, ex.ok ? ('✅ '+ex.language+'\n\n'+ex.text) : ('❌ '+ex.error));
    return true;
  }
  if(/^\/(flow|workflow|اتوماسیون)\b/i.test(t)){
    var b=t.replace(/^\/\S+\s*/,'').trim();
    if(/^(list|ls)$/i.test(b) || b===''){ var fl=await flowListAll(env); var mine=fl.filter(function(f){return f.uid===uid;}); if(!mine.length){ await tgReply(env,chatId,'⏰ Workflow: هنوز هیچ.\nنمونه: /flow every day 8:00 run:/crypto\nیا: /flow every 30m متن نوتیف'); return true; } var ls=['⏰ Workflow های شما:']; mine.forEach(function(f,i){ls.push((i+1)+'. ['+(f.sched)+ ((f.hour!==undefined)?' '+f.hour+':'+(f.minute||0):'')+'] '+(f.task||'')+' — 🆔 '+f.id);}); await tgReply(env,chatId,ls.join('\n')+'\n\nحذف: /flowdel ID'); return true; }
    if(/^(del|delete|rm)$/i.test((b.split(/\s+/)[0]||''))){ var did=b.split(/\s+/)[1]; if(!did){ await tgReply(env,chatId,'فرمت: /flowdel ID'); return true; } var fl2=await flowListAll(env); var bef2=fl2.length; fl2=fl2.filter(function(f){return !(f.uid===uid && f.id===did);}); await flowSave(env,fl2); await tgReply(env,chatId,fl2.length===bef2?'❌ نیست.':'🗑️ حذف شد.'); return true; }
    var m=b.match(/^(.*?)\s+(.*)$/);
    if(!m){ await tgReply(env,chatId,'فرمت: /flow <schedule> <text|run:comando>'); return true; }
    var sched=null; var taskPart=null;
    sched=parseFlowSchedule(m[1]);
    if(sched){ taskPart=m[2]; }
    else{
      var parts=b.split(/\s+/);
      for(var cut=2; cut<=Math.min(parts.length,4); cut++){ var cand=parts.slice(0,cut).join(' '); sched=parseFlowSchedule(cand); if(sched){ taskPart=parts.slice(cut).join(' '); break; } }
    }
    if(!sched){ await tgReply(env,chatId,'❌ برنامه را نفهمیدم. نمونه: /flow every day 8:00 run:/crypto  یا  /flow every 30m متن'); return true; }
    if(!taskPart){ await tgReply(env,chatId,'✅ متن یا run: را بنویس.'); return true; }
    var list3=await flowListAll(env);
    list3.push({id:advId('fl'), uid:uid, chatId:chatId, sched:sched.kind, ms:sched.ms||0, hour:sched.hour, minute:sched.minute, task:taskPart, ts:Date.now()});
    await flowSave(env,list3);
    await tgReply(env,chatId,'⏰ Workflow ذخیره شد.\nزمان: '+JSON.stringify(sched)+'\nکار: '+taskPart+'\n\nلیست: /flowlist');
    return true;
  }
  if(/^\/(suggest|پیشنهاد)\b/i.test(t)){
    var lastQ='', lastA='';
    try{ var h=await getHistory(env,uid); var u=h.filter(function(m){return m.role==='user';}); var a=h.filter(function(m){return m.role==='assistant';}); lastQ=(u.length?String(u[u.length-1].content||u[u.length-1].text||''):''); lastA=(a.length?String(a[a.length-1].content||a[a.length-1].text||''):''); }catch(e2){}
    if(!lastQ){ await tgReply(env,chatId,'هنوز گفتگویی نیست.'); return true; }
    try{ await tg(env,'sendChatAction',{chat_id:chatId,action:'typing'}); }catch(e){}
    await novaSendSuggestions(env,chatId,uid,lastQ,lastA);
    return true;
  }

  if(/^\/(imgedit|img2img|ویرایش\s*عکس)\b/i.test(t)){
    await tgReply(env,chatId,'🖼️ ویرایش تصویر:\nعکس را بفرست و در کپشن بنویس:\nویرایش: توضیح تغییرات\nیا ریپلای روی عکس با /imgedit توضیح');
    return true;
  }
  return false;
}


