/** صف ساده درخواست‌ها در KV (برای ترافیک بالا) */
async function novaEnqueue(env, uid, payload) {
  if (!FEATURES.requestQueue || !env.BOT_KV) return null;
  var qid = 'q_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  var item = { id: qid, uid: uid, payload: payload, ts: Date.now(), status: 'pending' };
  try {
    var q = (await env.BOT_KV.get('req_queue', 'json')) || [];
    if (!Array.isArray(q)) q = [];
    q.push(item);
    if (q.length > 200) q = q.slice(-200);
    await env.BOT_KV.put('req_queue', JSON.stringify(q));
    return qid;
  } catch (e) { return null; }
}

async function novaDequeueNext(env) {
  if (!env.BOT_KV) return null;
  try {
    var q = (await env.BOT_KV.get('req_queue', 'json')) || [];
    if (!Array.isArray(q) || !q.length) return null;
    var item = q.shift();
    await env.BOT_KV.put('req_queue', JSON.stringify(q));
    return item;
  } catch (e) { return null; }
}

/**
 * Streaming واقعی از API سازگار با OpenAI (SSE)
 * توکن‌ها را می‌گیرد و پیام تلگرام را تدریجی ویرایش می‌کند.
 */
async function callExternalStreamToTelegram(env, chatId, messages, opts) {
  opts = opts || {};
  if (!FEATURES.realStream) return null;
  var provs = (opts.onlyUserKeys && opts.userId)
    ? await collectKeys(env, opts.userId)
    : await collectKeys(env);
  var pid = opts.provider;
  if (!pid) {
    var order = ['apx', 'groq', 'openrouter', 'gemini', 'google_studio', 'cerebras', 'openai', 'xai'];
    for (var i = 0; i < order.length; i++) if (provs[order[i]]) { pid = order[i]; break; }
  }
  var prov = provs[pid];
  if (!prov || !prov.keys || !prov.keys.length) return null;
  var model = opts.model || await pickModel(env, pid, 'text');
  if (!model) return null;
  var key = (typeof prov.keys[0] === 'string') ? prov.keys[0] : (prov.keys[0] && prov.keys[0].key) || prov.keys[0];
  if (typeof key === 'object') key = key.key;
  var base = String(normalizeGeminiBase(prov.base, key) || prov.base || '').replace(/\/+$/, '');
  if (!base) return null;
  var url = base + '/chat/completions';
  var headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + key,
    'User-Agent': 'Mozilla/5.0 NovaAI/26'
  };
  if (pid === 'openrouter') {
    headers['HTTP-Referer'] = 'https://openrouter.ai';
    headers['X-Title'] = 'Nova AI';
  }

  var placeholder = '🧠 Nova در حال فکر کردن...\n▌';
  var sent;
  try {
    sent = await tgSendSafe(env, 'sendMessage', { chat_id: chatId, text: placeholder }, 1);
  } catch (e) { return null; }
  if (!sent || !sent.ok || !sent.result || !sent.result.message_id) return null;
  var msgId = sent.result.message_id;

  var body = {
    model: model,
    messages: messages,
    max_tokens: opts.maxTokens || 2048,
    temperature: opts.temperature !== undefined ? opts.temperature : 0.65,
    stream: true
  };

  var full = '';
  var lastEdit = 0;
  var streamOk = false;
  var ac = null;
  var streamTimer = null;
  try {
    ac = typeof AbortController !== 'undefined' ? new AbortController() : null;
    if (ac) streamTimer = setTimeout(function () { try { ac.abort(); } catch (eA) {} }, 42000);
    var r = await fetch(url, { method: 'POST', headers: headers, body: JSON.stringify(body), signal: ac ? ac.signal : undefined });
    if (!r.ok || !r.body) {
      var et = '';
      try { et = await r.text(); } catch (e2) {}
      var errCombo = String(r.status) + ' ' + String(et || '');
      var billing = isBillingOrQuotaError(errCombo) || r.status === 402 || r.status === 403;
      try {
        if (billing) {
          await markProviderQuotaFail(env, pid, model, et);
          // پیام فنی به کاربر نشان نده — فقط «در حال مدل جایگزین»
          try {
            await tg(env, 'editMessageText', {
              chat_id: chatId, message_id: msgId,
              text: '⏳ اعتبار این مدل/سرویس تمام است — در حال تلاش با مدل دیگر…'
            });
          } catch (eBill) {}
        } else {
          try {
            await tg(env, 'editMessageText', {
              chat_id: chatId, message_id: msgId,
              text: '⏳ استریم قطع شد — ادامه با روش عادی…'
            });
          } catch (eSoft) {}
        }
      } catch (e3) {}
      // پیام placeholder را پاک نکن؛ مسیر عادی بعداً جواب می‌دهد و این پیام می‌ماند مگر حذف کنیم
      try { await tg(env, 'deleteMessage', { chat_id: chatId, message_id: msgId }); } catch (eDel) {}
      return {
        error: 'stream ' + r.status + ': ' + String(et).slice(0, 180),
        model: model,
        providerName: prov.name,
        billing: billing,
        streamFailed: true
      };
    }
    var reader = r.body.getReader();
    var dec = new TextDecoder();
    var buf = '';
    var streamStart = Date.now();
    while (true) {
      if (Date.now() - streamStart > 40000) break;
      var chunk = await reader.read();
      if (chunk.done) break;
      buf += dec.decode(chunk.value, { stream: true });
      var lines = buf.split('\n');
      buf = lines.pop() || '';
      for (var li = 0; li < lines.length; li++) {
        var line = lines[li].trim();
        if (!line || line.indexOf('data:') !== 0) continue;
        var data = line.slice(5).trim();
        if (data === '[DONE]') continue;
        try {
          var j = JSON.parse(data);
          var delta = j.choices && j.choices[0] && j.choices[0].delta && j.choices[0].delta.content;
          if (!delta && j.choices && j.choices[0] && j.choices[0].text) delta = j.choices[0].text;
          if (delta) {
            full += delta;
            streamOk = true;
            var now = Date.now();
            if (now - lastEdit > 450 || full.length < 40) {
              lastEdit = now;
              try {
                await tg(env, 'editMessageText', {
                  chat_id: chatId, message_id: msgId,
                  text: (full + '▌').slice(0, 4090)
                });
              } catch (eEdit) {}
            }
          }
        } catch (pe) {}
      }
    }
  } catch (eStream) {
    return { error: 'stream: ' + (eStream.message || eStream), model: model, providerName: prov.name };
  }

  if (streamTimer) try { clearTimeout(streamTimer); } catch (eT) {}
  if (!streamOk || !full.trim()) {
    // اگر چیزی آمده بود همان را نگه دار
    if (full.trim()) {
      try {
        await tg(env, 'editMessageText', {
          chat_id: chatId, message_id: msgId,
          text: (full + '\n\n— 🤖 ' + model + (prov.name ? ' · ' + prov.name : '')).slice(0, 4090)
        });
      } catch (eP) {}
      return { text: full, model: model, providerName: prov.name, streamed: true };
    }
    try { await tg(env, 'deleteMessage', { chat_id: chatId, message_id: msgId }); } catch (eE) {}
    return { error: 'stream empty', model: model, providerName: prov.name, streamFailed: true };
  }
  var footer = '\n\n— 🤖 ' + model + (prov.name ? ' · ' + prov.name : '');
  try {
    await tg(env, 'editMessageText', {
      chat_id: chatId, message_id: msgId,
      text: (full + footer).slice(0, 4090)
    });
  } catch (eF) {}
  return { text: full, model: model, providerName: prov.name, streamed: true };
}

/**
 * اجرای واقعی کد با Piston (چندزبانه: python, js, c, ...)
 * https://emkc.org/api/v2/piston
 */
async function novaExecCode(lang, code, stdin) {
  lang = String(lang || 'python').toLowerCase().trim();
  var map = {
    py: 'python', python: 'python', python3: 'python',
    js: 'javascript', javascript: 'javascript', node: 'javascript',
    ts: 'typescript', typescript: 'typescript',
    c: 'c', cpp: 'c++', 'c++': 'c++', java: 'java',
    go: 'go', rust: 'rust', rb: 'ruby', ruby: 'ruby',
    php: 'php', sh: 'bash', bash: 'bash', r: 'r'
  };
  var language = map[lang] || lang;
  try {
    var r = await fetchT('https://emkc.org/api/v2/piston/execute', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        language: language,
        version: '*',
        files: [{ content: String(code || '') }],
        stdin: String(stdin || ''),
        run_timeout: 10000
      })
    }, 20000);
    var t = await r.text();
    var j;
    try { j = JSON.parse(t); } catch (e) { return { ok: false, error: 'پاسخ نامعتبر از sandbox' }; }
    if (!r.ok) return { ok: false, error: (j && j.message) || ('HTTP ' + r.status) };
    var run = j.run || {};
    var out = String(run.stdout || '');
    var err = String(run.stderr || '');
    var codeExit = run.code;
    var text = '';
    if (out) text += '📤 خروجی:\n' + out.slice(0, 3500);
    if (err) text += (text ? '\n\n' : '') + '⚠️ stderr:\n' + err.slice(0, 1500);
    if (!text) text = '(بدون خروجی) exit=' + codeExit;
    return { ok: true, text: text, language: language, exit: codeExit };
  } catch (e) {
    return { ok: false, error: e.message || String(e) };
  }
}

/**
 * ویرایش / تغییر تصویر با Workers AI (text-guided)
 * کاربر عکس + دستور می‌فرستد.
 */
async function novaImageEdit(env, imageBytes, prompt) {
  if (!FEATURES.imageEdit || !env.AI) return { ok: false, error: 'Workers AI در دسترس نیست' };
  prompt = String(prompt || 'improve this image').slice(0, 500);
  // مدل‌های img2img / edit رایج CF (ترتیب تلاش)
  var models = [
    '@cf/runwayml/stable-diffusion-v1-5-img2img',
    '@cf/stabilityai/stable-diffusion-xl-base-1.0',
    '@cf/black-forest-labs/flux-1-schnell'
  ];
  var lastErr = '';
  for (var i = 0; i < models.length; i++) {
    try {
      var input = { prompt: prompt };
      // img2img expects image as array of bytes sometimes
      if (models[i].indexOf('img2img') !== -1 && imageBytes) {
        input.image = Array.from(new Uint8Array(imageBytes));
        input.strength = 0.75;
      }
      var res = await env.AI.run(models[i], input);
      var bytes = null;
      if (res instanceof ArrayBuffer) bytes = res;
      else if (res && res.image) {
        // base64
        var b64 = String(res.image).replace(/^data:image\/\w+;base64,/, '');
        var bin = atob(b64);
        var arr = new Uint8Array(bin.length);
        for (var j = 0; j < bin.length; j++) arr[j] = bin.charCodeAt(j);
        bytes = arr.buffer;
      }
      if (bytes) return { ok: true, bytes: bytes, model: models[i], mime: 'image/png' };
      lastErr = models[i] + ': empty';
    } catch (e) {
      lastErr = models[i] + ': ' + (e.message || e);
    }
  }
  return { ok: false, error: lastErr || 'image edit failed' };
}

/** Agent واقعی با tools (OpenAI-style) + fallback به JSON چندمرحله‌ای */
async function novaRealAgent(env, uid, chatId, question) {
  var tools = [
    { type: 'function', function: { name: 'web_search', description: 'جستجوی وب برای اطلاعات روز', parameters: { type: 'object', properties: { query: { type: 'string' } }, required: ['query'] } } },
    { type: 'function', function: { name: 'run_code', description: 'اجرای کد در sandbox', parameters: { type: 'object', properties: { language: { type: 'string' }, code: { type: 'string' } }, required: ['language', 'code'] } } },
    { type: 'function', function: { name: 'crypto_price', description: 'قیمت ارز دیجیتال', parameters: { type: 'object', properties: { symbol: { type: 'string' } }, required: ['symbol'] } } },
    { type: 'function', function: { name: 'remember', description: 'ذخیره نکته در حافظه کاربر', parameters: { type: 'object', properties: { note: { type: 'string' } }, required: ['note'] } } }
  ];
  var messages = [
    { role: 'system', content: 'تو یک Agent هستی. از ابزارها وقتی لازم است استفاده کن. جواب نهایی را به فارسی بده.' },
    { role: 'user', content: String(question || '') }
  ];
  var provs = await collectKeys(env);
  var tryOrder = ['apx', 'openai', 'groq', 'openrouter', 'gemini'];
  var lastErr = '';
  for (var pi = 0; pi < tryOrder.length; pi++) {
    var pid = tryOrder[pi];
    if (!provs[pid]) continue;
    var model = await pickModel(env, pid, 'text');
    if (!model) continue;
    var keyObj = provs[pid].keys[0];
    var key = (typeof keyObj === 'string') ? keyObj : (keyObj && keyObj.key) || keyObj;
    var base = String(provs[pid].base || '').replace(/\/+$/, '');
    try {
      for (var step = 0; step < 5; step++) {
        var r = await fetchT(base + '/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + key
          },
          body: JSON.stringify({
            model: model,
            messages: messages,
            tools: tools,
            tool_choice: 'auto',
            max_tokens: 2000
          })
        }, 45000);
        var et = await r.text();
        if (!r.ok) { lastErr = pid + ' ' + r.status + ': ' + et.slice(0, 120); break; }
        var j = JSON.parse(et);
        var msg = j.choices && j.choices[0] && j.choices[0].message;
        if (!msg) { lastErr = 'empty message'; break; }
        messages.push(msg);
        var tcalls = msg.tool_calls;
        if (!tcalls || !tcalls.length) {
          var finalText = msg.content || '';
          if (finalText) return { ok: true, text: finalText, model: model, providerName: provs[pid].name };
          break;
        }
        for (var ti = 0; ti < tcalls.length; ti++) {
          var tc = tcalls[ti];
          var fn = tc.function || {};
          var fname = fn.name || '';
          var args = {};
          try { args = JSON.parse(fn.arguments || '{}'); } catch (eA) {}
          var toolResult = '';
          if (fname === 'run_code') {
            var ex = await novaExecCode(args.language || 'python', args.code || '');
            toolResult = ex.ok ? ex.text : ('خطا: ' + ex.error);
          } else if (fname === 'crypto_price') {
            try {
              var sym = String(args.symbol || 'BTC').toUpperCase();
              var cr = await fetchT('https://api.binance.com/api/v3/ticker/price?symbol=' + sym + 'USDT', {}, 8000);
              var cj = await cr.json();
              toolResult = sym + ' ≈ ' + (cj.price || '?') + ' USDT';
            } catch (eC) { toolResult = 'خطا در قیمت'; }
          } else if (fname === 'remember') {
            try {
              await touchUserMemory(env, uid, 'یادداشت: ' + (args.note || ''));
              toolResult = 'ذخیره شد';
            } catch (eR) { toolResult = 'خطا در حافظه'; }
          } else if (fname === 'web_search') {
            toolResult = 'جستجو: ' + (args.query || '') + ' — از دانش مدل استفاده کن.';
          } else {
            toolResult = 'ابزار ناشناخته';
          }
          messages.push({
            role: 'tool',
            tool_call_id: tc.id,
            content: toolResult
          });
        }
      }
    } catch (e) {
      lastErr = pid + ': ' + (e.message || e);
    }
  }
  // fallback: agent قدیمی
  try {
    var old = await novaToolAgent(env, uid, chatId, question);
    var ans = old && (old.text || old.answer);
    if (ans) {
      return {
        ok: true,
        text: ans,
        model: (old && old.model) || 'agent',
        providerName: 'Agent-fallback'
      };
    }
  } catch (e2) {}
  return { ok: false, error: lastErr || 'agent failed' };
}



